window.JASTROW_CHUNKS[72]={"28800":{"h":"קַנִּשְׁרַיָּא","r":"S01618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵן\">קֵן</a> ch.</div>","alt":[]},"28801":{"h":"קְנָת","r":"S01619","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Kenath</i>, on the east of the Jordan (v. Hildesh. Beitr., p. 49 sq.). <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> (not <a href=\"#\" data-headword=\"קנח\">קנח</a>); <span class=\"citation\">Tosef. Shebi. IV, 11</span> (v. ed. Zuck. note); <span class=\"citation\">Sifré Deut. 51</span>; <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">יינקת</span> (corr. acc., or <a href=\"#\" data-headword=\"קוּנְתְּיָה\">קוּנְתְּיָיה</a>).</div>","alt":[]},"28802":{"h":"קֶנֶת","r":"S01620","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָנַן\">קָנַן</a>; cmp. <a href=\"#\" data-headword=\"קַנְקָן I\"><span dir=\"rtl\">קַנְקַן</span> I</a>) [<i>that which is inserted</i>,] <i>handle, helve</i>. <span class=\"citation\">Macc. II, 1</span> מקַנְתּוֹ Ar. (or <span dir=\"rtl\">מקַנָּתוֹ</span> fr. <a href=\"#\" data-headword=\"קָנָה\">קַנָּה</a>; ed. <span dir=\"rtl\">מקַתּוֹ</span>, v. <a href=\"#\" data-headword=\"קַתְּ\">קַתְּ</a>).—Pl. <a href=\"#\" data-headword=\"קַנְתּוֹר\">קַנְתּוֹת</a>. Y’lamd. to Lev. XIX quot. in Ar. <span dir=\"rtl\">ק׳ של רמחים וכ׳</span> handles of spears and knives.—[<span class=\"citation\">Kel. XV, 1</span> R. S. Vers., v. <a href=\"#\" data-headword=\"קִיסְטָא II\">קִיסְטָה</a>.]</div>","alt":[]},"28803":{"h":"קַנְתָּא","r":"S01621","html":"<div class=\"sense\"> Y. Naz. I, 51ᵇ <span dir=\"rtl\">אורהיה … ק׳ דכולבא וכ׳</span> man is in the habit of saying, ‘the handle of an axe’; does any one say, ‘the axe of the handle’?, i.e. in making a vow one begins with the word <a href=\"#\" data-headword=\"שְׁבוּעָה\">שבועה</a>, but does not place it at the end; <span class=\"citation\">Y. Ned. II, 36ᵈ</span> top.—V. <a href=\"#\" data-headword=\"קַתָּא\">קַתָּא</a></div>","alt":["קַנְתָּה"]},"28804":{"h":"קַנְתּוֹר","r":"S01622","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַנְטָר\">קַנְטָר</a></div>","alt":[]},"28805":{"h":"קִנְתּוּר","r":"S01623","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִינְטוּר\">קִינְטוּר</a></div>","alt":[]},"28806":{"h":"(קנתור)","r":"S01624","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִנְטִינָר\">קִנְטִינָר</a></div>","alt":["קִנְתִּינַר","קִנְתֵּיר"]},"28807":{"h":"קַנְתֵּל","r":"S01625","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κανθήλια, pl.) <i>the pannier on the side of the pack-saddle, large basket</i>. <span class=\"citation\">Par. XII, 9</span> <span dir=\"rtl\">הסלים שבק׳</span> the baskets in the pannier.</div>","alt":[]},"28808":{"h":"קַנָּתָנִית","r":"S01626","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִנְאָנִית\">קַנְּאָנִית</a></div>","alt":[]},"28809":{"h":"קִנְתֵּר","r":"S01627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִנְטֵר\">קִנְטֵר</a>, <a href=\"#\" data-headword=\"קַנְטֵר\"><a href=\"#\" data-headword=\"קַנְטֵר\">קַנְטֵר</a>.</a></div>","alt":["קַנְתֵּר"]},"28810":{"h":"קַנְתְּרוֹס","r":"S01628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַתְרוֹס III\"><span dir=\"rtl\">קַתְרוֹס</span> III</a></div>","alt":[]},"28811":{"h":"קַנְתְּרִין","r":"S01629","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִינְטוּר\">קִינְטוּר</a></div>","alt":[]},"28812":{"h":"קַנְתְּרָן","r":"S01630","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַנְטְרָן\">קַנְטְרָן</a></div>","alt":[]},"28813":{"h":"קֵסָא","r":"S01631","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵיסָא\">קֵיסָא</a></div>","alt":[]},"28814":{"h":"קְסָאוֹת","r":"S01632","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִסְוָה\">קִסְוָה</a></div>","alt":[]},"28815":{"h":"קִסְבָּא","r":"S01633","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִשְׁבָּא\">קִשְׁבָּא</a></div>","alt":[]},"28816":{"h":"קַסְגַּלְגָס","r":"S01634","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳasgalgas</i>, a contraction of <i>Caius Caligula</i>, the Roman emperor. <span class=\"citation\">Tosef. Sot. XIII, 6</span> ed. Zuck. (Var. <span dir=\"rtl\">גס קלגוס</span>, <span dir=\"rtl\">גסקלנוס</span>), v. <a href=\"#\" data-headword=\"גַּיּוּס\">גַּיּוּס</a>.</div>","alt":[]},"28817":{"h":"קַסְדָּא","r":"S01635","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cassis, -idis) <i>casque, helmet</i>. <span class=\"citation\">Sabb. VI, 2</span> (expl. <span class=\"citation\">ib. 62ᵃ</span> <a href=\"#\" data-headword=\"סַנְוַורְתָּא\">סַנְוַורְתָּא</a>). <span class=\"citation\">Kel. XI, 8</span> (Ar. ed. Koh. <span dir=\"rtl\">קַסִּידָא</span>). <span class=\"citation\">Tosef. Kel. B. Mets. III, 1</span>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">כדי ללבוש ק׳ ושריון וכ׳</span> strong enough to wear helmet, mail and (carry) arms.—Pl. <span dir=\"rtl\">קַסִּידִין</span>. Y’lamd. to Gen. III, 22, quot. in Ar. (ref. to <span dir=\"rtl\">כרבלתהון</span>) <span dir=\"rtl\">אלו הק׳</span> that means the helmets.</div>","alt":["קַסְדָּה"]},"28818":{"h":"קִסְדּוֹר","r":"S01636","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּסְדֹּור\">קוּסְדּוֹר</a></div>","alt":[]},"28819":{"h":"קַסְוָא","r":"S01637","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסְוָוא\">קַסְוָוא</a></div>","alt":[]},"28820":{"h":"קִסְוָה","r":"S01638","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>marked measure</i>, esp. <i>vessel for libation</i>. <span class=\"citation\">Snh. IX, 6</span> <span dir=\"rtl\">הגונב את הק׳</span> (Y. ed. <span dir=\"rtl\">הקסווא</span>) if one steals the <i>ḳisvah</i>, expl. ib. 81ᵇ <span dir=\"rtl\">מאי ק׳ כלי שרת</span> (Ms. M. <a href=\"#\" data-headword=\"קִיסְוָוא\">קיסווא</a>) <i>ḳ</i>. means service vessels (ref. to <span class=\"citation\">Num. IV, 7</span>); Y. ib. IX, end, 27ᵇ, v. <a href=\"#\" data-headword=\"קִיסְטָא II\"><span dir=\"rtl\">קִיסְטָא</span> II</a>. Bab. ib. 82ᵇ. <span class=\"citation\">Tosef. Zeb. I, 12</span> <span dir=\"rtl\">היין שניסכו בקיסוא וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">בקסווה</span>) if wine for libation was poured into the <i>ḳ</i>. and thence into a <i>hin</i> measure.—Pl. <span dir=\"rtl\">קִסְוָואוֹת</span>, <span dir=\"rtl\">קִשְׂוָו׳</span>. <span class=\"citation\">Succ. 48ᵇ</span> <span dir=\"rtl\">שני קס׳ וכ׳</span> (sub. <span dir=\"rtl\">מיני</span>) ed. Pes. a. oth. (Ms. M. 1 <a href=\"#\" data-headword=\"קִשְׂוָא\">קִשְׂוָא׳</a>; Ms. M. 2 <a href=\"#\" data-headword=\"קְסָאוֹת\">קְסָאוֹת</a>; ed. <span dir=\"rtl\">קשוו׳</span>) two sets of bowls were there, one for water, and one for wine libations.</div>","alt":["קִסְוָוא"]},"28821":{"h":"קַסְוָוא","r":"S01639","html":"<div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"קַבְוָותָא\">קַסְוָותָא</a>, <a href=\"#\" data-headword=\"קַסְוָא\">קַסְוָ׳</a>, <a href=\"#\" data-headword=\"קַסְוָוא\">קַשְׂ׳</a>. <span class=\"citation\">Targ. O. Ex. XXV, 29</span> (Y. <a href=\"#\" data-headword=\"קַסְוָוא\">קַשְׂ׳</a>). Ib. XXXVII, 16. <span class=\"citation\">Targ. O. Num. IV, 7</span> <span dir=\"rtl\">קַסְוַת</span> constr. ed. Berl. (oth. ed. a. Yer. <span dir=\"rtl\">קַסְווֹת</span>). <span class=\"citation\">Targ. I Chr. XXVIII, 17</span>.</div>","alt":["קַשְׂ׳"]},"28822":{"h":"*קַסְוֵי","r":"S01640","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַסְוָוא\">preced.</a>) a certain <i>measure</i>. <span class=\"citation\">Ber. 44ᵇ</span> Men. Hammaor ch. III, Ner 6, K’lal 1, Ḥeleḳ. 1, s. 3 (ed. <span dir=\"rtl\">קַיְיסֵי</span>).</div>","alt":[]},"28823":{"h":"קָסוֹמָא","r":"S01641","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קִסָּם\">קְסַם</a>) <i>charmer, diviner.</i> <i>—</i> Pl. <span dir=\"rtl\">קְסוֹמַיָּא</span>. <span class=\"citation\">Targ. Y. Gen. XXII, 21</span> (not <span dir=\"rtl\">קְסוּ׳</span>). <span class=\"citation\">Targ. Y. I Deut. XVIII, 10</span> (Y. II <span dir=\"rtl\">לאקסומי</span>, read: <span dir=\"rtl\">לא קְסוֹמֵי</span>). Targ. Y. ib. 14 <span dir=\"rtl\">קיסומי</span> (corr. acc.).—V. <a href=\"#\" data-headword=\"קַסָּמָא\">קַסָּמָא</a>.</div>","alt":[]},"28824":{"h":"קִסּוּמָא","r":"S01642","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיסּוּמָא\">קִיסּוּמָא</a></div>","alt":[]},"28825":{"h":"קסוסטבן","r":"S01643","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<i>pl.</i> of ξεστός or of sextarius, transposed) <i>sextarii</i> (one sextarius = 1/16 of a modius). <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> bot. <span dir=\"rtl\">כגון אילין … מתרתין ק׳ … ק׳</span> as those who advance the money with which to buy to those who sail to (do business at) the races, at a share in the profits of two or three sextarii for each modius; v. <a href=\"#\" data-headword=\"קָלִיט\">קָלִיט</a>.</div>","alt":["קְסוּסְטִין","קְסוּסְטָרִין"]},"28826":{"h":"קסוסנון","r":"S01644","html":"<div class=\"sense\"> (a corrupt. for <span dir=\"rtl\">קְסוּנְטוֹן</span>, transpos. of <span dir=\"rtl\">סקונטון</span>) <i>Saguntum</i> in Spain. <span class=\"citation\">Y. Keth. II, 26ᶜ</span> bot. <span dir=\"rtl\">אפי׳ עידיה בק׳ תמתין</span> even if her witnesses are as far away as Saguntum, she must wait (cmp. <span class=\"citation\">B. Bath. III, 2</span>, quot. s. v. <a href=\"#\" data-headword=\"אִסְפַּמְיָא\">אִסְפַּמְיָא</a>).</div>","alt":[]},"28827":{"h":"קִסְטְ","r":"S01645","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קוּסְדֹּור\">קִיסְ׳</a>.</div>","alt":["קִסְטָא"]},"28828":{"h":"קסטוריא","r":"S01646","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּסְטוֹדְיָא\">קוּסְטוֹדְיָא</a></div>","alt":[]},"28829":{"h":"קסטיא","r":"S01647","html":"<div class=\"sense\">, Tanḥ. Shof’ṭim 14, read: <a href=\"#\" data-headword=\"קַסִּיטְרָא\">קַסִּיטְרָא</a>.</div>","alt":[]},"28830":{"h":"קסטיטיריון","r":"S01648","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסִּיטְרוֹן\">קַסִּיטְרוֹן</a></div>","alt":[]},"28831":{"h":"קסטינר","r":"S01649","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּסְטִינָר\">קוּסְטִינָר</a></div>","alt":[]},"28832":{"h":"רָהִיט ²","r":"T00287","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"רָהִיט\">preced.</a>) <i>runner</i>. <span class=\"citation\">Targ. Jer. LI, 31</span>.—Pl. <span dir=\"rtl\">רְהִיטַיָּא</span>, <span dir=\"rtl\">רְהִיטֵי</span>. Targ. II Esth. III, 13 ed. Lag.; (ib. 15 <span dir=\"rtl\">רהטיא</span>); a. e., v. <a href=\"#\" data-headword=\"רַהֲטוֹנָא\">רַהֲטוֹנָא</a>.—<span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">שתין ר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"צְפַר IV\">צַפְרָא</a>; <span class=\"citation\">B. Kam. 92ᵇ</span> <span dir=\"rtl\">רָהוֹטֵי</span>. <span class=\"citation\">Sabb. 78ᵇ</span> <span dir=\"rtl\">רהיטי מוכסא</span> (Ar. <span dir=\"rtl\">רהוטי</span>) the runners (police) of the toll collector (who ask persons they meet for their receipts).</div>","alt":["רְהִיטָא"]},"28833":{"h":"רְהִיטְנִי","r":"T00288","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָהִיט ²\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>a tool for planing wood</i> &amp;c. (so named from the grooves in which it runs), <i>chisel</i>, differ. fr. <a href=\"#\" data-headword=\"מְגֵירָה\">מְגֵירָה</a>. <span class=\"citation\">Tosef. Kel. B. Bath. II, 2</span>. <span class=\"citation\">Tosef. B. Kam. XI, 15</span>; <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">היוצא … ומתחת הר׳ וכ׳</span> chips falling from under the borer and the chisel belong to the carpenter.</div><div class=\"sense\"><b>—2)</b>  (cmp. ξυστήρ a. ξύριον) <i>a tool for shaving hair, an instrument</i> with which the hairs are removed singly, differ. fr. <a href=\"#\" data-headword=\"תַּעַר\">תַּעַר</a>. <span class=\"citation\">Macc. III, 5</span>; <span class=\"citation\">Naz. 40ᵇ</span>; a. e.</div>","alt":[]},"28834":{"h":"רָהַן","r":"T00289","html":"<div class=\"sense\">, <i>Hif.</i> <a href=\"#\" data-headword=\"רָהַב\">הִרְהִין</a> (a contract, of <span dir=\"rtl\">רהבן</span>, cmp. <a href=\"#\" data-headword=\"רַהֲבוֹנָא\">רַהֲבוֹנָא</a> a. Lat. arrha; v. <a href=\"#\" data-headword=\"עֵרָבוֹן\">עֵרָבוֹן</a>) <i>to deposit as a pledge</i>, contrad. to <a href=\"#\" data-headword=\"מִשְׁכֵּן\">מִשְׁכֵּן</a> to take a pledge. <span class=\"citation\">Tosef. Maas. Sh. I, 1</span> <span dir=\"rtl\">מעשר שני … ואין מַרְהִינִין אותו</span> ed. Zuck. (Var. <span dir=\"rtl\">מְהַרְהִינִין</span>) second tithes must neither be sold, nor taken or given as a pledge; Y. ib. I, 52ᶜ top. Ib. <span dir=\"rtl\">עבר והי׳ וכ׳</span> if he pledged it in defiance of the law, he is fined. <span class=\"citation\">Pes. 31ᵃ</span> <span dir=\"rtl\">כשהִרְהִינוֹ אצלו</span> when he deposited it (the leavened matter) with him (the gentile) as a pledge. <span class=\"citation\">Ib.ᵇ</span>; a. e.</div>","alt":[]},"28835":{"h":"רהקא","r":"T00290","html":"<div class=\"sense\">, <span class=\"citation\">Bets. 30ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"דּוּחֲקָא\">דּוּחֲקָא</a> (v. Rabb. D. S. a. l. a. <span class=\"citation\">Sabb. 148ᵃ</span> Ms. M.).</div>","alt":[]},"28836":{"h":"רֵוָא","r":"T00291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיו\">רֵיוָא</a></div>","alt":[]},"28837":{"h":"רוֹאֶה I","r":"T00292","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ראי\">רָאָה</a>) = <a href=\"#\" data-headword=\"רֳאִי I\">רֳאִי</a>, <i>sight, view</i>. <span class=\"citation\">Zeb. XIV, 6</span> <span dir=\"rtl\">בכל הר׳</span> were permitted to be eaten within the entire range of sight (around Shiloh); (<span class=\"citation\">Yalk. Deut. 881</span> <span dir=\"rtl\">בכל מקום שאתה רואה</span>); <span class=\"citation\">Num. R. s. 14</span><sup>7</sup>. <span class=\"citation\">Zeb. 118ᵇ</span> <span dir=\"rtl\">ר׳ שאמרו ר׳ כולו וכ׳</span> the range of sight of which they speak means a spot from where you can overlook the entire place with nothing to intercept &amp;c.; <span dir=\"rtl\">לא ר׳ כולו אלא ר׳ מקצתו</span> by <i>roëh</i> is meant the view not only of the entire place but also of a part of it.</div>","alt":[]},"28838":{"h":"רוֹאֶה II","r":"T00293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (supposed to be) the name of <i>an insect</i> on trees. <span class=\"citation\">Tosef. Shebi. I, 11</span>; Y. ib. II, 33ᵈ</div>","alt":[]},"28839":{"h":"רוֹאִי","r":"T00294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֳאִי I\">רֳאִי</a></div>","alt":[]},"28840":{"h":"רוֹב","r":"T00295","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>multitude; larger portion; majority</i>. <span class=\"citation\">Meg. 15ᵇ</span> (ref. to <span class=\"citation\">Esth. V, 11</span>) <span dir=\"rtl\">וכמה ר׳ בניו</span> how large was the multitude of his sons? <span class=\"citation\">Bekh. VI, 8</span> <span dir=\"rtl\">ר׳ המדבר וכ׳</span> the larger portion of the anterior part of the tongue. <span class=\"citation\">Keth. 15ᵃ</span> <span dir=\"rtl\">הולכין אחר ר׳ העיר</span> we are guided by the legal status of the majority of the inhabitants of the town; <span dir=\"rtl\">ר׳ סיעה</span> the majority of the members of the caravan that encamped near the town. Ib.; <span class=\"citation\">Ḥull. 95ᵃ</span>, a. e. <span dir=\"rtl\">בנמצא הלך אחר הר׳</span> when a piece of meat is found, we go by the majority of the meat stalls (to decide whether it be <i>kasher</i> or not). <span class=\"citation\">Ib. 3ᵇ</span>, a. e. <span dir=\"rtl\">ר׳ מצויין וכ׳</span> most of those engaged in slaughtering are experts. <span class=\"citation\">Sabb. 118ᵇ</span> <span dir=\"rtl\">רוּבָּן של צדיקים וכ׳</span> most righteous men die from bowel diseases. <span class=\"citation\">Ḥull. II, 1</span> <span dir=\"rtl\">רוּבֹּו של אחד כמוהו</span> if one cuts through the larger portion of the organ (v. <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>), it is considered as if he had cut it through. <span class=\"citation\">Hor. 3ᵇ</span> <span dir=\"rtl\">בכל התורה … רובו ככולו</span> in the entire Law we adopt the rule that a majority (or the larger portion) are legally equal to an entirety; <span class=\"citation\">Naz. 42ᵃ</span>; a. v. fr.—<span class=\"citation\">Gitt. 60ᵇ</span> <span dir=\"rtl\">ר׳ בכתב וכ׳</span> the majority of the halakhic decisions rests on the Scripture (is derived from the text by interpretation), and the minority on tradition; v. Y. Peah I, 17ᵃ bot.—[<span class=\"citation\">Y. Yeb. IV, 6ᵇ</span> top <span dir=\"rtl\">עד שיפרש לו רובו</span>, read: <span dir=\"rtl\">רַבֹּו</span>.]</div>","alt":[]},"28841":{"h":"רוּבָּא","r":"T00296","html":"<div class=\"sense\"> <span class=\"citation\">Ḥull. 11ᵃ</span> <span dir=\"rtl\">מנא הא מילתא … בתר ר׳</span> whence do we derive the rule laid down by the Rabbis, that we are guided by the majority? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ דאיתיה קמן</span> a majority which is before us, a majority of a definite number; <span dir=\"rtl\">ר׳ דליתיה קמן כגון וכ׳</span> a majority of an indefinite number, as for instance, the case of a minor <i>yabam</i> (<span class=\"citation\">Yeb. XIII, 12</span>, when we are guided by the principle that the majority of persons are not impotent). <span class=\"citation\">B. Kam. 46ᵇ</span> <span dir=\"rtl\">ר׳ דאנשי לרדיא וכ׳</span> most people buy animals for ploughing. Ib.; <span class=\"citation\">B. Bath. 92ᵇ</span>, v. <a href=\"#\" data-headword=\"אִיסּוּרָא\">אִיסּוּרָא</a>; a. v. fr.—Pl. <a href=\"#\" data-headword=\"רוֹבִי\">רוּבֵּי</a>. <span class=\"citation\">Ḥull. 28ᵇ</span> תרי ר׳ … ליכא Rashi (ed. <span dir=\"rtl\">רובא</span>) two larger portions of one object cannot be assumed, i.e. if an object is divided into two equal parts, you cannot apply the principle that either half may be ritually considered as if it were the larger portion.</div>","alt":[]},"28842":{"h":"רוֹבָא","r":"T00297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹבָה\">רוֹבָה</a></div>","alt":[]},"28843":{"h":"רוֹבֵא","r":"T00298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>growing</i>,] <i>young man, youth</i>. <span class=\"citation\">Sot. 26ᵃ</span> <span dir=\"rtl\">הר׳ שנשא עקרה וכ׳</span> a young man who married a barren or an old woman. Y. ib. VIII, 22ᵈ bot. <span dir=\"rtl\">ר׳ שנשא ריבה</span> a young man that married a young girl; a. e.—Pl. <a href=\"#\" data-headword=\"רוֹבִי\">רוֹבִים</a>, <span dir=\"rtl\">רוֹבִין</span>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">והר׳ שומרים שם</span> the young priests held watch there; [anoth. opinion: the <i>archers</i>, v. <span dir=\"rtl\">רְבֵי II</span>].—Esp. <span dir=\"rtl\">הר׳</span> <i>the sons of R. Ḥiyya</i>. <span class=\"citation\">Ḥull. 20ᵃ</span> <span dir=\"rtl\">יקבלו הר׳ וכ׳</span> let the lads receive the answer to their arguments. <span class=\"citation\">Y. Ḥag. III, 79ᶜ</span> bot.; a. e.</div>","alt":["רוֹבֶה I"]},"28844":{"h":"רוֹבֶד","r":"T00299","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*רָבַד\">רָבַד</a>) </div><div class=\"sense\"><b>1)</b> <i>mosaic pavement</i>, esp. <i>the paved level space between steps</i> in the Temple hall, <i>landing, terrace</i>. <span class=\"citation\">Yoma IV, 3</span> <span dir=\"rtl\">הר׳ הרביעי שבהיכל</span>, emended <span class=\"citation\">ib. 43ᵇ</span> <span dir=\"rtl\">של היכל</span>, the fourth terrace on coming from the hall. <span class=\"citation\">Midd. III, 6</span> <span dir=\"rtl\">רום מעלה … ור׳ שלשה וכ׳</span> the height of each step was half a cubit, its depth one cubit each of the three steps, and a landing of three cubits &amp;c. <span class=\"citation\">Ib. IV, 4</span>, sq. <span class=\"citation\">Tosef. Succ. IV, 23</span>; <span class=\"citation\">Tosef. Men. XI, 13</span> <span dir=\"rtl\">הר׳ שבאולם</span> the pavement in the hall.—Pl. <span dir=\"rtl\">רוֹבְדִים</span>, <span dir=\"rtl\">רוֹבְדִין</span>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">היה מוקף ר׳ של אבן</span> was surrounded with stone pavements; <span class=\"citation\">Midd. I, 8</span>. <span class=\"citation\">Tosef. Ohol. XVII, 1</span> <span dir=\"rtl\">משוקעין בר׳ ובאבנים</span> sunk in and covered with paving blocks or with (rough) stones.</div><div class=\"sense\"><b>—2)</b> <i>the interlaced branches of two neighboring trees.</i> <i>—Pl</i>. as ab. <span class=\"citation\">Ḥull. 140ᵇ</span> <span dir=\"rtl\">היתה יושבת בין שני רוֹבְדֵי אילן</span> if the mother bird is found sitting on the junction of two trees. <span class=\"citation\">Ib. 141ᵃ</span>; a. e.</div>","alt":[]},"28845":{"h":"רוֹבֵדָא","r":"T00300","html":"<div class=\"sense\">, <i>pavement</i>. <span class=\"citation\">Targ. II Chr. VII, 3</span> (h. text <a href=\"#\" data-headword=\"רִצְפָה\">רצפה</a>).</div>","alt":[]},"28846":{"h":"רוֹבֶה I","r":"T00301","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹבֵא\">רוֹבֵא</a></div>","alt":[]},"28847":{"h":"רוֹבֶה II","r":"T00302","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָבֶה\">רָבֶה</a>) <i>saturation, sauce, dip</i>. <span class=\"citation\">Y. Pes. X, 37ᵈ</span> top <span dir=\"rtl\">ולמה … ר׳ שהיא רָבָה עמו</span> and why is it (<a href=\"#\" data-headword=\"חֲרוֹסֶת\">חֲרוֹסֶת</a>) called <i>robeh</i> (saturation)? Because it is saturated with it (the wine that is put in as a sauce).</div>","alt":[]},"28848":{"h":"רוֹבָה","r":"T00303","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"רַב\">רַבָּא</a>, <i>great</i>. <span class=\"citation\">Targ. Y. II, Lev. X, 19</span> (ed. Vien. <a href=\"#\" data-headword=\"רוּבָּא\">רוּבָא</a>).</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a> <i>elder, senior</i>. <span class=\"citation\">Y. Ber. II, 5ᵇ</span> bot. <span dir=\"rtl\">ר׳ הושעיא ר׳</span>. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> <span dir=\"rtl\">ר׳ חייא ר׳</span>; a. fr. (interch. with <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a>).</div>","alt":["רוֹבָא"]},"28849":{"h":"רוּבָּה I","r":"T00304","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מְרוּבֶּה\">מְרוּבָּה</a>) <i>more, larger number</i>. <span class=\"citation\">Keth. 103ᵃ</span> <span dir=\"rtl\">ברכת הבית בר׳</span> the blessing of the household increases with the number of its members (every one contributing towards the comfort of all); <span class=\"citation\">B. Bath. 144ᵇ</span>; <span class=\"citation\">Tosef. Keth. XII, 3</span> <a href=\"#\" data-headword=\"מְרוּבֶּה\">מרובה</a> (corr. acc.).</div>","alt":[]},"28850":{"h":"רוּבָּה II","r":"T00305","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"רְבַב\">רְבַב</a>) <i>gradation, conclusion a minori ad majus</i> (= <span dir=\"rtl\">קַל וָחוֹמֶר</span>). <span class=\"citation\">Y. Peah IV, 18ᵇ</span> top <span dir=\"rtl\">ר׳ דר׳ יוחנן ור׳ דר&quot;ל</span> there exists one argument a minori by R. J. and another by R. S. ben L.; <span dir=\"rtl\">ר׳ … מה מציאה וכ׳</span> R. J.’s argument is: if in the case of a find &amp;c. (v. corr. vers in Frankel, Talm. Hierosol.).—<a href=\"#\" data-headword=\"ר׳\">ר׳</a>, <span dir=\"rtl\">דר׳</span> (cmp. <a href=\"#\" data-headword=\"חוֹמֶר I\"><span dir=\"rtl\">חוֹמֶר</span> I</a>) <i>something greater, more restrictive</i>. <span class=\"citation\">Y. Sabb. XVII, beg. 16ᵃ</span> <span dir=\"rtl\">דלתות הבית דר׳ ודלתות הכלים דר׳ וכ׳</span> (not <span dir=\"rtl\">דרובן</span>) in one respect there is a greater restriction in the law concerning the moving of the doors of a house, and in another respect a greater restriction in the law concerning the doors of furniture; <span dir=\"rtl\">דלתות … דר׳ וכ׳</span> the greater restriction concerning the doors of a house consists in this that they dare not be moved even &amp;c. <span class=\"citation\">Y. Ab. Zar. I, 40ᵃ</span> top <span dir=\"rtl\">ר׳ דר&quot;ש ב&quot;ל מדרבי וכ׳</span> the opinion of R. S. b. L. goes farther in restriction than that of R. J. <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> bot. <span dir=\"rtl\">דר׳ אתא אימור לך</span> he comes to tell you something greater.—<span class=\"citation\">Y. Meg. I, 71ᶜ</span> top <span dir=\"rtl\">דרַבָּה שהספרים וכ׳</span> here is something greater (than the difference between scrolls and T’fillin which has been stated): scrolls may be written on either side of the parchment &amp;c.; <span dir=\"rtl\">דף אחד בשני עורות לית היא דר׳</span> the ‘one column’ law against the ‘two sides’ law—this is no gradation. <span class=\"citation\">Y. Peah I, 15ᵈ</span> top <span dir=\"rtl\">והוא דרבה מִנָּהּ גדול … כפריעת חוב וכ׳</span> (not <span dir=\"rtl\">בפריעת</span>) here is something greater (just the reverse, v. <a href=\"#\" data-headword=\"אַדְּרַבָּא\">אַדְּרַבָּא</a>); greater is a duty which is like paying a debt (the filial duty) than &amp;c.; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> bot. <span dir=\"rtl\">וההיא דרבנין</span> (corr. acc.).</div>","alt":[]},"28851":{"h":"רוֹבִי","r":"T00306","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רוֹבֶה I\">רוֹבֶה</a>, <i>youth, young man</i>. <span class=\"citation\">Targ. I Chr. XXII, 5</span>.—Pl. <span dir=\"rtl\">רוֹבִין</span>, <a href=\"#\" data-headword=\"רוֹבִי\">רוֹבַיָּא</a>. <span class=\"citation\">Targ. Ruth III, 10</span>. <span class=\"citation\">Targ. Lam. II, 12</span> (not <a href=\"#\" data-headword=\"רַמְשִׁית\">רוּ׳</a>). <span class=\"citation\">Ib. 21</span>; a. e.—<span class=\"citation\">Targ. Job XXI, 11</span> <span dir=\"rtl\">ורוֹבְיֵהוֹן</span>.</div>","alt":["רוֹבְיָא I"]},"28852":{"h":"רוֹבִי ²","r":"T00307","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fenugreek</i>, (oth. opin. <i>flax-seed</i>). <span class=\"citation\">Ker. 6ᵃ</span> <span dir=\"rtl\">יהא רגיל … ורובי וכ׳</span> (Rashi <span dir=\"rtl\">ורוביא</span>) one should make it a habit at the beginning of a year to eat pumpkin, fenugreck &amp;c.; <span class=\"citation\">Hor. 12ᵃ</span>. <span class=\"citation\">Ḥull. 52ᵃ</span>. <span class=\"citation\">Sabb. 109ᵇ</span>, v. <a href=\"#\" data-headword=\"גִּיר III\"><span dir=\"rtl\">גִּיר</span> III</a>.</div>","alt":["רוֹבְיָא II"]},"28853":{"h":"רוֹבָן","r":"T00308","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>) <i>coarse weft</i>. <span class=\"citation\">Par. XII, 8</span> (Var. <a href=\"#\" data-headword=\"אָרְבָּן\">אָרְבָּן</a> q. v.).</div>","alt":[]},"28854":{"h":"רוֹבַע","r":"T00309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>one-fourth</i>, esp. (sub. <span dir=\"rtl\">קב</span>) <i>robʿa</i>, one-fourth of a Kab. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">Y. Yoma IV, 41ᵈ</span>. <span class=\"citation\">Tosef. B. Bath. V, 10</span> (among the measures to be kept) <span dir=\"rtl\">ר׳ וחצי ר׳</span> a <i>robʿa</i> and a half <i>robʿa</i>. <span class=\"citation\">Num. R. s. 9</span><sup>24</sup> (God repays measure for measure) <span dir=\"rtl\">ר׳ וחצי ר׳</span> even to a <i>r.</i> and a half-<i>r</i>. <span class=\"citation\">Tosef. Kel. B. Bath. III, 8</span> <span dir=\"rtl\">הר׳ וחצי הר׳</span> a block with the cavity of a <i>r.</i> on one side and of a half-<i>r</i>. on the other; <span class=\"citation\">Tosef. Mikv. VI, 22</span>. <span class=\"citation\">Tosef. Ohol. I, 7</span> <span dir=\"rtl\">ר׳ עצמות</span> a <i>robʿa</i>-ful of bones; a. fr.—<span dir=\"rtl\">בית ר׳</span> a piece of ground of the capacity of one <i>robʿa</i> of seed. <span class=\"citation\">Kidd. 26ᵇ</span>; a. e.</div>","alt":[]},"28855":{"h":"רוּבְעָא","r":"T00310","html":"<div class=\"sense\">, <i>one fourth</i>. Targ. II Esth. IV, 1.—Pl. <span dir=\"rtl\">רוּבְעַיָּא</span>. <span class=\"citation\">Y. Ḥall. II, 58ᵈ</span> top, v. <a href=\"#\" data-headword=\"קַבָּא\">קַבָּא</a>.</div>","alt":[]},"28856":{"h":"רוּבְצָל","r":"T00311","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְצָל\">רִבְצָל</a></div>","alt":[]},"28857":{"h":"רוֹגֶז","r":"T00312","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>excitement, anger, commotion, trouble</i>. <span class=\"citation\">Midr. Till. to Ps. XXII</span> <span dir=\"rtl\">מתיך ר׳ רחמים</span> out of the divine anger comes mercy (ref. to <span class=\"citation\">Hab. III, 2</span>). <span class=\"citation\">Pirké d’R. El. ch. XXXVIII</span> <span dir=\"rtl\">התחיל מקלל רוֹגְזָם וכ׳</span> he began to curse his sons’ anger. <span class=\"citation\">Gen. R. s. 84</span> (ref. to <span class=\"citation\">Job III, 26</span>) <span dir=\"rtl\">בא עלי רָגְזוֹ וכ׳</span> the trouble about Joseph came upon me.</div>","alt":[]},"28858":{"h":"רוּגְזָא","r":"T00313","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. II Chr. XXXIV, 21</span>. <span class=\"citation\">Targ. Ps. LXXVIII, 31</span>. <span class=\"citation\">Targ. Job XXI, 30</span> <a href=\"#\" data-headword=\"רְגִזְתָּא\">רְגִזְתָּא</a>, <span dir=\"rtl\">רְגִיזְ׳</span> (Ms. <a href=\"#\" data-headword=\"רוּגְזֵיתָא\">רוּגְזֵיתָא</a>); a. e.—[<span class=\"citation\">Targ. Prov. XXIX, 22</span> <span dir=\"rtl\">גברא ר׳</span>, read with ed. Lag. a. oth. <a href=\"#\" data-headword=\"רַגְזָנָא\">רַגְזָנָא</a>.]—<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">נתמלא רוּגְזֵיה וכ׳</span> (<i>masc</i>.) Ben Kosiba’s anger rose to its full measure.—Pl. <a href=\"#\" data-headword=\"רוּגְזֵיתָא\">רוּגְזָאתָא</a>, <a href=\"#\" data-headword=\"רוּגְזֵיתָא\">רוּגְזָתָא</a>. <span class=\"citation\">Targ. Job XL, 11</span> (Ms. <a href=\"#\" data-headword=\"רְגוּזְתָּא\">רְגוּזְתָּא</a>).</div>","alt":[]},"28859":{"h":"רוּגְזֵיתָא","r":"T00314","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּגְזָא\">preced.</a></div>","alt":[]},"28860":{"h":"רוגיינא","r":"T00315","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. I, 27ᵃ</span> <span dir=\"rtl\">אף הר׳</span>, v. <a href=\"#\" data-headword=\"*נִיוְיָינָא\">נִיוְיָינָא</a></div>","alt":[]},"28861":{"h":"רוֹגְלוֹת","r":"T00316","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"רוֹגְלִית\">next w.</a></div>","alt":[]},"28862":{"h":"רוֹגְלִית","r":"T00317","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"רַגְלִיּוֹת\">רוֹגְלִיּוֹת</a> (<a href=\"#\" data-headword=\"רֶגֶל\">רֶגֶל</a>) </div><div class=\"sense\"><b>1)</b> <i>routes, directions</i>. <span class=\"citation\">Cant. R. to IV, 1</span> <span dir=\"rtl\">מה … משוגרת ר׳ הרבה וכ׳</span> as the pigeon is sent out in many directions and always returns &amp;c.; <span class=\"citation\">ib. to I, 15</span> (not <span dir=\"rtl\">שוגרת</span>).</div><div class=\"sense\"><b>—2)</b>  (adj.) <i>familiar</i>. <span class=\"citation\">Tosef. Ber. II, 12</span>, a. e. <span dir=\"rtl\">הלכות ר׳</span>, v. <a href=\"#\" data-headword=\"רָגִיל\">רָגִיל</a>.</div><div class=\"sense\"><b>—3)</b>  [<i>runners</i>,] <i>grapes growing in a row on isolated vines</i>, opp. <span dir=\"rtl\">דליות</span> (v. <a href=\"#\" data-headword=\"דָּלִית\">דָּלִית</a>). <span class=\"citation\">Men. VIII, 6</span> (<span class=\"citation\">86ᵇ</span>) <a href=\"#\" data-headword=\"רַגְלִיּוֹת\">רַגְלִיּוֹת</a>; Tosef. ib. IX, 10 <span dir=\"rtl\">רג׳</span>. <span class=\"citation\">Y. Peah VII, end, 20ᶜ</span> <span dir=\"rtl\">כל ר׳ ור׳ אומן וכ׳</span> all plants in one row form one bed; <span class=\"citation\">Y. Pes. IV, 31ᵇ</span> bot. <a href=\"#\" data-headword=\"רוֹגְלוֹת\">רוגלות</a>.</div>","alt":[]},"28863":{"h":"רַוְגְּנַג","r":"T00318","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> river <i>Ravg’nag</i>. <span class=\"citation\">B. Bath. 73ᵇ</span> top (Ms. M. <span dir=\"rtl\">רונג</span>; Ms. R. <span dir=\"rtl\">דַוְנַג</span>; ed. Lubl. <span dir=\"rtl\">דוונג</span>; v. Rabb. D. S. a. l. note).</div>","alt":[]},"28864":{"h":"רוּגְשָׁנָא","r":"T00319","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְגָשָׁא\">רְגָשָׁא</a></div>","alt":[]},"28865":{"h":"רוֹדֶה","r":"T00320","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רָדָה II) <i>the flat portion of the baker’s shovel</i>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 7</span>, v. <a href=\"#\" data-headword=\"צִנּוֹרָא III\"><span dir=\"rtl\">צִנּוֹרָא</span> III</a>.</div>","alt":[]},"28866":{"h":"רוֹדוֹס","r":"T00321","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (a corrupt. of Ἄραδος) <i>Aradus</i>, v. <a href=\"#\" data-headword=\"אַרְוָוד\">אַרְוָוד</a>. <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot. (expl. <span dir=\"rtl\">ארודי</span>, <span class=\"citation\">Gen. X, 18</span>) <a href=\"#\" data-headword=\"ר׳\">ר׳</a>; [The context forbids thinking of Rhodus].—[<span class=\"citation\">Y. Yeb. VIII, 9ᵇ</span> bot. <span dir=\"rtl\">ברודוס</span>, read with Y. Kidd. IV, 66ᵇ top, a. <span class=\"citation\">Y. Bicc. I, 64ᵃ</span> <span dir=\"rtl\">בדָרוֹם</span>.]</div>","alt":[]},"28867":{"h":"רָוָה","r":"T00322","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוי\">רוי</a></div>","alt":[]},"28868":{"h":"רוּהֲנָא","r":"T00323","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוֵי\">רְוָא</a>, cmp. <a href=\"#\" data-headword=\"רָהוֹן\">רָהוֹן</a>) <i>moistening, refreshment</i> [or <i>marrow</i>]. <span class=\"citation\">Targ. Prov. III, 8</span>, v. <a href=\"#\" data-headword=\"דּוּהֲנָא\">דּוּהֲנָא</a>.</div>","alt":[]},"28869":{"h":"רֵווּ","r":"T00324","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיו\">רֵיו</a></div>","alt":["רִוו","רֵוָוא"]},"28870":{"h":"רְוַוז","r":"T00325","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוַז\">רְוַז</a></div>","alt":[]},"28871":{"h":"רָוַוח","r":"T00326","html":"<div class=\"sense\"> (b. h.) <i>to be wide, roomy; to spread</i>. <span class=\"citation\">Y. Snh. I, 19ᶜ</span> top <span dir=\"rtl\">משם התורה יוצאה ורווַֹחַת וכ׳</span> from there (the hall of the Sanhedrin) the law went forth and spread (with authority) for all Israel; Tosef. ib. VII, 1; <span class=\"citation\">Tosef. Ḥag. II, 9</span>. <span class=\"citation\">Y. Yeb. I, 3ᵃ</span> bot. <span dir=\"rtl\">ראה … רווחת בישראל</span> see how this decision will spread (what its effect will be) in Israel; a. e.—Part. pass. <span dir=\"rtl\">רָווּחַ</span>; pl. <span dir=\"rtl\">רְווּחִים</span>. <span class=\"citation\">Ab. V, 5</span>, a. e. <span dir=\"rtl\">משתחוים</span>, <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, v. <a href=\"#\" data-headword=\"צָפַף\">צָפַף</a>; [Mish. ed. <span dir=\"rtl\">רְוָחִים</span>, pl. of <a href=\"#\" data-headword=\"רָוַח\">רָוָח</a>.]</div><div class=\"sense\"><b>Pa. רוּוָּח</b> <div class=\"sense\"><b>1)</b> <i>to be placed wide apart</i>.—Part. <span dir=\"rtl\">מְרוּוָּח</span>; f. <span dir=\"rtl\">מְרוּוַּחַת</span>; pl. <span dir=\"rtl\">מְרוּוָּחִים</span>, <span dir=\"rtl\">מְרוּוָּחִין</span>; <span dir=\"rtl\">מְרוּוָּחוֹת</span> (or <span dir=\"rtl\">מְרֻיָּו׳</span>). Y. Shebi. II, end, 34ᵇ <span dir=\"rtl\">במר׳</span> when the trees are planted wide apart, opp. <span dir=\"rtl\">רצופין</span>; Y. M. Kat. I, 80ᶜ top; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be wide and flat</i>. <span class=\"citation\">Koh. R. to VII, 23</span> <span dir=\"rtl\">מקום מר׳</span>, v. <a href=\"#\" data-headword=\"רֶוַוח\">רֶוַוח</a>. <span class=\"citation\">Tosef. Kel. B. Mets. VIII, 6</span> לשונות מר׳ R. S. to <span class=\"citation\">Kel. XVIII, 5</span> wide and flat straps (comfortable to lie on), v. <a href=\"#\" data-headword=\"לוּחַ I\"><span dir=\"rtl\">לוּחַ</span> I</a>.</div></div><div class=\"sense\"><b>Hif. הִרְוִיחַ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רָוַח\">רֶוַח</a>) </div><div class=\"sense\"><b>1)</b> <i>to be relieved</i>; </div><div class=\"sense\"><b>2)</b> <i>to make profit</i>. <span class=\"citation\">Gen. R. s. 13</span> <span dir=\"rtl\">משא … מַרְוִיחִין</span> commerce is prosperous, and the dealers make profit; <span dir=\"rtl\">אף … מרויחין</span> even the lepers feel relieved; Yalk. ib. 20. <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">החולה … ומַרְוִיחַ</span> the sick man saw him (Abraham) and felt better. <span class=\"citation\">Yalk. Ps. 843</span>, v. <a href=\"#\" data-headword=\"רֶוַוח\">רֶוַוח</a>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to cause relief</i>. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">מרויחין לו</span> they (the visitors) bring him some relief; <span class=\"citation\">Midr. Till. to Ps. XLI</span>.</div></div><div class=\"sense\"><b>Hithpa. הִתְרַוֵּוחַ</b> </div><div class=\"sense\"><b>Nithpa. נִתְרַוֵּוחַ</b> <div class=\"sense\"><i>to be relieved, be in comfortable circumstances</i>. Lev. R. l. c. <span dir=\"rtl\">לכשאתה מִתְרַוּוֵחַ וכ׳</span> when thou art in better circumstances, thou wilt repay me.—[Ib., a. e. <span dir=\"rtl\">נתרווח העולם</span>, read: <a href=\"#\" data-headword=\"רוי\">נִתְרַוֶּוה</a>, v. <a href=\"#\" data-headword=\"רָוָה\">רָוָה</a>.]</div></div>","alt":["רָוַח"]},"28872":{"h":"רְוַוח","r":"T00327","html":"<div class=\"sense\"><b>1)</b> <i>to be wide, extend; to be easy</i>; <span dir=\"rtl\">ר׳ ל־</span> <i>to feel relieved</i>. <span class=\"citation\">Targ. Job XXXII, 20</span>.—[<span class=\"citation\">Targ. Ps. XXIII, 5</span> רויחא Ms., ed. Lag. <span dir=\"rtl\">רווחא</span>, v. <a href=\"#\" data-headword=\"רְוִיתָא\">רְוִיתָא</a>.]—<span class=\"citation\">Snh. 7ᵃ</span> <span dir=\"rtl\">כיון דר׳ ר׳</span>, v. <a href=\"#\" data-headword=\"בִּדְקָא\">בִּדְקָא</a>. <span class=\"citation\">Ḥull. 8ᵃ</span> <span dir=\"rtl\">בית … מִירְוַוח ר׳</span> the cut widens, i.e. the parts cut through go apart, and are not affected by the heat of the knife. <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">תרעא דר׳ ר׳</span> when the market becomes easy (prices fall), it remains so (for the rest of the year). <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">אמינא … ר׳ עלמא וכ׳</span> (Ms. M. <span dir=\"rtl\">דוו</span>, corr. acc.) I thought, as it has been raining, the world is at ease (prices will come down). <span class=\"citation\">Keth. 80ᵇ</span>, v. <a href=\"#\" data-headword=\"רְוַוח ²\">רַוְוחָא</a>. <span class=\"citation\">B. Bath. 167ᵃ</span> (suspecting an erasure in a document) <span dir=\"rtl\">מ&quot;ט רְוִיחַ ליה עלמא להאי וי&quot;ו</span> why has this Vav so much space?, opp. <a href=\"#\" data-headword=\"דְּחוֹק\">דחוק</a>; a. fr.—<span class=\"citation\">Y. Sabb. XX, end, 17ᵈ</span> <span dir=\"rtl\">נפל ביתיה על מאן דרויח עליה</span> his house fell in over him who felt at ease (?), v. <a href=\"#\" data-headword=\"צְנִינִים\">צְנִינִים</a>.—[</div><div class=\"sense\"><b>2)</b> <i>to make room</i>. <span class=\"citation\">Targ. Is. XLIX, 20</span> <span dir=\"rtl\">רְוַח לי</span> (prob. to be read: <a href=\"#\" data-headword=\"רְוַוח\">רַוַּח</a> <i>Pa.</i>; h. text <span dir=\"rtl\">גְּשָׁה</span>.]</div><div class=\"sense\"><b>Pa. רַוַּוח  רַוַּח</b> <div class=\"sense\"><b>1)</b> <i>to widen, make room; give comfort</i>. <span class=\"citation\">Targ. Prov. XVIII, 16</span> (h. text <span dir=\"rtl\">ירחיב</span>).—Part. pass. <span dir=\"rtl\">מְרַוַּוח</span>; f. <span dir=\"rtl\">מְרַוְּוחָא</span>; pl. <span dir=\"rtl\">מרַוְּוחִין</span>; <span dir=\"rtl\">מְרַוְּוחָן</span>, <span dir=\"rtl\">מְרַוְּח׳</span>. <span class=\"citation\">Targ. Jer. XXII, 14</span>.— </div><div class=\"sense\"><b>2)</b>  (denom. of <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a>) <i>to inspire</i>.—Part. pass. as ab. <span class=\"citation\">Targ. Y. Deut. XXXII, 24</span> [read:] <span dir=\"rtl\">מְרַוְּוחֵי רוּחִין בישין</span> possessed by evil spirits.</div></div><div class=\"sense\"><b>Af. אַרְוַוח  אַרְוַח</b> <div class=\"sense\"><b>1)</b> <i>to make room, widen; to relieve</i>. <span class=\"citation\">Targ. Y. Gen. XXVI, 22</span>. <span class=\"citation\">Targ. Lam. III, 56</span> <span dir=\"rtl\">לאַרְוָוחוּתְנִי</span> (verbal noun); a. e.—<span class=\"citation\">Sabb. 151ᵇ</span> <span dir=\"rtl\">האי כוחלא … מַרְוַוח</span> (or <span dir=\"rtl\">מְרַוַּוח</span> <i>Pa.</i>) stibium widens (improves the eye-sight) up to forty years of age, <span dir=\"rtl\">מכאן … אַרְוָחֵי לא מרווח</span> after that … it preserves the eye-sight, but does not improve it; a. e.—<i>Part. pass</i>. <span dir=\"rtl\">מַרְוַוח</span> <i>open; vacant</i>. <span class=\"citation\">Targ. II Chr. XXIII, 15</span>. <span class=\"citation\">Targ. I Sam. XX, 25</span>; <span class=\"citation\">27</span> (h. text <span dir=\"rtl\">ויִפָּקֵד</span>).</div><div class=\"sense\"><b>—2)</b> <i>to make profit, gain</i>. Y. Ned. V, end, 39ᵇ <span dir=\"rtl\">חד בר נש נדר דלא מַרְוַוח</span> (not <span dir=\"rtl\">מרווחא</span>) a man made a vow that he would make no profit (in business). Ib. [read:] <span dir=\"rtl\">א&quot;ל מאי אשבעת א&quot;ל דלא מַרְוַוחְנָא</span> he asked him, what didst thou swear (not to do)? Said he, that I will make no profit (v. Asheri to <span class=\"citation\">Gitt. 35ᵇ</span>).</div><div class=\"sense\"><b>—3)</b> <i>to cause to profit</i>. <span class=\"citation\">B. Mets. 73ᵃ</span> bot. <span dir=\"rtl\">אנא נטרנא … ומרווחנא להו בכמה</span> I wait for them (give them time to move) until Iyar, and thus I benefit them greatly; a. e.—Part. pass. <span dir=\"rtl\">מַרְוַוח</span>. <span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">מ׳ עסקך</span> thy business will be profitable, opp. <a href=\"#\" data-headword=\"פָּסֵיד\">פסיד</a>.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַוַּוח</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְוַוח</b> <div class=\"sense\"><i>a</i>) <span dir=\"rtl\">אתר׳ ל־</span> <i>to be relieved; to be better</i>. <span class=\"citation\">Targ. I Sam. VI, 3</span>. <span class=\"citation\">Ib. XVI, 23</span>; a. e.—<i>b</i>) <i>to be blessed</i> (with issue, with increase of wealth). <span class=\"citation\">Targ. Gen. XX, 17</span>. <span class=\"citation\">Targ. Y. ib. XXII, 20</span>. <span class=\"citation\">Ib. XXV, 21</span>. <span class=\"citation\">Ib. XXVI, 31</span>.</div></div>","alt":["רְוַח I"]},"28873":{"h":"רֶוַוח","r":"T00328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְוַוח\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>extension, wide space; interval</i>. <span class=\"citation\">Gen. R. s. 74</span> <span dir=\"rtl\">אין … במקום ר׳</span> they (the eastern men) hold council only in an open and level place (where they are safe against spies); <span class=\"citation\">Yalk. ib. 130</span> <span dir=\"rtl\">בשדה דאית בה ר׳</span>; Koh. R. to VI, 23 <span dir=\"rtl\">במקום מְרוּוָּח</span> (v. <a href=\"#\" data-headword=\"רָוַוח\">רָוַוח</a>); Pesik. Par., p. 34ᵃ <span dir=\"rtl\">במקום רחוק</span> (corr. acc.). <span class=\"citation\">Gen. R. s. 19</span> (play on <span dir=\"rtl\">לרוּחַ היום</span>, <span class=\"citation\">Gen. III, 8</span>) <span dir=\"rtl\">לרי׳ היום</span> for the extension of the day (in order to extend Adam’s day to God’s day, a thousand years); <span class=\"citation\">Pesik. R. s. 40</span> יום משלי … לר׳ היום וכ׳ I will give him one of my days,—‘to the extension of the day’—I will give him &amp;c. <span class=\"citation\">Ḥull. V, 3</span> <span dir=\"rtl\">בזמן שאין לו ר׳</span> when there is no interval of time between the sale of the dam for slaughter and that of her young. <span class=\"citation\">Koh. R. to I, 7</span> <span dir=\"rtl\">ארבע … ר׳ בין וכ׳</span> there was a space of four cubits between each two. <span class=\"citation\">Ber. 15ᵇ</span> <span dir=\"rtl\">שיתן ר׳ בין הדבקים</span> he must allow an interval between words that may easily run into each other; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>ease, relief</i>. <span class=\"citation\">Tosef. Sot. II, 3</span> <span dir=\"rtl\">שאם … בצער יולדת בר׳</span> if (before she was tested) she used to give birth with great pains, she would now do so with ease; <span class=\"citation\">Num. R. s. 9</span><sup>41</sup>; <span class=\"citation\">Ber. 31ᵇ</span>. Tanḥ. Vayishl. 8 <span dir=\"rtl\">כשהיית בצרה … בר׳ וכ׳</span> when thou wast in trouble, thou didst make a vow, but now that thou art relieved, thou forgettest; a. e.</div><div class=\"sense\"><b>—3)</b> <i>profit, gain</i>. <span class=\"citation\">Midr. Till. to Ps. XCII</span>; <span class=\"citation\">Yalk. ib. 843</span> <span dir=\"rtl\">והיו … את הר׳ שהרויח</span></div>","alt":["רֵוַח","רֵי׳"]},"28874":{"h":"רְוַוח ²","r":"T00329","html":"<div class=\"sense\"><b>1)</b> <i>open space, room</i>. <span class=\"citation\">Targ. O. Num. XXXV, 2</span> (ed. Berl. <a href=\"#\" data-headword=\"רָוַח\">רַוַח</a>; ed. Vien. <a href=\"#\" data-headword=\"רָוַח\">רֶוַח</a>; h. text <a href=\"#\" data-headword=\"מִגְרָשׁ\">מגרש</a>). <span class=\"citation\">Targ. O. Lev. XXV, 34</span>. <span class=\"citation\">Targ. Ez. XLV, 2</span> (ed. Wil. <a href=\"#\" data-headword=\"רְוָוחָא\">רְוָחָא</a>). <span class=\"citation\">Targ. O. Gen. XXXII, 17</span> (ed. Vien. <span dir=\"rtl\">רְוָ׳</span>); a. fr.—<span class=\"citation\">Meg. 7ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"בְּסוּמָא\">בְּסוּמָא</a>. <span class=\"citation\">Sabb. 146ᵇ</span> <span dir=\"rtl\">לא הוה ליה ר׳</span> he had no room (to accommodate all his hearers); a. e.—Pl. <span dir=\"rtl\">רַוְוחִין</span>, <span dir=\"rtl\">רַוְוחַיָּא</span>, <a href=\"#\" data-headword=\"רְוָוחָא\">רַוְח׳</a>, <a href=\"#\" data-headword=\"רְוָוחָא\">רְוָח׳</a>. <span class=\"citation\">Targ. O. Num. XXXV, 4</span>, sq. (ed. Vien. <span dir=\"rtl\">רְוָ׳</span>). <span class=\"citation\">Targ. Josh. XIV, 4</span> (ed. Wil. <span dir=\"rtl\">רְוָ׳</span>); a. fr.—[<span class=\"citation\">Targ. Y. I Deut. XXXII, 24</span> <span dir=\"rtl\">רווחין</span>, read: <span dir=\"rtl\">רוּחִין</span>, v. <a href=\"#\" data-headword=\"רְוַוח ²\"><span dir=\"rtl\">רְוַוח</span> I</a>.]</div><div class=\"sense\"><b>—2)</b> <i>relief</i>. <span class=\"citation\">Targ. O. Ex. IX, 28</span>. <span class=\"citation\">Targ. Esth. IV, 14</span>. <span class=\"citation\">Targ. Is. XXXII, 15</span> (h. text <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a>!); a. e.—<span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\">בשעת רַוְוחֵיה</span>, v. <a href=\"#\" data-headword=\"אֲנַנְקָא\">אֲנַנְקָא</a>; <span class=\"citation\">Koh. R. to I, 12</span>; <span class=\"citation\">Gen. R. s. 81</span>, a. e., v. <a href=\"#\" data-headword=\"עָקַת\">עַקְתָא</a>. <span class=\"citation\">Pes. 112ᵇ</span> <span dir=\"rtl\">שבק לי ר׳ פורתא</span> allow me a little relief (liberty); a. e.</div><div class=\"sense\"><b>—3)</b> <i>ample provision, comfort</i>. <span class=\"citation\">Keth. 69ᵃ</span> <span dir=\"rtl\">דאיכא רְוַוח ביתא</span> there is ample provision in the house (she is sufficiently provided for). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אנא ר׳ ביתא מהני וכ׳</span> I mean ample provision out of that estate. <span class=\"citation\">Ib. 80ᵃ</span> sq. <span dir=\"rtl\">כי … משום ר׳ ביתא וכ׳</span> the scholars allowed the husband the fruition of the wife’s property for the sake of domestic comfort, but not to the extent of selling the products. <span class=\"citation\">Ib. 80ᵇ</span> <span dir=\"rtl\">משום ר׳ ביתא הא קא רְוַוח</span> fruition is allowed him for the sake of domestic comfort, and the comfort of the house remains secured; a. e.—<span class=\"citation\">B. Kam. 116ᵃ</span> <span dir=\"rtl\">לר׳ דמילתא הוא דעבד</span> he did it for the convenience of the thing, i.e. as an extraordinary, though not legally necessary, measure, to avoid litigation.</div>","alt":["רְוַח II","רַוְוחָא","רַוְחָא"]},"28875":{"h":"רְוָוחָא","r":"T00330","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְוַוח ²\">same</a>, <i>wide space, relief</i>. <span class=\"citation\">Targ. Ps. XVIII, 20</span>; <span class=\"citation\">Targ. II Sam. XXII, 20</span>. <span class=\"citation\">Targ. Ps. LXVI, 12</span> (h. text <span dir=\"rtl\">רויה</span>); a. e.—[<span class=\"citation\">Targ. Ps. XXIII, 5</span>, v. <a href=\"#\" data-headword=\"רְוִיתָא\">רְוִיתָא</a>.]</div>","alt":["רְוַוחְתָּא","רְוַחְ׳","רְוָחָא"]},"28876":{"h":"רְוָוחָה","r":"T00331","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"רְוָוחָא\">same</a>, <i>width; relief, ease</i>. <span class=\"citation\">Ab. I, 5</span> <span dir=\"rtl\">יהי ביתך פתוח לר׳</span> let thy house be wide open (hospitable); <span class=\"citation\">Ab. d’R. N. ch. VII</span>.—Y. Sot. X, 24ᵃ bot. <span dir=\"rtl\">בשעה שישראל בצרה ואו&quot;ה בר׳</span> when Israel is in distress and the nations are at ease; (Bab. <span class=\"citation\">ib. 48ᵃ</span> <span dir=\"rtl\">בנחת ובשלוה</span>; <span class=\"citation\">Tosef. ib. XIII, 9</span> <span dir=\"rtl\">בשלוה</span>); a. e.</div>","alt":["רְוָחָה"]},"28877":{"h":"רְוַוחְתָּא","r":"T00332","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוָוחָא\">רְוָוחָא</a></div>","alt":[]},"28878":{"h":"רַווחָתָא","r":"T00333","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> [<i>Wide Places</i>,] <i>Ravḥatha</i>. <span class=\"citation\">Targ. Y. Gen. XXVI, 22</span> (h. text <span dir=\"rtl\">רְחֹבוֹת</span>).</div>","alt":[]},"28879":{"h":"רְוֵוי","r":"T00334","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוֵי\">רְוֵי</a>, <a href=\"#\" data-headword=\"רַוֵּי\">רַוֵּי</a>, <a href=\"#\" data-headword=\"רְוִיָּה\"><a href=\"#\" data-headword=\"רְוִיָּה\">רְוִיָּה</a>.</a></div>","alt":["רַוֵּוי","רְוִויָּיה"]},"28880":{"h":"רַוָּוק","r":"T00335","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּק\">רוּק</a>; cmp. <a href=\"#\" data-headword=\"פָּנוּי\">פָּנוּי</a>) <i>single, bachelor</i>. <span class=\"citation\">Kidd. IV, 13</span> <span dir=\"rtl\">לא ילמד אדם ר׳ סופרים</span> a single man must not be a teacher of primary classes. <span class=\"citation\">Ib. 14</span>. <span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">ר׳ הדר וכ׳</span> a bachelor that lives in a large city and does not sin. <span class=\"citation\">Lev. R. s. 27</span> (ref. to <span class=\"citation\">Job XLI, 3</span>) <span dir=\"rtl\">זה ר׳ הדר וכ׳</span> this refers to a bachelor (childless man) that dwells in a community and contributes towards the maintenance of teachers of Bible and Mishnah. Tanḥ. Aḥăré, ed. Bub. 15 <span dir=\"rtl\">לעשיר גדול ר׳ וכ׳</span> like a very rich but unmarried man; having no wife, he has no house; Tanḥ. l. c. 10 <span dir=\"rtl\">וחזק</span> (corr. acc.); <span class=\"citation\">Yalk. Ps. 767</span>; a. e.—Pl. <span dir=\"rtl\">רַוָּוקִים</span>, <span dir=\"rtl\">רַוָּוקִין</span>. Kidd. l. c. <span dir=\"rtl\">לא ישנו שני ר׳ וכ׳</span> two bachelors should not sleep wrapped up in one cloak; Tosef. ib. V, 10. Mekh. Bo, s. 13 <span dir=\"rtl\">וכולן בכורים מר׳ אחרים</span> and they were all firstborn sons of other young men (not the husbands).</div>","alt":[]},"28881":{"h":"רְוָוקָא","r":"T00336","html":"<div class=\"sense\">—<i>pl.</i> <span dir=\"rtl\">רְוָוקֵי</span>, <a href=\"#\" data-headword=\"רוקי\">רְוָקֵי</a>. <span class=\"citation\">Targ. Is. XL, 30</span> (ed. Ven. <span dir=\"rtl\">רֵיקֵי</span>; h. text <span dir=\"rtl\">בחורים</span>).</div>","alt":["רְוָקָא I"]},"28882":{"h":"רְוָוקָא II","r":"T00337","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רוק <i>to be clear</i>, v. Fl. to Levy Talm. Dict. IV, p. 486) <i>straining bag</i>. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">בדר׳</span> when the drink is made by pouring water on the strainer (and the lees contained in it), opp. <span dir=\"rtl\">דפורצנא</span>.—Pl. <span dir=\"rtl\">רְוָוקֵי</span>. <span class=\"citation\">Ab. Zar. 75ᵃ</span> <span dir=\"rtl\">הני ר׳ דארמאי וכ׳</span></div>","alt":[]},"28883":{"h":"רְוַז","r":"T00338","html":"<div class=\"sense\"> [<i>to sprout forth</i>, v. P. Sm. 3845,] <i>to be glad, bright</i>. <span class=\"citation\">Targ. Prov. XIII, 9</span> (some ed. <span dir=\"rtl\">נירוון</span>, read: <span dir=\"rtl\">נִירְוַוז</span>; h. text <span dir=\"rtl\">שמח</span>). <span class=\"citation\">Ib. XI, 10</span> Bxt. (ed. <a href=\"#\" data-headword=\"דּוּץ\">דוץ</a>; ed. Ven. <span dir=\"rtl\">דון</span>, corr. acc.). <span class=\"citation\">Ib. XXIII, 16</span>.</div>","alt":["רְוַוז"]},"28884":{"h":"*רוֹז","r":"T00339","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוַז\">preced.</a>) <i>joy</i> (?). <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">ר׳ פפא</span> (Ms. M. <a href=\"#\" data-headword=\"רָז\">רז</a>) Papa’s Joy (?), name of a measure introduced by Papa, v. <a href=\"#\" data-headword=\"*דּוֹן\">דּוֹן</a>.</div>","alt":[]},"28885":{"h":"רוֹזְגָר","r":"T00340","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*רוּנְגָּר\">רוּנְגָּר</a></div>","alt":[]},"28886":{"h":"רוּזִינְקָא","r":"T00341","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">רוזיקא</span>; Pers.) <i>provisions for the day</i>. <span class=\"citation\">Taan. 23ᵇ</span> Ar. (Var. in Ar. as ed. <a href=\"#\" data-headword=\"עִיבּוּר ²\">עיבורא</a>). <span class=\"citation\">Men. 69ᵇ</span> נחיתא ליה ר׳ וחטי Ar. (read: <span dir=\"rtl\">דחיטי</span>; Var. in Ar. s. v. <a href=\"#\" data-headword=\"עדי\">עדי</a>: <span dir=\"rtl\">רוסנין קב חיטי</span>; ed. <span dir=\"rtl\">רום כיזבא חיטי</span> or <a href=\"#\" data-headword=\"נִזְבָּא\">נזבא</a>; v. Rabb. D. S. a. l. note 80) provisions of wheat came down (from heaven) covering a space of three parasangs, v. <a href=\"#\" data-headword=\"נִזְבָּא\">נִזְבָּא</a>.</div>","alt":[]},"28887":{"h":"רוֹזֶן","r":"T00342","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> רזן <i>to be strong, heavy</i>) <i>prince.</i>—Pl. <span dir=\"rtl\">רוֹזְנִים</span>. <span class=\"citation\">Snh. 70ᵇ</span> (ref. to <span class=\"citation\">Prov. XXXI, 4</span>) <span dir=\"rtl\">מי שכל רוֹזְנֵי עולם וכ׳</span> should he at whose door the princes of the world appear every morning, drink wine and become drunken? <span class=\"citation\">Num. R. s. 10</span>. <span class=\"citation\">Lev. R. s. 12</span>, end (ref. to Prov. l. c.) <span dir=\"rtl\">שני ר׳ היו לי וכ׳</span> two princes (Nadab and Abihu) were mine, and they died only on account of wine; <span class=\"citation\">Yalk. Jer. 320</span>; a. e.</div>","alt":[]},"28888":{"h":"רָוַח","r":"T00343","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">רווח</span>.</div>","alt":["רְוַח","רֶוַח"]},"28889":{"h":"רוּחַ I","r":"T00344","html":"<div class=\"sense\"><i>to smell</i>, v. <a href=\"#\" data-headword=\"רִיחַ\">רִיחַ</a>.</div>","alt":[]},"28890":{"h":"רוּחַ II","r":"T00345","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>wind, air; direction, side</i>. <span class=\"citation\">Ex. R. s. 15</span><sup>22</sup> <span dir=\"rtl\">שלשה בריות … המים והר׳ וכ׳</span> three creations preceded the formation of the world: water, air, and fire; <span dir=\"rtl\">הר׳ הרה וכ׳</span> the air (spirit) conceived and gave birth to wisdom. <span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">הכל בר׳</span> all (diseases) are caused by the air. <span class=\"citation\">Ḥag. 12ᵃ</span> <span dir=\"rtl\">עשרה … ר׳ ומים וכ׳</span> ten things were created on the first day: heaven …, air and water &amp;c. <span class=\"citation\">Ib. 12ᵇ</span> <span dir=\"rtl\">הרים בר׳</span> the mountains are sustained by the air, <span dir=\"rtl\">ר׳ בסערה</span> the air by the wind-storm.—<span class=\"citation\">Ber. 31ᵃ</span> <span dir=\"rtl\">יכול … לכל ר׳ שירצה</span> you may think a man may pray facing any direction he may desire. <span class=\"citation\">B. Bath. 22ᵇ</span> <span dir=\"rtl\">מר׳ אחת</span> from one side. <span class=\"citation\">Ib. II, 9</span> <span dir=\"rtl\">לכל ר׳ עושה וכ׳</span> one may erect a tannery on any side of the town except the western. <span class=\"citation\">Ib. 25ᵇ</span> <span dir=\"rtl\">ר׳ דרומית</span> the southern wind. <span class=\"citation\">Kil. V, 5</span>; a. v. fr.—Pl. <span dir=\"rtl\">רוּחוֹת</span>. <span class=\"citation\">Ab. III, 17</span> <span dir=\"rtl\">שאפי׳ כל הר׳ וכ׳</span> even if all the winds were to come and blow at them &amp;c. <span class=\"citation\">Kil. III, 1</span> <span dir=\"rtl\">בארבע ר׳ הערוגה</span> on the four sides of the bed. Y. ib. VI, end, 30ᶜ <span dir=\"rtl\">מגופף מארבע רוּחוֹתָיו</span> enclosed on its four sides. <span class=\"citation\">Pes. 94ᵃ</span> <span dir=\"rtl\">לארבע ר׳ העולם</span> he may turn towards any of the four directions of the world; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>mind, disposition, spirit</i>. <span class=\"citation\">Ab. III, 10</span>, v. <a href=\"#\" data-headword=\"נוּחַ\">נוּחַ</a> h. <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot., a. e., v. <a href=\"#\" data-headword=\"הֲנָחָה\">הֲנָחָה</a>. <span class=\"citation\">Ab. IV, 7</span>, v. <a href=\"#\" data-headword=\"גַּס III\"><span dir=\"rtl\">גַּס</span> III</a>. <span class=\"citation\">Ib. V, 19</span> <span dir=\"rtl\">ר׳ נמוכה</span> a lowly spirit; a. v. fr.</div><div class=\"sense\"><b>—3)</b> <i>spirit, soul</i>. <span class=\"citation\">Gen. R. s. 7</span>, end <span dir=\"rtl\">נפש חיה זה רוּחוֹ של וכ׳</span> ‘a living soul’ (<span class=\"citation\">Gen. II, 19</span>), this means the soul of Adam. <span class=\"citation\">Gen. R. s. 2</span> ורוח אלהים זו רוחו וכ׳ ‘and the spirit of God’ (<span class=\"citation\">Gen. I, 2</span>), this means the soul of the king Messiah; a. v. fr.—Esp. <span dir=\"rtl\">ר׳ הקדש</span> (abbr. <span dir=\"rtl\">רוה&quot;ק</span>) <i>the holy spirit, prophetic inspiration, intuition</i>. <span class=\"citation\">Ab. Zar. 20ᵇ</span> <span dir=\"rtl\">קדושה … רוה&quot;ק</span> sanctity (of life) leads to prophetic inspiration. <span class=\"citation\">Meg. 7ᵃ</span> <span dir=\"rtl\">אסתר ברוה&quot;ק וכ׳</span> the Book of Esther was composed in a spirit of prophecy. <span class=\"citation\">Yoma 9ᵇ</span> <span dir=\"rtl\">משמתו … נסתלקה רוה&quot;ק וכ׳</span> with the death of the last prophets, Haggai …, the prophetic spirit was withdrawn from Israel. <span class=\"citation\">Ber. 10ᵃ</span> חזאי לי ברוה&quot;ק וכ׳ I saw in a prophetic vision that unworthy children would go forth &amp;c.; a. v. fr.—Snḥ. 65ᵇ, a. fr. <span dir=\"rtl\">ר׳ טומאה</span></div><div class=\"sense\"><b>—4)</b>  (<i>evil</i>) <i>spirit, demon</i>. <span class=\"citation\">Pes. 112ᵃ</span> <span dir=\"rtl\">ר׳ רעה</span> (<span dir=\"rtl\">סכנת</span>) the danger threatening from an evil spirit; a. fr.—<span dir=\"rtl\">ר׳ צרדה</span>, <span dir=\"rtl\">ר׳ צרעת</span>, <span dir=\"rtl\">ר׳ תזזית</span> &amp;c., v. respective determinants.—Pl. <span dir=\"rtl\">רוּחוֹת</span>, <span dir=\"rtl\">רוּחִין</span>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">ר׳ הזכרים</span> male demons; <span dir=\"rtl\">ר׳ נקבות</span> female demons. <span class=\"citation\">Erub. 18ᵇ</span> <span dir=\"rtl\">הוליד ר׳ ושדין וכ׳</span> begot spirits and demons &amp;c.; a. fr.</div>","alt":[]},"28891":{"h":"רוּחָא","r":"T00346","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 2</span>. <span class=\"citation\">Ib. VIII, 1</span>. <span class=\"citation\">Ib. VI, 17</span>. <span class=\"citation\">Ib. XLV, 27</span> <span dir=\"rtl\">רוח נבואה</span> (O. ed. Berl. <a href=\"#\" data-headword=\"קוֹדַשׁ\">קודשא</a>) = h. <span dir=\"rtl\">רוח הקדש</span>, v. <a href=\"#\" data-headword=\"רוּחַ II\">preced.</a>; a. v. fr.—<span class=\"citation\">Gen. R. s. 38</span>, end <span dir=\"rtl\">נסגוד לר׳ וכ׳</span> let us worship the wind that scatters the clouds; <span dir=\"rtl\">ונסגוד לבר … ר׳</span> let us worship man that carries the wind (whose body is filled with air). <span class=\"citation\">Gitt. 67ᵇ</span> <span dir=\"rtl\">דהא ר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"קוּרְדְּיָיקוֹס\">קוּרְדְּיָיקוֹס</a>; a. fr.—Pl. <span dir=\"rtl\">רוּחִין</span>, <span dir=\"rtl\">רוּחַיָּא</span>, <span dir=\"rtl\">רוּחֵי</span>, <span dir=\"rtl\">רוּחָתָא</span>. <span class=\"citation\">Targ. O. Num. XVI, 22</span>. <span class=\"citation\">Targ. Deut. XXXII, 24</span>. <span class=\"citation\">Targ. Y. I ib.</span> <span dir=\"rtl\">רווחין</span> (corr. acc.), v. <a href=\"#\" data-headword=\"רְוַוח ²\"><span dir=\"rtl\">רְוַוח</span> I</a>; a. fr.—Y. Shek. V, end, 49ᵇ <span dir=\"rtl\">רבהון דרוּחַיָּיא</span> the chief of the evil spirits. <span class=\"citation\">Gen. R. s. 20</span>, end <span dir=\"rtl\">ר׳ דביתא טבין וכ׳</span> the spirits of a man’s house are benevolent, for they grow up with him; <span dir=\"rtl\">ר׳ דחקלא</span> the spirits of the field; ib. s. 24, end. <span class=\"citation\">Lev. R. s. 5</span> שידא שריהון דר׳ Sheda (demon), the prince of the spirits. <span class=\"citation\">B. Bath. 25ᵃ</span> <span dir=\"rtl\">לכל ר׳ אוקמן וכ׳</span> place me (for prayer) in any direction except due east; a. fr.</div>","alt":[]},"28892":{"h":"רַוְחָא","r":"T00347","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוַוח ²\">רַוְוחָא</a>, <a href=\"#\" data-headword=\"רְוָוחָא\"><a href=\"#\" data-headword=\"רְוָוחָא\">רְוָוחָא</a>.</a></div>","alt":["רְוָחָא"]},"28893":{"h":"רוֹחַב","r":"T00348","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֹחַב\">רֹחַב</a></div>","alt":[]},"28894":{"h":"רוּחְצָן","r":"T00349","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחֵץ\">רְחֵץ</a>) <i>safety, reliance, security, faith</i>. <span class=\"citation\">Targ. Gen. XXXIV, 25</span>. <span class=\"citation\">Targ. II Chr. XXXII, 22</span>. <span class=\"citation\">Targ. II Kings XVIII, 9</span>. <span class=\"citation\">Targ. Ps. XXXVI, 8</span> <span dir=\"rtl\">ישרון לר׳</span> (Ms. <span dir=\"rtl\">יתרחצון</span>); a. fr.—Pl. <span dir=\"rtl\">רוּחְצָנַיָּא</span>. <span class=\"citation\">Targ. Jer. II, 37</span>.</div>","alt":["רוּחְצָנָא","רוֹ׳","רָחֲצָ׳"]},"28895":{"h":"רוֹחַק","r":"T00350","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָחִיק I\"><span dir=\"rtl\">רָחִיק</span> I</a></div>","alt":[]},"28896":{"h":"קסטירא","r":"S01650","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסִּיטְרָא\">קַסִּיטְרָא</a></div>","alt":[]},"28897":{"h":"קסטל","r":"S01651","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 19</span> ק׳ מלכים Ar., read with ed. <span dir=\"rtl\">טרסקל נקוב</span>.</div>","alt":[]},"28898":{"h":"קַסְטְלִין","r":"S01652","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (castellum, καστέλλιν S.) </div><div class=\"sense\"><b>1)</b> <i>fort, castle</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> <span dir=\"rtl\">נפל ק׳ דטיבריא</span> (ed. Krot. <a href=\"#\" data-headword=\"קסיטולין\">קסיטולין</a>, corr. acc.) the castle of Tiberias fell in (burying the idol placed therein).</div><div class=\"sense\"><b>—2)</b> <i>reservoir</i>. <span class=\"citation\">Tosef. Mikv. IV, 6</span> <span dir=\"rtl\">ק׳ המחליק מים וכ׳</span> a reservoir which distributes water (in pipes) in the cities.</div>","alt":[]},"28899":{"h":"קַסְטְרָא","r":"S01653","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (castra, pl.) </div><div class=\"sense\"><b>1)</b> <i>fortification, military camp</i>. <span class=\"citation\">B. Kam. 98ᵃ</span> <span dir=\"rtl\">היו לו מעות בק׳ או וכ׳</span> if one has money deposited in the (Roman) camp or in the (forts of the) king’s Mountain. <span class=\"citation\">Num. R. s. 12</span> (expl. <span dir=\"rtl\">מצודתי</span>, <span class=\"citation\">Ps. XCI, 2</span>) <span dir=\"rtl\">ק׳ דירי</span> my fortification; Midr. Till. to Ps. l. c. (not <span dir=\"rtl\">קסטרי</span>). <span class=\"citation\">Lam. R. to III, 7</span> <span dir=\"rtl\">זה ק׳ של פרסיין</span> (read: <span dir=\"rtl\">רומיים</span>) this alludes to the camp of the Romans; <span class=\"citation\">Yalk. ib. 1037</span> <a href=\"#\" data-headword=\"קנטרה\">קנטרה</a> (corr. acc.). <span class=\"citation\">Deut. R. s. 1</span> (expl. <span dir=\"rtl\">נציבים</span>, <span class=\"citation\">II Sam. VIII, 6</span>) <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (not <a href=\"#\" data-headword=\"קסטרס\">קסטרס</a>); a. e.—Pl. <span dir=\"rtl\">קַסְטְרָאוֹת</span>, <span dir=\"rtl\">קַסְטְרָיוֹת</span>. <span class=\"citation\">Tosef. Ohol. XVIII, 12</span> <span dir=\"rtl\">הק׳ והלגיונות</span> the dwellings in forts and in the (camps of the) legions. <span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">היו … אהליות וק׳</span> they would have surrounded it (the Tabernacle) with tents and forts (to protect it); <span class=\"citation\">Cant. R. to II, 3</span>; <span class=\"citation\">Num. R. s. 1</span>; a. e.—V. <a href=\"#\" data-headword=\"גַּסְטְרָא\">גַּסְטְרָא</a>.—2) pr. n. pl. <i>Castra</i>, near Haifa (Castellum peregrinum). <span class=\"citation\">Cant. R. to II, 2</span>; <span class=\"citation\">Lam. R. to I, 17</span> as hostile as <span dir=\"rtl\">ק׳ לחיפה</span> Castra to Haifa.—V. <a href=\"#\" data-headword=\"קַצְרָא III\"><span dir=\"rtl\">קַצְרָא</span> III</a>.</div>","alt":["קַסְטְרָה"]},"28900":{"h":"קַסִּטְרוֹן","r":"S01654","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסִּיטְרוֹן\">קַסִּיטִרוֹן</a></div>","alt":[]},"28901":{"h":"קסטרס","r":"S01655","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסְטְרָא\">קַסְטְרָא</a></div>","alt":[]},"28902":{"h":"קסיא","r":"S01656","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְסִיָּיה\">קְסִיָּיה</a></div>","alt":["קְסִיָּה"]},"28903":{"h":"קסיוהא","r":"S01657","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. LXXV</span> ed. pr., read: <a href=\"#\" data-headword=\"קִיּוּהָא\">קִיּוּהָא</a>.</div>","alt":[]},"28904":{"h":"קסיט","r":"S01658","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיסְטְ\">קִיסְטְ</a></div>","alt":[]},"28905":{"h":"קסיטולין","r":"S01659","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַסְטְלִין\">קַסְטְלִין</a></div>","alt":[]},"28906":{"h":"קַסִּיטְרָא","r":"S01660","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κασσίτερος, cassiterum) <i>tin</i>. <span class=\"citation\">Targ. Y. I Num. XXXI, 22</span>, <span class=\"citation\">Targ. Y. II, Num. XXXI, 22</span> <a href=\"#\" data-headword=\"קסטירא\">קסטירא</a>, <a href=\"#\" data-headword=\"קיסטרא\">קיסטרא</a> (corr. acc.; h. text <span dir=\"rtl\">בדיל</span>).—Tanḥ. Shof’ṭim 14 <span dir=\"rtl\">כלי זין קסטיא</span> (corr. acc.) tinplated armor (v. Sm. Ant. s. v. Stamnum).</div>","alt":[]},"28907":{"h":"קַסִּיטְרוֹן","r":"S01661","html":"<div class=\"sense\"> m. <a href=\"#\" data-headword=\"קַסִּיטְרָא\">same</a>. Y. Snh. VII, 24ᵇ bot. (expl. <span dir=\"rtl\">בעץ</span>) <span dir=\"rtl\">אבר וקסטיטיריון מעורבין</span> (corr. acc., or <a href=\"#\" data-headword=\"קַסִּיטְרוֹן\">קַסִּיטִירוֹן</a>) lead and tin mixed. <span class=\"citation\">Tosef. Kel. B. Kam. VII, 7</span> <span dir=\"rtl\">אין מקיפין בק׳ וכ׳</span> you must not make a rim of tin, because &amp;c., v. <a href=\"#\" data-headword=\"פָּתִיל\">פָּתִיל</a>. <span class=\"citation\">Ib. III, 4</span> <span dir=\"rtl\">ועשאה בבעץ ובקנטרין</span> (corr. acc.) and mended it with tin or cassiterum (v. <a href=\"#\" data-headword=\"בַּעַץ\">בַּעַץ</a>); ib. <span class=\"citation\">B. Mets. I, 8</span>. <span class=\"citation\">Tosef. B. Bath. V, 9</span> <span dir=\"rtl\">של בעץ ושל אבר ושל קסטירון</span> ed. Zuck. (oth. ed. <a href=\"#\" data-headword=\"קיספורון\">קיספורון</a>, corr. acc.) weights of tin, or of lead, or of cassiterum; <span class=\"citation\">B. Bath. 89ᵇ</span> <span dir=\"rtl\">גיסטרין</span>, v. <a href=\"#\" data-headword=\"גַּסִּיטְרוֹן\">גַּסִּיטְרוֹן</a>.</div>","alt":["קַסִּטְ׳"]},"28908":{"h":"קְסִיָּיה","r":"S01662","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קסי</span> = <a href=\"#\" data-headword=\"כסי ²\"><span dir=\"rtl\">כָּסָה</span> II</a>) [<i>cover, protection</i>,] </div><div class=\"sense\"><b>1)</b>  a sort of <i>glove</i> for laborers. <span class=\"citation\">Kel. XVI, 6</span> (ed. Dehr. <a href=\"#\" data-headword=\"קסיא\">קְסִיָּה</a>).</div><div class=\"sense\"><b>—2)</b>  ק׳ של שלחנות <i>table cloth</i>, a sheet spread over the set table to protect it from flies &amp;c. <span class=\"citation\">Makhsh. V, 8</span> <a href=\"#\" data-headword=\"קסיא\">קסיה</a> ed. Dehr. (ed. <a href=\"#\" data-headword=\"קסיא\">קסיא</a>); [Ar.: <i>vessels</i>, cmp. <a href=\"#\" data-headword=\"קִסְוָה\">קִסְוָה</a>,—which, however, does not suit the context].</div>","alt":[]},"28909":{"h":"קסילופונוס","r":"S01663","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of ξύλον a. φάνος, a compound not otherwise recorded) <i>a torch made of wooden staves</i>, esp. <i>of vines</i>. Pesik. Ḳumi, p. 144ᵇ sq. <span dir=\"rtl\">עתידה … לעשות ק׳ וכ׳</span> (ed. <span dir=\"rtl\">קסילפנוס</span>, Ms. O. <span dir=\"rtl\">כסיל פנים</span>, corr. acc.) in the future Jerusalem shall be a torch for the nations, and they shall walk by its light (ref. to <span class=\"citation\">Is. LX, 3</span>); <span class=\"citation\">Yalk. Is. 359</span> only <a href=\"#\" data-headword=\"פָּנָס\">פָּנָס</a>; <span class=\"citation\">Midr. Till. to Ps. XXXVI, 10</span> (missing in ed. Bub.) <a href=\"#\" data-headword=\"מטרפולין\">מטרפולין</a> (corr. acc.). <span class=\"citation\">Koh. R. to I, 9</span> <span dir=\"rtl\">פעם אחת … ק׳ אחד משלכם</span> (ed. <span dir=\"rtl\">קסלפנוס</span>, <span dir=\"rtl\">ניס …</span>) once the (Roman) government sent word to our teachers, ‘send us one of your torches.’—Pl. <span dir=\"rtl\">קְסִילוֹפַנְסִין</span>. Ib. [read:] <span dir=\"rtl\">אמרו כמה ק׳ יש להם והם מבקשין ממנו קסילופנוס אחד כמדומין וכ׳</span> (strike out <span dir=\"rtl\">כמה מקות פנסין יש להם</span>, as a corrupt Var. Lect., and <span dir=\"rtl\">כמה אבנים טובים ומרגליות יש להם</span> as an erroneous gloss) they said, they have ever so many torches, and they ask us for one torch? It seems to us, they mean one enlightening the countenances of men with his learning.</div>","alt":["קְסִילוֹפָנוֹס"]},"28910":{"h":"קסלפונוס","r":"S01664","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קסילופונוס\">preced.</a></div>","alt":["קסלפינוס","קסלפיניס"]},"28911":{"h":"קָסַם","r":"S01665","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cut, carve</i>. <span class=\"citation\">Snh. IX, 6</span> <span dir=\"rtl\">המקלל בקוֹסֵם</span> (Y. ed. <span dir=\"rtl\">בקַסָּם</span>) he that curses (his neighbor) invoking God as ‘a carver’ (instead of <i>creator ex nihilo</i>); expl. ib. 81ᵇ <span dir=\"rtl\">יכה קוֹסֵם את קוֹסָמוֹ</span> (Ms. M. <span dir=\"rtl\">את קוסו</span>, emended <span dir=\"rtl\">קוסמו</span>, Ar. <span dir=\"rtl\">קִסְמוֹ</span>, <span dir=\"rtl\">קִיסְמוֹ</span>) may the carver strike his carving; anoth. explan. <span dir=\"rtl\">יכהו קוסם לו ולקונו ולמקנו</span> may the carver strike him (euphem. for <i>thee</i>), himself (thyself) &amp;c., v. <a href=\"#\" data-headword=\"קָנָה\">קָנָה</a>; Y. ib. IX, end, 27ᵇ, v. <a href=\"#\" data-headword=\"*קַיְינָא\">קַיְינָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to decide</i> (cmp. <a href=\"#\" data-headword=\"גָּזַר\">גָּזַר</a>). <span class=\"citation\">Ḥag. 14ᵃ</span> (ref. to <span class=\"citation\">Is. III, 2</span>) <span dir=\"rtl\">קוסם זה מלך</span> <i>ḳosem</i> means king (with ref. to <span class=\"citation\">Prov. XVI, 10</span>); <span class=\"citation\">Yalk. Is. 261</span>.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"קֶסֶם\">קֶסֶם</a>) <i>to divine</i>. <span class=\"citation\">Sifré Deut. 171</span> <span dir=\"rtl\">איזהו קוסם זה האוחז וכ׳</span> who is a <i>ḳosem?</i> He that seizes his staff (and measuring it fist-wise says), shall I or shall I not go? (ref. to <span class=\"citation\">Hos. IV, 12</span>); <span class=\"citation\">Yalk. Deut. 918</span>. <span class=\"citation\">Snh. 106ᵃ</span> (ref. to <span class=\"citation\">Josh. XIII, 22</span>) <span dir=\"rtl\">קזסם נביא הוא</span> a charmer? is he not a prophet? <span dir=\"rtl\">בתחלה נביא ולבסוף קוסם</span> at first a prophet, and in the end a charmer. <span class=\"citation\">Num. R. s. 20</span> (ref. to <span class=\"citation\">Num. XXII, 7</span>) <span dir=\"rtl\">הוליכו … קסמים שהיו קוֹסְמִין בהן</span> they carried with them all kinds of divining implements with which people divine. <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">לִקְסוֹם קסמים</span>, v. <a href=\"#\" data-headword=\"קֶסֶם\">קֶסֶם</a>; a. e.</div><div class=\"sense\"><b>Pi. קִסֵּם</b> <div class=\"sense\"><i>to divine</i>. <span class=\"citation\">Midr. Till. to Ps. LXXIX</span>, beg. <span dir=\"rtl\">עמד לו מְקַסֵּם וכ׳</span> he stood up and divined to find out whether or not to go up.</div></div><div class=\"sense\"><b>Nithpa. נִתְקַסֵּם</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְסֵם\">קִרְסֵם</a></div></div>","alt":[]},"28912":{"h":"קְסַם I","r":"S01666","html":"<div class=\"sense\"><b>1)</b> <i>to cut, chip</i>. <span class=\"citation\">Y. Shebi. II, 34ᵃ</span> <span dir=\"rtl\">וקַסְמָהּ בידיה וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to divine</i>. <span class=\"citation\">Targ. Ez. XXI, 26</span>. <span class=\"citation\">Targ. Deut. XVIII, 10</span> <span dir=\"rtl\">קָסֵים</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"קְסַם I\">קָסֵם</a>, incorr. <a href=\"#\" data-headword=\"קוֹסֵם\">קוֹסֵם</a>); a. e.—<span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">חזי … קָסֵים אחיך</span> saw a diviner who was divining, and laughed (at him). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לִקְסוֹם … תותיה</span> let him divine what is under him.</div>","alt":[]},"28913":{"h":"קֶסֶם","r":"S01667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קְסַם I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>chip, carving</i>, v. <a href=\"#\" data-headword=\"קָסַם\">קָסַם</a>.—Pl. <span dir=\"rtl\">קְסָמִים</span>, <span dir=\"rtl\">קְסָמִין</span>, v. <a href=\"#\" data-headword=\"קִיסָּם\">קִיסָּם</a>.</div><div class=\"sense\"><b>—2)</b> <i>decision</i>, esp. <i>decision by lot or sign, divination, augury; means or tools of divination.</i> <i>—Pl.</i> as ab. Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">התחיל קוסם ק׳</span> he began to make divinations (by throwing arrows &amp;c.); <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">לקסום ק׳</span>. <span class=\"citation\">Num. R. s. 20</span>, v. <a href=\"#\" data-headword=\"קָסַם\">קָסַם</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שידעו בק׳ שלהם וכ׳</span> they knew that there was no profit in their divining signs; a. fr.</div>","alt":[]},"28914":{"h":"קְסַם II","r":"S01668","html":"<div class=\"sense\"><b>1)</b> <i>decision</i>. <span class=\"citation\">Targ. Prov. XVI, 10</span>.</div><div class=\"sense\"><b>—2)</b> <i>divination, divining tools</i>. <span class=\"citation\">Targ. Ez. XXI, 26</span> (ed. Wil. <a href=\"#\" data-headword=\"קֶסֶם\">קֶסֶם</a>); <span class=\"citation\">27</span>; a. e.—Pl. <a href=\"#\" data-headword=\"קִסְמִית\">קִסְמִין</a>, <span dir=\"rtl\">קִסְמַיָּא</span>, <span dir=\"rtl\">קֻ׳</span>, <a href=\"#\" data-headword=\"קוֹרְטוֹר\">קוּ׳</a>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Targ. Deut. XVIII, 10</span> (Y. II <a href=\"#\" data-headword=\"קוּסְדֹּור\">קַסְ׳</a>). <span class=\"citation\">Targ. Y. Gen. XXX, 27</span>. <span class=\"citation\">Targ. Y. I Deut. XVIII, 14</span> (Y. II, v. <a href=\"#\" data-headword=\"קַסָּמָא\">קַסָּמָא</a>); a. fr.—Y. Maasr. III, end, 51ᵃ, v. <a href=\"#\" data-headword=\"קַנְטֵר\">קַנְטֵר</a>.</div>","alt":["קִסְמָא","קוּ׳","קִי׳"]},"28915":{"h":"קִסָּם","r":"S01669","html":"<div class=\"sense\"><i>chip</i>, v. <a href=\"#\" data-headword=\"קִיסָּם\">קִיסָּם</a>, <a href=\"#\" data-headword=\"קֵיסֶם\"><a href=\"#\" data-headword=\"קֵיסֶם\">קֵיסֶם</a>.</a></div>","alt":["קֵסֶם","קְסַם"]},"28916":{"h":"קְסַם III","r":"S01670","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"קִיסָּם\">קִיסַם</a></div>","alt":[]},"28917":{"h":"קַסָּם","r":"S01671","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָסַם\">קָסַם</a>) <i>carver</i>. <span class=\"citation\">Snh. IX, 6</span> Y. ed., v. <a href=\"#\" data-headword=\"קָסַם\">קָסַם</a>. <span class=\"citation\">Cant. R. to V, 14</span> <span dir=\"rtl\">כל מי שנעשה ק׳ וכ׳</span> he that makes himself a carver (skilful worker) in the words of the Law shall finally become a king (leader) through them (with ref. to <span class=\"citation\">Prov. XVI, 10</span>). [Ib. <span dir=\"rtl\">שנעשה בהם ק׳</span> some ed., read: <a href=\"#\" data-headword=\"סַפִּיר\">סַפִּיר</a>; v. Matt. K. a. l.]</div>","alt":[]},"28918":{"h":"קַסָּמָא","r":"S01672","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְסַם I) <i>diviner, charmer</i>. <span class=\"citation\">Targ. Josh. XIII, 22</span> (not <span dir=\"rtl\">קִ׳</span>).—<span class=\"citation\">Gitt. 68ᵇ</span>, v. <a href=\"#\" data-headword=\"קְסַם I\"><span dir=\"rtl\">קְסַם</span> I</a>.—Pl. <span dir=\"rtl\">קַסָּמַיָּא</span>, <a href=\"#\" data-headword=\"קַסָּמָא\">קָסָ׳</a>, <a href=\"#\" data-headword=\"קוּסְדֹּור\">קָסְ׳</a>, <span dir=\"rtl\">קוֹסְ׳</span>. <span class=\"citation\">Targ. O. Deut. XVIII, 14</span> (Y. II <span dir=\"rtl\">קִסְמֵי</span>, corr. acc.).—<span class=\"citation\">Targ. Zech. X, 2</span>. <span class=\"citation\">Targ. I Sam. VI, 2</span>; a. fr.</div>","alt":["קָסָ׳","קָסְמָא","קוֹ׳"]},"28919":{"h":"קִסְמָא","r":"S01673","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְסַם II\"><span dir=\"rtl\">קְסַם</span> II</a></div>","alt":[]},"28920":{"h":"קִסְמִית","r":"S01674","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיסְמִית\">קִיסְמִית</a></div>","alt":[]},"28921":{"h":"קסנטור","r":"S01675","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְוִיסְטוֹר\">קְוִיסְטוֹר</a></div>","alt":[]},"28922":{"h":"קָסַס","r":"S01676","html":"<div class=\"sense\"><i>Polel</i>) </div><div class=\"sense\"><b>1)</b> <i>to cut</i>, v. <a href=\"#\" data-headword=\"קְסָסָה\">קְסָסָה</a>.—[<span class=\"citation\">Y. Ber. VI, 10ᵇ</span> top <span dir=\"rtl\">הקוֹסֵס את החטים</span> Ar., ed. <span dir=\"rtl\">הכוסס</span>, v. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>.]</div><div class=\"sense\"><b>—2)</b>  (of wine) <i>to bite, have a pungent taste, be sourish</i>. <span class=\"citation\">Y. Pes. II, end, 29ᶜ</span> <span dir=\"rtl\">היה לו יין קוֹסֵס וכ׳</span> had a sourish wine, and he put barley into it that it might become sour (vinegar). <span class=\"citation\">Tosef. B. Bath. VI, 6</span> if one sells a cellar full of wine, <span dir=\"rtl\">מקבל … קוֹסְסוֹת למאה</span> he (the purchaser) must accept ten casks of pungent wine for every hundred. <span class=\"citation\">Maas. Sh. IV, 2</span> היין שקסס Ms. M. (Y. ed. <span dir=\"rtl\">שקִיסֵּס</span>; ed. <span dir=\"rtl\">שקרם</span>, Var. <span dir=\"rtl\">שהִקְסִיס</span>) wine that has turned sourish; a. fr.</div><div class=\"sense\"><b>Pi. קִיסֵּס</b> <div class=\"sense\">; <i>Hif.</i> <span dir=\"rtl\">הִקְסִיס</span>, v. supra.</div></div>","alt":[]},"28923":{"h":"קְסָסָה","r":"S01677","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קְסָסוֹת</span> (<a href=\"#\" data-headword=\"קָסַס\">preced.</a>) <i>lumps, balls</i> (cmp. <span dir=\"rtl\">קְזוֹזוֹת</span>). <span class=\"citation\">Naz. 65ᵃ</span> <span dir=\"rtl\">נוטל את הקיסמין ואת הק׳</span></div>","alt":[]},"28924":{"h":"*קַסְקְסָאָה","r":"S01678","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Ḳasḳ’saah</i>, surname of one R. Isaac. <span class=\"citation\">Ber. 51ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"סַקָּאָה\">סַקָּאָה</a> <i>sack-maker</i> (?); Beth N. <a href=\"#\" data-headword=\"קְטוּסְפָּאָה\">קטוספאה</a>, <i>of Ctesiphon</i>; oth. Var. <span dir=\"rtl\">קרקוסאה</span> <i>of Circesium</i>; v. Rabb. D. S. a. l. note).</div>","alt":[]},"28925":{"h":"קַסְקַסִּין","r":"S01679","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשְׂקֶשֶׂת\">קַשְׂקֶשֶׂת</a></div>","alt":[]},"28926":{"h":"קֵסַר","r":"S01680","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵיסַר\">קֵיסַר</a></div>","alt":[]},"28927":{"h":"קסרטל","r":"S01681","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרַסְטְלִין\">קְרַסְטְלִין</a></div>","alt":[]},"28928":{"h":"קִסְרִי","r":"S01682","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קִיס\">קִיס׳</a>.</div>","alt":["קֵסַרְיוֹן","קִסְרָיָא","קִסרִין"]},"28929":{"h":"קסרין","r":"S01683","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to VII, 11</span> <span dir=\"rtl\">ראש ק׳</span>, a gloss expl. <span dir=\"rtl\">ממונה על האוצרות</span>, prob. meant for <a href=\"#\" data-headword=\"קַסְטְלִין\">קַסְטְרִין</a>; perh. for <a href=\"#\" data-headword=\"סִיקָרִין\">סִיקָרִין</a>.</div>","alt":[]},"28930":{"h":"קְסִרְקִיטוֹן","r":"S01684","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (exercitus, ἐξέρκετον, S.) <i>army</i>. Lam. R. introd. (R. Naḥm.) (ref. to <span class=\"citation\">Is. XXIX, 1</span>) <span dir=\"rtl\">קריה … דוד לק׳ שלו</span> the city which David built for his army; <span class=\"citation\">Yalk. Is. 302</span> <a href=\"#\" data-headword=\"קיסרקיסון\">קיסרקיסון</a> (corr. acc.). <span class=\"citation\">Cant. R. to VIII, 13</span> <span dir=\"rtl\">נטל קצרקטין שלו וכ׳</span> (read: <a href=\"#\" data-headword=\"קְצִרְקְטוֹן\">קְצִרְקְטוֹן</a></div>","alt":[]},"28931":{"h":"קִסְתָּא","r":"S01685","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיסְטְ\">קִיסְטְ</a></div>","alt":[]},"28932":{"h":"קסתות","r":"S01686","html":"<div class=\"sense\">, <span class=\"citation\">Kel. XV, 1</span> R. S., v. <a href=\"#\" data-headword=\"קִיסְטָא II\">קִיסְטָה</a></div>","alt":[]},"28933":{"h":"קְעִילָה","r":"S01687","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, <span class=\"citation\">Erub. 63ᵇ</span>, v. <span dir=\"rtl\">קִלְעָא I</span>.—Pl. <a href=\"#\" data-headword=\"קְעִילִית\">קְעִילִין</a>, <span class=\"citation\">Snh. 106ᵃ</span> Ar.; <span class=\"citation\">Yalk. Num. 771</span>, v. <a href=\"#\" data-headword=\"קֶלַע III\"><span dir=\"rtl\">קֶלַע</span> III</a>.</div>","alt":[]},"28934":{"h":"קְעִילִית","r":"S01688","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"קְעִילָה\">קעילה</a>) <i>of Keilah</i>, a town in the lowland district of Judæa. <span class=\"citation\">Yoma 76ᵃ</span>, a. e. <span dir=\"rtl\">דבילה ק׳</span>, v. <a href=\"#\" data-headword=\"דְּבֵילָה\">דְּבֵילָה</a>. <span class=\"citation\">Y. Bicc. III, beg. 65ᶜ</span> <span dir=\"rtl\">בקש … נאמר אם היתה ק׳ וכ׳</span> if one wants to bring (as first fruits) pressed figs, shall we say, if they are from Keilah, he may, if from Bozrah, he dare not?</div>","alt":[]},"28935":{"h":"קִעְקֵעַ I","r":"S01689","html":"<div class=\"sense\"> (onomatop.) <i>to cackle; to call hens by imitating their cackling</i>. <span class=\"citation\">Kidd. 31ᵃ</span> (sarcastically) <span dir=\"rtl\">הטל … וקַעְקֵעַ להן וכ׳</span> put water in a bowl and call them as you do hens.</div>","alt":[]},"28936":{"h":"קִעְקֵעַ II","r":"S01690","html":"<div class=\"sense\"> (transpos. of <span dir=\"rtl\">עקעק</span>, v. <a href=\"#\" data-headword=\"עוּק\">עוּק</a>; cmp. <a href=\"#\" data-headword=\"גִּעְגֵּעַ\">גִּעְגֵּעַ</a>) </div><div class=\"sense\"><b>1)</b> <i>to engrave</i> (cmp. <a href=\"#\" data-headword=\"חָקַק\">חָקַק</a>); <i>to etch in</i>. <span class=\"citation\">Macc. III, 6</span> <span dir=\"rtl\">כתב ולא ק׳ ק׳ … וִיקַעְקֵעַ</span> if he writes (on his skin) but makes no impression, or makes an impression but does not write, he is not guilty (of trespassing the law, <span class=\"citation\">Lev. XIX, 28</span>) until he writes and stamps with ink &amp;c.; Sifra K’doshim, Par. 3, ch. VI; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to stamp out, exterminate</i>. <span class=\"citation\">Y. Ab. Zar. IV, 44ᵃ</span> top, a. e., v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>. <span class=\"citation\">Tosef. B. Kam. X, 5</span>; <span class=\"citation\">Y. Gitt. V, 47ᵃ</span> bot. <span dir=\"rtl\">יְקַעְקֵעַ כל הבירה וכ׳</span> he must (if necessary) take down the entire group of buildings in order to restore it (the stolen beam). <span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">החריבה אותו אלא שלא קִעְקְעָה אותו וכ׳</span> she (Babylon) laid the Temple in ruins, but she did not stamp it out, whereas of Edom it is written (<span class=\"citation\">Ps. CXXXVII, 7</span></div><div class=\"sense\"><b>Hithpa. הִתְקַעְקֵעַ</b> </div><div class=\"sense\"><b>Nithpa. נִתְקַעְקֵעַ</b> <div class=\"sense\"><i>to be stamped out</i>, v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>. <span class=\"citation\">Esth. R. to I, 7</span> <span dir=\"rtl\">מי גרם … שתִּתְקַעְקֵעַ ביצתו וכ׳</span> what was the cause that Belshazzar’s dynasty was entirely exterminated? <span class=\"citation\">Ruth R. to IV, 14</span> <span dir=\"rtl\">מברכותיהן … לא נִתְקַעְקְעָה ביצתו וכ׳</span> owing to the blessings of the women, the seed of David was not entirely exterminated in the days of Athaliah. <span class=\"citation\">Pesik. R. s. 12</span> <span dir=\"rtl\">ואימתי שמשו שוקעת וביצתו מִתְקַעְקַעַת וכ׳</span> and when shall his (Amalek’s) sun go down and his egg be stamped out and his seed uprooted?</div></div>","alt":[]},"28937":{"h":"קַעְקַע","r":"S01691","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קִעְקֵעַ II\">preced.</a>) <i>impression</i>; <span dir=\"rtl\">כתובת ק׳</span> <i>etched inscription</i>. <span class=\"citation\">Macc. III, 6</span>; <span class=\"citation\">Lev. R. s. 19</span>, a. e., v. <a href=\"#\" data-headword=\"כְּתוֹבֶת\">כְּתוֹבֶת</a>.</div>","alt":[]},"28938":{"h":"קַעְקָא","r":"S01692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>neck</i>, v. <a href=\"#\" data-headword=\"קוֹעָא\">קוֹעָא</a>.</div>","alt":[]},"28939":{"h":"קְעָרָה","r":"S01693","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> קער <i>to be sunk</i>, <i>dish, charger</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> bot. <span dir=\"rtl\">אלכסנדרוס … ואת הים כק׳</span> when Alexander the Macedonian attempted to ascend to heaven, he rose higher and higher, until he saw the earth beneath him like a ball and the sea like a dish; <span dir=\"rtl\">ויצורינה ק׳ בידיה</span> and why is he not represented with a dish in his hand?; <span class=\"citation\">Num. R. s. 13</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הקריב ק׳ … ודומה לק׳</span> he offered a charger which is typical of the sea that surrounds the whole world and resembles a dish. <span class=\"citation\">Ker. 7ᵇ</span>, v. <a href=\"#\" data-headword=\"גָּדַף\">גָּדַף</a>. <span class=\"citation\">B. Bath. 16ᵃ</span> בקש איוב להפוך ק׳ על פיה Job attempted to turn the dish upside down, i.e. to challenge Providence; a. fr.—Pl. <span dir=\"rtl\">קְעָרוֹת</span>. <span class=\"citation\">Men. 97ᵃ</span>, v. <a href=\"#\" data-headword=\"דָּפוּס\">דָפוּס</a>; a. e.</div>","alt":[]},"28940":{"h":"קָפָא","r":"S01694","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"קפי\">קפי</a></div>","alt":["קְפָא"]},"28941":{"h":"קַפָּא I","r":"S01695","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάππα) the letter <i>kappa</i> (k′) as numeral, <i>twenty</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד בר נש</span>), v. <a href=\"#\" data-headword=\"דּוֹקְיָיא\">דּוֹקְיָיא</a>; <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot. [read:] <span dir=\"rtl\">מני עשרין … ק׳ דוקייא</span> count twenty beams in thy house (counting upwards and downwards until you arrive at twenty), and thou shalt find thy father’s savings, <i>kappa dokia</i> (twenty beams; oneirocritical play on Cappadocia; v. <span class=\"citation\">Gen. R. s. 68</span>).</div>","alt":[]},"28942":{"h":"קַפָּא II","r":"S01696","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קפף</span>) </div><div class=\"sense\"><b>1)</b> <i>trunk, vine</i>, v. <a href=\"#\" data-headword=\"קוֹפָא II\"><span dir=\"rtl\">קוֹפָא</span> II</a>.—</div><div class=\"sense\"><b>*2)</b>  (v. <a href=\"#\" data-headword=\"קוֹפָא II\"><span dir=\"rtl\">קוֹפָא</span> II</a>, 1) <i>pole, beam</i>. <span class=\"citation\">Ber. 56ᵇ</span>, v. <a href=\"#\" data-headword=\"*דִּיקָא\">דִּיקָא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זיל חזי ק׳ דריש עשרה וכ׳</span> go and examine the beam which heads the number ten, and you shall find (in number eleven) &amp;c.; v., however, <a href=\"#\" data-headword=\"קַפָּא I\">preced.</a></div>","alt":[]},"28943":{"h":"קַפָּא III","r":"S01697","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"קָפָא\">קָפָא</a>) name of <i>a worm</i> in herbs which causes disease of the bowels; (oth. opin.) <i>a poisonous substance in vegetables</i>. <span class=\"citation\">Pes. 115ᵇ</span> <span dir=\"rtl\">צריך לשקועיה … משום ק׳</span> you must dip the bitter herb into the <i>ḥăroseth</i> to counteract the effect of the <i>ḳappa</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא … וק׳ מריחא מיית</span> it is not necessary to dip it, for the ḳ. dies from the smell (of the <i>ḥăroseth</i>). <span class=\"citation\">Ib. 116ᵃ</span>, v. <a href=\"#\" data-headword=\"חַמָּא\">חַמָּא</a>.—<span class=\"citation\">Tosef. Ter. VII, 11</span> Ar., v. <a href=\"#\" data-headword=\"קַפָּה\">קַפָּה</a>.</div>","alt":[]},"28944":{"h":"קפאטיות","r":"S01698","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּבְטָאוֹת\">קוּבְטָאוֹת</a></div>","alt":[]},"28945":{"h":"קָפַד","r":"S01699","html":"<div class=\"sense\"> (b. h.) <i>to contract, convolve</i>, v. <a href=\"#\" data-headword=\"קוּפָּד\">קוּפָּד</a>.</div><div class=\"sense\"><b>Hif. הִקְפִּיד</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קָצַף\">קָצַף</a>) </div><div class=\"sense\"><b>1)</b> <i>to be angry, lose temper</i>. <span class=\"citation\">Taan. 20ᵇ</span> <span dir=\"rtl\">מימי לא הִקְפַּדְתִּי וכ׳</span> never did I lose my temper in my house; Y. ib. III, end, 67ᵃ. Y. Ber. IV, 7ᵈ (prayer on entering the schoolhouse) <span dir=\"rtl\">שלא אַקְפִּיד … יַקְפִּידוּ וכ׳</span> that I may not get excited over my colleagues, and my colleagues may not get excited over me. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">והלל לא יַקְפִּיד</span> and Hillel (I) shall not get impatient. <span class=\"citation\">Ab. d’R. N. ch. I</span> <span dir=\"rtl\">מַקְפִּיד על דבריו</span>, v. <a href=\"#\" data-headword=\"מָתַן\">מָתַן</a>. <span class=\"citation\">Ex. R. s. 6</span> <span dir=\"rtl\">ואף הוא מקפיד</span> (not <span dir=\"rtl\">מקפידו</span>) and he (Moses) also lost his temper. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ואתה מקפיד על דברי</span> and thou losest thy temper in spite of my word (that declared thee the most patient of men)?; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to provoke, insult</i>. Y. Keth. IV, 28ᵈ bot. <span dir=\"rtl\">ה׳ את וכ׳</span> he insulted an elder and struck him.</div><div class=\"sense\"><b>—3)</b> <i>to be strict, particular; to care for, mind</i>. <span class=\"citation\">Mikv. IX, 3</span>; <span class=\"citation\">7</span> <span dir=\"rtl\">כל המקפיד עליו הוצץ</span> whatever one minds (on one’s body) causes a partition for immersion, v. <a href=\"#\" data-headword=\"חָצַץ I\"><span dir=\"rtl\">חָצַץ</span> I</a>. <span class=\"citation\">B. Mets. 75ᵃ</span> <span dir=\"rtl\">בני חבורה המַקְפִּידִין וכ׳</span> members of a party that are particular with one another (in lending and borrowing); <span class=\"citation\">Sabb. 149ᵃ</span>. <span class=\"citation\">Ḥull. 107ᵇ</span> <span dir=\"rtl\">שני אחין ומקפידין וכ׳</span> two brothers (taking separate meals at the same table) who are particular with each other. <span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">לא היתה מַקְפֶּדֶת וכ׳</span> did not mind the pollution through idolatry; a. v. fr.</div></div>","alt":[]},"28946":{"h":"קְפַד","r":"S01700","html":"<div class=\"sense\">, <i>to be angry, sensitive; to be particular, care for, mind</i>. <span class=\"citation\">Snh. 113ᵇ</span>, v. <a href=\"#\" data-headword=\"קַפְדָּן\">קַפְדָּן</a>. <span class=\"citation\">Ḥull. 107ᵃ</span> <span dir=\"rtl\">קַפְדִּיתוּ אמנא</span> are you particular about the condition of the vessel (used for ablution)? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אמנא ואחזותא קַפְדִּינָן</span> we are particular about the vessel and about the color (of the water), <span dir=\"rtl\">אשיעורא לא קַפְדִּינָן</span> we are not so about the quantity. <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">והוא דקָפֵיד עלייהו</span> provided a person is particular about his garments’ being shaken before he puts them on; <span dir=\"rtl\">אנן לא קפדינן</span> we do not care about it. <span class=\"citation\">Pes. 110ᵇ</span> <span dir=\"rtl\">כל דקפיד קָפְדֵּי בהדיה וכ׳</span> he that minds (such practices) is strictly dealt with (suffers for disregarding them); he that does not care &amp;c. <span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">דקפיד אמנא שד</span> a magician that is particular about the vessel he uses is a conjurer of demons; a. fr.</div><div class=\"sense\"><b>Pa. קַפֵּיד</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קָפַד\">same</a>. Y. Sabb. I, 4ᵃ top <span dir=\"rtl\">מְקַפְּדִין</span>, v. <a href=\"#\" data-headword=\"קוּרְיָיאָה\">קוּרְיָיאָה</a></div></div><div class=\"sense\"><b>Ithpe. אִתְקְפַד  אִיקְּפַד</b> <div class=\"sense\"><b>1)</b> <i>to be contracted, shortened</i>. <span class=\"citation\">Targ. Is. XXXVIII, 12</span> (ed. Lag. <span dir=\"rtl\">איתקפלו</span>). <span class=\"citation\">Ib. L, 2</span>. <span class=\"citation\">Targ. Mic. II, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be angry, excited</i>. Y. Ber. II, 5ᵇ top <span dir=\"rtl\">שמע … וא׳ עילוי</span> Samuel heard of it and was angry with him. <span class=\"citation\">Kidd. 33ᵃ</span>; a. fr.</div></div><div class=\"sense\"><b>Af. אַקְפַּד</b> <div class=\"sense\"><i>to provoke, insult</i>. Y. B. Kam. VIII, end, 6ᶜ <span dir=\"rtl\">חד בר נש א׳ לר׳ וכ׳</span> (not <span dir=\"rtl\">איק׳</span>) a man insulted R. Ḥ.</div></div>","alt":[]},"28947":{"h":"*קְפָדָא","r":"S01701","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְפַד\">preced.</a>) <i>anger, indignation</i>. <span class=\"citation\">Targ. Y. I Num. XXV, 8</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a>; [prob. a corrupt. for <span dir=\"rtl\">בקבָתָהּ</span>, corresp. to h. text <span dir=\"rtl\">אל קבתה</span>; Pesh. <span dir=\"rtl\">בכרסה</span>].</div>","alt":[]},"28948":{"h":"קַפְדָּן","r":"S01702","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*קְפָדָא\">preced.</a> wds.) <i>hot-tempered, impetuous</i>, opp. <a href=\"#\" data-headword=\"עִנְוְתָן\">עִנְוְתָן</a>. <span class=\"citation\">Ab. II, 5</span> <span dir=\"rtl\">לא הק׳ מלמד</span> (Ar. <span dir=\"rtl\">הקו׳</span>) an impatient man cannot be a teacher. <span class=\"citation\">Sabb. 30ᵇ</span> bot., v. <a href=\"#\" data-headword=\"עִנְוְתָן\">עִנְוְתָן</a>; <span class=\"citation\">Ab. d’R. N. ch. XV</span>. <span class=\"citation\">Snh. 113ᵃ</span> sq. (in Chal. dict.) <span dir=\"rtl\">אבא אליהו ק׳ הוה</span> father Elijah (the prophet) was hot-tempered (dealing with Ahab too severely); <span dir=\"rtl\">א&quot;ל ק׳ קרית לי … דקא קפיד מר</span> said he (Elijah) to him, thou didst call me hot-tempered! Said he, this very case before us proves it, for thou art resentful; a. e.</div>","alt":["קוֹפְדָן"]},"28949":{"h":"קַפְדָּנוּת","r":"S01703","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַפְדָּן\">preced.</a>) <i>impatience, anger, irritability</i>, opp. <a href=\"#\" data-headword=\"עִנְוְתָנוּת\">עִנְוְתָנוּת</a>. <span class=\"citation\">Gen. R. s. 74</span>, a. e. <a href=\"#\" data-headword=\"קַפְדָּנוּת\">קַפְדָּנוּתָן</a>, v. <a href=\"#\" data-headword=\"עִנְוְתָנוּת\">עִנְוְתָנוּת</a>. <span class=\"citation\">Sabb. 31ᵃ</span> קַפְדָּנוּתוֹ של שמאי וכ׳ Shammai’s impatience came near driving us out of the world (of salvation); <span class=\"citation\">Ab. d’R. N. II</span> (ed. Schechter) ch. XXIX <span dir=\"rtl\">קִפְדָּנוּתְךָ שמאי וכ׳</span> thy impatience, O Shammai, &amp;c.; a. e.</div>","alt":[]},"28950":{"h":"קָפָה","r":"S01704","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קפי\">קפי</a></div>","alt":[]},"28951":{"h":"קֵפֶה","r":"S01705","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵיפֶא\">קֵיפֶא</a></div>","alt":[]},"28952":{"h":"קַפָּה","r":"S01706","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> name of <i>a worm</i> in herbs. <span class=\"citation\">Tosef. Ter. VII, 11</span> (Ar. <a href=\"#\" data-headword=\"קַפָּא I\">קפא</a>), v. <a href=\"#\" data-headword=\"קַפָּא III\"><span dir=\"rtl\">קַפָּא</span> III</a>.</div>","alt":[]},"28953":{"h":"קִפּוֹד","r":"S01707","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִיפּוֹד\">קִיפּוֹד</a></div>","alt":[]},"28954":{"h":"קַפּוּדְקָאָה","r":"S01708","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַפּוּדְקָיָא\">קַפּוּדְקָיָא</a></div>","alt":[]},"28955":{"h":"קַפּוּדְקְיָא","r":"S01709","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Cappadocia</i>, a district of Asia Minor. <span class=\"citation\">Targ. O. Deut. II, 23</span> <span dir=\"rtl\">קַפּוּטְקַ׳</span>; Y. ed. Vien. <span dir=\"rtl\">קְיָאָה …</span>; h. text <span dir=\"rtl\">כפתר</span>). <span class=\"citation\">Targ. Am. IX, 7</span>.—<span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד בר נש</span>); Y. Maas. Sh. IV, 55ᵇ bot.; <span class=\"citation\">Ber. 56ᵇ</span>, v. <a href=\"#\" data-headword=\"קַפָּא I\"><span dir=\"rtl\">קַפָּא</span> I</a>, II. <span class=\"citation\">Y. Yeb. II, end, 4ᵇ</span>, v. <a href=\"#\" data-headword=\"קִיסְרִין\">קִיסְרִין</a>; <span class=\"citation\">Tosef. ib. IV, 5</span> <span dir=\"rtl\">קפוט׳</span>. <span class=\"citation\">Keth. XIII, 11</span> <span dir=\"rtl\">קפוט׳</span>; Y. ed. <span dir=\"rtl\">קפוד׳</span>. <span class=\"citation\">Sabb. 26ᵃ</span>; <span class=\"citation\">Tosef. ib. II, 3</span>, v. <a href=\"#\" data-headword=\"נֵפְטְ\">נֵפְטְ</a>; a. e.</div>","alt":["קַפּוּדְקְיָיא","קַפּוּטְ׳"]},"28956":{"h":"קַפּוּדְקָיָא","r":"S01710","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַפּוּדְקְיָא\">preced.</a>) <i>Cappadocian</i>. <span class=\"citation\">Y. Peah I, 16ᶜ</span> top <span dir=\"rtl\">ר׳ יודן ק׳</span>. <span class=\"citation\">Koh. R. to VII, 23</span> <span dir=\"rtl\">ר׳ שמואל ק׳</span>; <span class=\"citation\">Pesik. R. s. 14</span>; a. e.—Pl. <a href=\"#\" data-headword=\"קַפּוּדְקָאָה\">קַפּוּדְקָאֵי</a>, <a href=\"#\" data-headword=\"קַפּוּדְקְיָא\">קַפּוּטְ׳</a>. <span class=\"citation\">Targ. Gen. X, 14</span> (h. text <span dir=\"rtl\">כפתרים</span>). <span class=\"citation\">Targ. Ez. XXVII, 11</span> (h. text <span dir=\"rtl\">גמדים</span>); a. e.—<span class=\"citation\">Y. Shebi. IX, 39ᵃ</span> top <span dir=\"rtl\">ק׳ דציפורין</span> the Cappadocian students at Sepphoris.</div>","alt":["קַפּוּדְקָאָה","קַפּוּטְ׳"]},"28957":{"h":"קָפוֹז","r":"S01711","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְפַז\">קְפַז</a>) <i>jumper, runner</i>. <span class=\"citation\">Gen. R. s. 86</span> (expl. <span dir=\"rtl\">איש מצליה</span>, <span class=\"citation\">Gen. XXXIX, 2</span>) <span dir=\"rtl\">גבר ק׳</span> a running (quick) man (with ref. to <span dir=\"rtl\">וצלחו</span>, <span class=\"citation\">II Sam. XIX, 18</span>); Yalk. ib. 145 <a href=\"#\" data-headword=\"קָפֵז\">קָפֵיז</a>.</div>","alt":[]},"28958":{"h":"קפוטורין","r":"S01712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיטּוּרֵי\">פִּיטּוּרֵי</a></div>","alt":[]},"28959":{"h":"קַפּוּטִיקִי","r":"S01713","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"קַפּוּדְקְיָא\">קַפּוּדְקְיָא</a> (?) <span class=\"citation\">Yalk. Gen. 148</span>; v., however, <a href=\"#\" data-headword=\"פְּלַסְטִינִי\">פְּלַסְטִינִי</a>.</div>","alt":[]},"28960":{"h":"רוּחְשִׁיתָא","r":"T00351","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְחַשׁ\">רְחַשׁ</a>) [<i>swarming</i>,] <i>Ruḥshitha</i>, legendary name of queen Esther’s maid for Thursday (with ref. to <span class=\"citation\">Gen. I, 20</span>). <span class=\"citation\">Targ. Esth. II, 9</span>.</div>","alt":[]},"28961":{"h":"רְוַחְתָּא","r":"T00352","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוָוחָא\">רְוָוחָא</a></div>","alt":[]},"28962":{"h":"רַוְחָתָא","r":"T00353","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַווחָתָא\">רַוְוחָתָא</a></div>","alt":[]},"28963":{"h":"רוֹטֶב","r":"T00354","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>) </div><div class=\"sense\"><b>1)</b> <i>soft, green date</i>, opp. <a href=\"#\" data-headword=\"יַבָּשָׁה\">יבשה</a>. <span class=\"citation\">Ukts. II, 2</span> <span dir=\"rtl\">גלעינה של ר׳</span> the kernel of a green date. <span class=\"citation\">Tosef. ib. II, 1</span>, sq.; a. e.—V. <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>.</div><div class=\"sense\"><b>—2)</b> <i>broth; juice of meats; jelly</i>. <span class=\"citation\">Ḥull. IX, 1</span>, expl. <span class=\"citation\">ib. 120ᵃ</span> <span dir=\"rtl\">מאי ר׳ שומנא</span> what kind of <i>roṭeb</i> is meant? Fat; (oth. opin.) <span dir=\"rtl\">חלא דקריש</span>, v. <a href=\"#\" data-headword=\"חָלָא III\"><span dir=\"rtl\">חָלָא</span> III</a>. <span class=\"citation\">Pes. VII, 2</span> <span dir=\"rtl\">נטף מרוֹטְבוֹ וכ׳</span> if (while roasting the Passover lamb) some of its juice dripped on &amp;c. <span class=\"citation\">Num. R. s. 10</span><sup>21</sup>; <span class=\"citation\">Tosef. Naz. IV, 6</span>. <span class=\"citation\">Ḥull. 108ᵃ</span> <span dir=\"rtl\">ר׳ רכה</span> (<i>fem</i>.) soft (liquid) juice; <span dir=\"rtl\">ר׳ עבה</span> thick (jelly-like) juice; a. fr.—<span class=\"citation\">Tosef. Kel. B. Bath. V, 6</span> <span dir=\"rtl\">ניקורי ר׳</span>, v. <a href=\"#\" data-headword=\"רֶטֶב\">רֶטֶב</a>.</div>","alt":[]},"28964":{"h":"רוֹטְבָא","r":"T00355","html":"<div class=\"sense\"><b>1)</b> <i>moisture</i>. <span class=\"citation\">Targ. Y. Lev. XI, 38</span> <span dir=\"rtl\">ברוֹטְבָהּ</span> (not <span dir=\"rtl\">בֵה …</span>) (of the condition of a fresh corpse).</div><div class=\"sense\"><b>—2)</b> <i>liquid</i>. <span class=\"citation\">Targ. II Chr. IV, 5</span> <span dir=\"rtl\">בר׳</span> as liquid measure.</div><div class=\"sense\"><b>—3)</b> <i>sap, marrow, juice</i>. <span class=\"citation\">Targ. Ps. XXXII, 4</span> (h. text <span dir=\"rtl\">לשד</span>). <span class=\"citation\">Targ. Job XV, 27</span> (h. text <span dir=\"rtl\">פימה</span>); a. e.—Pl. <span dir=\"rtl\">רוֹטְבַיָּא</span>, <span dir=\"rtl\">רוֹטְבִין</span>. <span class=\"citation\">Targ. Y. Lev. XI, 11</span> <span dir=\"rtl\">רוֹטְבֵיהוֹן</span> (not <span dir=\"rtl\">רועדיהון</span>), v. <a href=\"#\" data-headword=\"צִיר\">צִיר</a> I ch.—[<span class=\"citation\">Targ. Ps. LXXIII, 7</span> ורוטביהון Ms., read: <span dir=\"rtl\">וח׳</span>, v. <a href=\"#\" data-headword=\"חוֹטְבָא\">חוֹטְבָא</a>.]</div>","alt":[]},"28965":{"h":"רוטגנית","r":"T00356","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹטְנָנִית\">next w.</a></div>","alt":[]},"28966":{"h":"רוֹטְנָנִית","r":"T00357","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָטַן\">רָטַן</a>) </div><div class=\"sense\"><b>1)</b> <i>grumbling, discontented</i>. <span class=\"citation\">Num. R. s. 12</span><sup>5</sup> <span dir=\"rtl\">למלך שהיתה לו מטרונה ר׳</span> (Mus. <span dir=\"rtl\">רוטג׳</span>, corr. acc.) this is like the case of a king who had a grumbling matron as wife; Tanḥ. Naso 12 <span dir=\"rtl\">אשה ראגניות</span>, <span dir=\"rtl\">ראנ׳</span>, <span dir=\"rtl\">דאג׳</span> (corr. acc., or <a href=\"#\" data-headword=\"רוֹנָנִית\">רוֹנָנִית</a>); <span class=\"citation\">Pesik. R. s. 5</span> <span dir=\"rtl\">רונונות</span> (corr. acc., or <a href=\"#\" data-headword=\"רוֹנָנִית\">רוננית</a>).</div><div class=\"sense\"><b>—2)</b>  [prob. to be read: <a href=\"#\" data-headword=\"רוֹטְנָנִית\">רוֹטְנָנוּת</a>] <i>grumbling, discontent</i>. Num. R. l. c. <span dir=\"rtl\">שלא תחזור לרוֹטְנָנִיתָהּ</span> lest she return to her sullenness; Pesik. R. l. c. <span dir=\"rtl\">לרוננית</span> (read <span dir=\"rtl\">לרוֹנָנִיתָהּ</span>, or with ed. Prague: <span dir=\"rtl\">לרַטְנָנִיתָהּ</span>).</div>","alt":[]},"28967":{"h":"רוי","r":"T00358","html":"<div class=\"sense\"> (b. h.) <i>to be moist, be saturated, drip</i>. <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> top <span dir=\"rtl\">משיִרְווּ</span> (not <span dir=\"rtl\">שיורו</span>), v. <a href=\"#\" data-headword=\"מַרְוִית\">מַרְוִית</a>.</div><div class=\"sense\"><b>Pi. רִיוָּה</b> <div class=\"sense\"><i>to saturate</i>; <i>to refresh</i>; trnsf. <i>to delight</i>. <span class=\"citation\">B. Bath. 14ᵇ</span>; <span class=\"citation\">Ber. 7ᵇ</span> (play on <a href=\"#\" data-headword=\"רוּת\">רוּת</a>) <span dir=\"rtl\">שזכתה … שׁרִיוָּהוּ להקב&quot;ה וכ׳</span> she was privileged in that from her descended David, who delighted the Lord with songs and hymns.</div></div><div class=\"sense\"><b>Hif. הִרְוָה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רוֹטְנָנִית\">same</a>. <span class=\"citation\">Midr. Till. to Ps. CL</span> (ref. to <span class=\"citation\">Is. XXXIV, 5</span>) [read:] <span dir=\"rtl\">מַרְוֶה אותה ומפילהו לשרה וכ׳</span> he saturates it (the sword with blood), and brings her tutelary angel to fall, and then it (the sword) will come down upon her (Rome; v. Cant. R. to VIII, 14).</div></div><div class=\"sense\"><b>Nithpa. נִתְרַוֶּה  נִתְרַוֶּוה</b> <div class=\"sense\"><i>to be saturated, refreshed</i>. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">ירדו … ונ׳ העולם</span> rain fell, and the world was refreshed; <span class=\"citation\">Lev. R. s. 34</span> (not <span dir=\"rtl\">ונתרווח</span>); <span class=\"citation\">Yalk. Lev. 665</span>; <span class=\"citation\">Yalk. Ps. 888</span> (corr. acc.). Y. M. Kat. III, 82ᶜ bot. <span dir=\"rtl\">כשם שׁנִתְרַוִּיתֶם וכ׳</span> as you were saturated with the oil of inauguration for seven days &amp;c.; a. e.</div></div>","alt":["רָוָה"]},"28968":{"h":"רְוֵי","r":"T00359","html":"<div class=\"sense\">, esp. <i>to be filled with wine, be drunken</i>. <span class=\"citation\">Targ. Gen. IX, 21</span>. <span class=\"citation\">Ib. XLIII, 34</span> (some ed. O. <span dir=\"rtl\">רַוִּאוּ</span>, <i>Pa.</i>). <span class=\"citation\">Targ. Jer. XLVI, 10</span> (ed. Wil. <span dir=\"rtl\">ותְרַוֵּי</span>, <i>Pa.</i>); a. fr.—Part. <a href=\"#\" data-headword=\"רְוֵי\">רָוֵי</a>, <a href=\"#\" data-headword=\"רַוֵּי\">רַוְיָא</a>; f. <a href=\"#\" data-headword=\"רַוֵּי\">רַוְיָא</a>; Pl. <span dir=\"rtl\">רָוָון</span>, <span dir=\"rtl\">רַוְיָן</span>. <span class=\"citation\">Targ. Is. LI, 21</span>. <span class=\"citation\">Targ. Prov. XXIII, 20</span>, sq. <span class=\"citation\">Targ. Hag. I, 6</span>; a. fr.—<span class=\"citation\">Gitt. 68ᵃ</span> <span dir=\"rtl\">אישתי רוה וגנא</span> he drank, he was intoxicated and lay down. <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">אבא … שתי ולא רָ׳</span> my father drank wine enough for a thousand men, and was not drunk. Pesik. Eth Korb., p. 57ᵇ <span dir=\"rtl\">ואנא על לוגך דאנא שתי דאנא ר׳ דאנא שבע</span> (not <span dir=\"rtl\">לוגין</span>) and I (the Lord) wrote about thy one Log of wine that I drink, I am filled, and I am satisfied (<span class=\"citation\">Num. XXVIII, 7</span>), v. <a href=\"#\" data-headword=\"רְוִיָּה\">רְוִיָּה</a>; <span class=\"citation\">Pesik. R. s. 16</span>; <span class=\"citation\">Yalk. Num. 776</span>; <span class=\"citation\">Yalk. Ps. 761</span>.</div><div class=\"sense\"><b>Pa. רַוֵּי  רַוֵּוי</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רוי\">same</a>, v. supra.—2) </div><div class=\"sense\"><i>to fill, saturate; to make drunk</i>. <span class=\"citation\">Targ. Is. LV, 10</span>. <span class=\"citation\">Targ. Hos. VI, 3</span> (h. text <a href=\"#\" data-headword=\"יוֹרֶה II\">יורה</a>). <span class=\"citation\">Targ. Jer. XLVI, 16</span> (h. text <span dir=\"rtl\">היונה</span>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְרַוֵּי\">מְרַוֵּי</a>; f. <a href=\"#\" data-headword=\"מְרַוְיָא\">מְרַוְּיָא</a>. <span class=\"citation\">Targ. Is. LVIII, 11</span>.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַוֵּי</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְוֵי</b> <div class=\"sense\"><i>to be saturated; to be drunken</i>. Ib. V, 22 (ed. Wil. <span dir=\"rtl\">אתחו׳</span>, corr. acc.). Ib. XLIX, 26. <span class=\"citation\">Targ. Ps. XXXVI, 9</span>; a. fr.</div></div>","alt":["(רְוִי)","רְוָא","רְוָה"]},"28969":{"h":"רַוֵּי","r":"T00360","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"רְוֵי\">preced.</a>) <i>drunk; drunkard</i>. <span class=\"citation\">Targ. I Kings XVI, 9</span>; <span class=\"citation\">XX, 16</span>. <span class=\"citation\">Targ. Prov. XXVI, 9</span>. <span class=\"citation\">Ib. 10</span> (not <span dir=\"rtl\">רז׳</span>; h. text <span dir=\"rtl\">שׂכֵר</span>!). <span class=\"citation\">Targ. I Sam. I, 13</span>; a. fr.—<span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">חזא ר׳ דהוה וכ׳</span> when he saw a drunken man that was lost, he led him back &amp;c. <span class=\"citation\">Sabb. 32ᵃ</span> (prov.) <span dir=\"rtl\">שבקיה לר׳ וכ׳</span> leave the drunken man alone, he will fall of himself (a person’s sins are visited upon him in critical moments); a. e.—Pl. <a href=\"#\" data-headword=\"רַוֵּי\">רַוַּיָּא</a>, <span dir=\"rtl\">רַוַּו׳</span>. <span class=\"citation\">Targ. Joel I, 5</span>.</div>","alt":["רַוְיָא","רַוְו׳"]},"28970":{"h":"רְוִיָּה","r":"T00361","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַוֵּי\">preced.</a>) <i>saturation, fulness, satisfaction</i>. Pesik. Eth Korb., p. 57ᵇ (ref. to <span dir=\"rtl\">הסך נסך שכר</span>, <span class=\"citation\">Num. XXVIII, 7</span>) <span dir=\"rtl\">לשון שתיה לשון ר׳ לשון שכרות</span> of this one Log of wine three words are used expressing drinking, fill, plenty; <span class=\"citation\">Pesik. R. s. 16</span>; (Tanḥ. Pinḥas 12 <a href=\"#\" data-headword=\"שְׂבִיעָה\">שביעה</a>).</div>","alt":["רְוִויָּיה"]},"28971":{"h":"רְוָיָה","r":"T00362","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְוִיָּה\">preced.</a> wds.) <i>overflow</i>; (numerical value) <i>two hundred and twenty-one</i> (<i>Logs</i>). <span class=\"citation\">Yoma 76ᵃ</span></div>","alt":[]},"28972":{"h":"רַוְיוּ","r":"T00363","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוָיָה\">preced.</a> wds.) <i>drunkenness</i>. <span class=\"citation\">Targ. Mic. II, 11</span> (h. text <a href=\"#\" data-headword=\"שֵׁכָר\">שֵׁכָר</a>).</div>","alt":[]},"28973":{"h":"רְוִיחַ","r":"T00364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוַוח\">רְוַוח</a>.—<span dir=\"rtl\">רויחא</span>, v. <a href=\"#\" data-headword=\"רְוִיתָא\">רְוִיתָא</a>.</div>","alt":[]},"28974":{"h":"רַוְיָיתָא","r":"T00365","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוִיחַ\">preced. art.</a>) </div><div class=\"sense\"><b>1)</b> <i>intoxicating drink</i>. <span class=\"citation\">Targ. Hos. IV, 11</span> (h. text <a href=\"#\" data-headword=\"תִּירוֹשׁ\">תירוש</a>).</div><div class=\"sense\"><b>—2)</b> <i>intoxication, rage</i>. <span class=\"citation\">Targ. Esth. II, 1</span> <span dir=\"rtl\">רַוְויַת</span> constr. <span class=\"citation\">Targ. Prov. XX, 1</span> (h. text <span dir=\"rtl\">הֹמֶה</span>).</div>","alt":["רַוְיָתָא","רַוְו׳"]},"28975":{"h":"רְוִיתָא","r":"T00366","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַוְיָיתָא\">preced.</a> wds.) <i>overflowing</i>. <span class=\"citation\">Targ. Ps. XXIII, 5</span> ed. Wil. (ed. Lag. <span dir=\"rtl\">רווחא</span>, oth. ed. <span dir=\"rtl\">רויחא</span>, corr. acc.; cmp., however, <span class=\"citation\">Targ. Ps. LXVI, 12</span>).</div>","alt":[]},"28976":{"h":"רוּכְבָּא","r":"T00367","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּקְבָּא II\"><span dir=\"rtl\">רוּקְבָּא</span> II</a> ch.</div>","alt":[]},"28977":{"h":"רוֹכְבָא","r":"T00368","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִכְבָּא\">רָכְבָּא</a></div>","alt":[]},"28978":{"h":"רוֹכְבָה","r":"T00369","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְכוּבָה\">רְכוּבָה</a></div>","alt":[]},"28979":{"h":"רוּכְכָא","r":"T00370","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְכַךְ\">רְכַךְ</a>) <i>softness, tenderness</i>. <span class=\"citation\">Ḥull. 56ᵃ</span> <span dir=\"rtl\">אי איתא … אגב רוּכְכֵיה וכ׳</span> if the upper membrane had been perforated, the lower would have burst on account of its tenderness.</div>","alt":[]},"28980":{"h":"רוֹכֵל","r":"T00371","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>peddler</i>, esp. <i>seller of spices, perfumes</i> &amp;c. <span class=\"citation\">Yeb. 63ᵇ</span>, v. <a href=\"#\" data-headword=\"פֶּצַע\">פֶּצַע</a>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">קופת הר׳</span> the spice-peddler’s basket. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אבקת ר׳</span>, v. <a href=\"#\" data-headword=\"אֲבָקָה\">אֲבָקָה</a>. <span class=\"citation\">Lev. R. s. 16</span>; a. e.—Pl. <span dir=\"rtl\">רוֹכְלִים</span>, <span dir=\"rtl\">רוֹכְלִין</span>. <span class=\"citation\">Sabb. 91ᵇ</span>; <span class=\"citation\">Gitt. 67ᵃ</span> v. <a href=\"#\" data-headword=\"קוּפָּה\">קוּפָּה</a>. <span class=\"citation\">Kidd. 82ᵃ</span>; a. e.</div>","alt":[]},"28981":{"h":"רוֹכְלָא","r":"T00372","html":"<div class=\"sense\"> <span class=\"citation\">Gitt. 33ᵃ</span> <span dir=\"rtl\">אטו תנא כי ר׳ וכ׳</span> (Rashi <a href=\"#\" data-headword=\"רוֹכֵל\">רוכל</a>) must the Tanna go on enumerating like a peddler (calling out all he has to sell)?; <span class=\"citation\">B. Kam. 36ᵇ</span>; <span class=\"citation\">Naz. 21ᵃ</span>; <span class=\"citation\">Arakh. 23ᵇ</span></div>","alt":[]},"28982":{"h":"רוֹכְלוֹת","r":"T00373","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוֹכְלָא\">preced.</a>) <i>mercantile journeys, success in business</i>. <span class=\"citation\">Cant. R. to III, 6</span> (play on <span dir=\"rtl\">אבקת רכל</span>, ib.) <span dir=\"rtl\">כל רוֹכְלוֹתָיו של יעקב וכ׳</span> whatever Jacob gained came to him only through the dust under his feet (he did not get anything from his father as did the latter from Abraham). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל הר׳ שישראל וכ׳</span> for whatever journeys Israelites undertake with success, they are indebted to the merits of the dust raised by of our father Jacob (when he wrestled with the angel and was blessed, <span class=\"citation\">Gen. XXXII, 25</span> sq.).</div>","alt":[]},"28983":{"h":"רוּם","r":"T00374","html":"<div class=\"sense\"> (b. h.) [<i>to swing</i>,] <i>to be high, lifted up; to rise</i>. <span class=\"citation\">Ab. Zar. 24ᵇ</span> רוֹמִי רומי השיטה Ar. (ed. <span dir=\"rtl\">רוני</span>) rise, rise, acacia (holy ark)!; <span class=\"citation\">Gen. R. s. 54</span> <span dir=\"rtl\">רומי השטה</span>.</div><div class=\"sense\"><b>Hif. הרִים</b> <div class=\"sense\"><b>1)</b> <i>to lift up, raise</i>. <span class=\"citation\">Cant. R. to III, 4</span> (ref. to <span class=\"citation\">Ps. LXXV, 8</span>) <span dir=\"rtl\">ישפיל … ויָרִים לכרש וכ׳</span> he shall lower Belshazzar, and lift up Cyrus and Darius; <span class=\"citation\">Yalk. Ps. 812</span> אני הוא משפיל ומֵרִים I lower and raise; <span dir=\"rtl\">מלכות … מרים</span> he lays low one empire and raises another empire &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to take off, remove</i>. <span class=\"citation\">Ruth R. to I, 17</span> (ref. to <span class=\"citation\">Ez. XXI, 31</span>) <span dir=\"rtl\">הסר … והָרִים העטרה וכ׳</span> remove the bonnet from our teachers, and take the crown off the nations; a. e.</div></div><div class=\"sense\"><b>Hof. הוּרָם</b> <div class=\"sense\"><i>to be taken off</i>, esp. <i>to be separated as an offering, priest’s share</i> &amp;c.; <i>to be consecrated</i>. <span class=\"citation\">Ḥall. II, 8</span> <span dir=\"rtl\">שלא הוּרְמָה חלתה</span> (not <a href=\"#\" data-headword=\"רוּם\">הורם</a>), v. <a href=\"#\" data-headword=\"חַלָּה\">חַלָּה</a>. <span class=\"citation\">Sifré Num. 110</span> (ref. to <span class=\"citation\">Num. IV, 20</span>) <span dir=\"rtl\">את שמוּרָם קודש וכ׳</span> that which is separated is to be sacred, and the remainder secular, but (no Ḥallah is to be taken,) when both would be sacred. <span class=\"citation\">Zeb. V, 6</span> <span dir=\"rtl\">המורם מהם וכ׳</span> the same rules apply to what is taken off them for the priest; a. fr.</div></div><div class=\"sense\"><b>Polel. רוֹמֵם</b> <div class=\"sense\"><i>to lift up, elevate</i>. Tanḥ. Matt. 6; <span class=\"citation\">Num. R. s. 22</span>, end (ref. to <span class=\"citation\">Num. XXXI, 9</span> and XXXII, 1) <span dir=\"rtl\">הא שהשפיל … ור׳ וכ׳</span> here you see that the Lord lowered the Midianites, and raised the Israelites. Ib. (ref. to <span class=\"citation\">I Sam. II, 7</span>) <span dir=\"rtl\">אף … מְרוֹמֵם את זה</span> in the anger which he brings to bear on one, he raises the other. <span class=\"citation\">Pesik. R. s. 10</span> (ref. to <span class=\"citation\">Ps. LXXV, 8</span>) <span dir=\"rtl\">משפיל לכל … ומרומם וכ׳</span> he lowered every one that had part in the worship of the golden calf, and elevated every one that had no part &amp;c. Ib. <span dir=\"rtl\">ועכשיו … אף כך רוֹמֵם ראשם</span> and now that thou hast lifted up my head, lift thou up their head likewise; <span dir=\"rtl\">לך ר׳ ראשם</span> go and lift up their heads (announce to them the divine pardon). Ib. (ref. to <span class=\"citation\">Ex. XXX, 12</span>) <span dir=\"rtl\">כל מה שאתה יכול לרוֹמֵם … רוֹמְמָהּ שבאילו לי אתה מְרוֹמֵם</span> (not <span dir=\"rtl\">רומם</span>) in whatever way thou canst elevate that nation elevate it, for by this thou elevatest me. <span class=\"citation\">Ex. R. s. 25</span> <span dir=\"rtl\">ורִימְּמָן הקב&quot;ה וכ׳</span> (fr. <a href=\"#\" data-headword=\"רָמַם\">רָמַם</a>) and the Lord raised them above all; a. fr.</div></div><div class=\"sense\"><b>Hithpol. הִתְרוֹמֵם</b> <div class=\"sense\">, <i>Nithpol</i>. <span dir=\"rtl\">נִתְרוֹמֵם</span> <i>to be lifted up; to pride one’s self</i>. Y. Ber. IX, 14ᵃ top <span dir=\"rtl\">יתגדל … ויתברך ויִתְרוֹמַם שמך וכ׳</span> thy Name be magnified … and blessed and lifted up (praised) for &amp;c.; Y. Taan. I, 64ᵃ top; <span class=\"citation\">Gen. R. s. 13</span>. <span class=\"citation\">Meg. 17ᵇ</span> <span dir=\"rtl\">כיון … מִתְרוֹמֶמֶת קרן וכ׳</span> when the transgressors cease to exist, the horn of the righteous will be uplifted. <span class=\"citation\">Num. R. s. 22</span>; Tanḥ. Matt. 6, a. e. <span dir=\"rtl\">אין אדם מִתְרוֹמֵם</span>, v. <a href=\"#\" data-headword=\"רוֹמֵמוּת\">רוֹמֵמוּת</a>. Tanḥ. Mick. 3 <span dir=\"rtl\">ונִתְרוֹמְמוּ</span> and they were raised (to power); a. e.—[<span class=\"citation\">Yalk. Gen. 79</span> <span dir=\"rtl\">מתרוממות</span>, read: <span dir=\"rtl\">מְתַמְּרִין</span>, v. <a href=\"#\" data-headword=\"תָּמַר\">תָּמַר</a>.]</div></div>","alt":["רִים"]},"28984":{"h":"רוּם ²","r":"T00375","html":"<div class=\"sense\">, <i>to be high</i>. <span class=\"citation\">Targ. Ps. LXXXIX, 14</span>. <span class=\"citation\">Targ. O. Deut. VIII, 14</span> <span dir=\"rtl\">וִירַם</span> ed. Berl. (oth. ed. <span dir=\"rtl\">וִירִים</span>, <span dir=\"rtl\">וְרִים</span>); a. fr.—2) <i>to lift; to remove</i>. <span class=\"citation\">Targ. Ps. LXXXIX, 18</span> <a href=\"#\" data-headword=\"תְּמִים\">תְּרִים</a>.—<span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">ורִימוּנָהּ</span> and they lifted it. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> bot. <span dir=\"rtl\">כיון דרִימֵיה</span> when he had removed it. <span class=\"citation\">Y. Ab. Zar. IV, 43ᵈ</span> <span dir=\"rtl\">מן דרִימוֹן</span> when he had removed them (the stones); a. e.</div><div class=\"sense\"><b>Af. אָרֵים  אֲרִים</b> <div class=\"sense\"><b>1)</b> <i>to swing; to wave an offering; to uplift</i>. <span class=\"citation\">Targ. Ex. VII, 20</span>. <span class=\"citation\">Targ. O. ib. XVII, 11</span> <a href=\"#\" data-headword=\"מִרְיָם\">מַרִים</a> ed. Berl. (ed. Vien. <span dir=\"rtl\">יְרִים</span>). <span class=\"citation\">Targ. Is. XXX, 28</span> (h. text <span dir=\"rtl\">להנפה</span>). <span class=\"citation\">Targ. Lev. XXIII, 11</span> (h. text <span dir=\"rtl\">והניף</span>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מִרְיָם\">מְרִים</a>; f. pl. <span dir=\"rtl\">מְרִימָן</span>. <span class=\"citation\">Targ. Is. III, 16</span> (h. text <span dir=\"rtl\">נטויות</span>).</div><div class=\"sense\"><b>—2)</b> <i>to lift take off, remove</i>. <span class=\"citation\">Lam. R. to V, 5</span> <span dir=\"rtl\">אֲרִימוּן ראשיה מיניה</span> cut his head off. Y. Ab. Zar. l. c. <span dir=\"rtl\">בחייך דאת מֵרִים אילין וכ׳</span> by thy life! thou must remove these stones; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתָּרַם</b> </div><div class=\"sense\"><b>Ithpe. אִיתְּרַם  אִיתְּרִים</b> <div class=\"sense\"><b>1)</b> <i>to be uplifted, rise</i>. <span class=\"citation\">Targ. Gen. VII, 17</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be swung, waved</i> (as an offering). <span class=\"citation\">Targ. Ex. XXIX, 27</span> (h. text <span dir=\"rtl\">הונף</span>); a. e.</div><div class=\"sense\"><b>—3)</b> <i>to be taken off, removed</i>. <span class=\"citation\">Lam. R. to V, 16</span> <span dir=\"rtl\">והא ניחא ליה דאיתרים רישיה וכ׳</span> it would have been better for him that his head be cut off rather than do this; <span class=\"citation\">Koh. R. to X, 5</span> <span dir=\"rtl\">נייח הוה דיִיתְּרִים וכ׳</span>; Y. Sot. IX, 24ᵇ sq. <span dir=\"rtl\">נייח ליה אילו איתרים וכ׳</span>.</div></div><div class=\"sense\"><b>Polel. רוֹמֵם</b> <div class=\"sense\"><i>to elevate, extol</i>. <span class=\"citation\">Targ. Ps. XXXVII, 34</span>. <span class=\"citation\">Ib. CXLV, 1</span>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 3</span>; a. e.—Part. pass. <span dir=\"rtl\">מְרוֹמַם</span>. <span class=\"citation\">Targ. Ps. XVIII, 47</span> (not <span dir=\"rtl\">מרומֵם</span>); <span class=\"citation\">Targ. II Sam. XXII, 47</span>; a. e.—V. <a href=\"#\" data-headword=\"מְרָמַם\">מְרָמַם</a>.</div></div><div class=\"sense\"><b>Ithpol. אִתְרוֹמַם</b> <div class=\"sense\"><i>to be lifted up; to be extolled</i>. <span class=\"citation\">Targ. Ps. CVII, 25</span>. <span class=\"citation\">Ib. LXXV, 11</span>. <span class=\"citation\">Ib. CVIII, 6</span>; a. e.—Y. Maas. Sh. IV, end, 55ᶜ <span dir=\"rtl\">את מִתְרוֹמְמָא</span>, v. <a href=\"#\" data-headword=\"הֲדָרָא\">הֲדָרָא</a>.</div></div><div class=\"sense\"><b>Palp. דַמְרֵם</b> <div class=\"sense\">, contr. <a href=\"#\" data-headword=\"רוֹרֵם\">רוֹרֵם</a>, <a href=\"#\" data-headword=\"רְרַם\">רָרֵם</a> <i>to elevate</i>. <span class=\"citation\">Targ. Ps. IX, 14</span> מְרוֹרֵם Ms. (ed. <span dir=\"rtl\">מְרוֹמֵם</span>). <span class=\"citation\">Ib. XXVII, 5</span>. <span class=\"citation\">Targ. Prov. XVII, 19</span> מְרָרֵים Ms. (ed. <a href=\"#\" data-headword=\"מִרְיָם\">מרים</a>, <span dir=\"rtl\">מורים</span>). <span class=\"citation\">Ib. XIV, 34</span>.</div></div><div class=\"sense\"><b>Ithpalp. אִתְרַמְרַם</b> <div class=\"sense\">, contr. <a href=\"#\" data-headword=\"רוּם ²\">אִתְרוֹרַם</a>, <a href=\"#\" data-headword=\"רְעַם I\">אִתְרָרַם</a> </div><div class=\"sense\"><b>1)</b> <i>to be elevated, rise</i>. <span class=\"citation\">Targ. Ps. LVII, 6</span>; <span class=\"citation\">12</span>. <span class=\"citation\">Targ. Prov. XI, 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be haughty, proud</i>. Ib. XVIII, 12.—Apocopated form: <a href=\"#\" data-headword=\"אֲמַר\">אִתְרַמַּר</a>. Ib. VI, 30 <span dir=\"rtl\">לא למִתְרַמָרוּ וכ׳</span> ed. (h. text <span dir=\"rtl\">יבוזו</span>) let them not look haughtily down on the thief &amp;c.; v. <a href=\"#\" data-headword=\"*דְּמַר\">דְּמַר</a>.</div></div>","alt":["רִים"]},"28985":{"h":"רוּם II","r":"T00376","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רוּם ²\">preced.</a>) <i>height</i>. <span class=\"citation\">Ber. 6ᵇ</span> (ref. to <span dir=\"rtl\">כרם זלות</span>, <span class=\"citation\">Ps. XII, 9</span>) <span dir=\"rtl\">אלו דברים … ברוֹמוֹ וכ׳</span> this means the things which stand on the height of the world (sublime things like prayer &amp;c.) and which men treat lightly. <span class=\"citation\">Meg. 14ᵃ</span> <span dir=\"rtl\">בני אדם שעומדין ברומו וכ׳</span> men that stood very high. <span class=\"citation\">Midd. II, 3</span>; <span class=\"citation\">III, 6</span> <span dir=\"rtl\">ר׳ מעלה וכ׳</span> the height of each step was &amp;c. <span class=\"citation\">Sifré Deut. 199</span> <span dir=\"rtl\">גדול השלום שדרי ר׳ וכ׳</span> peace is something great, for the dwellers on high (angels) need peace; <span class=\"citation\">Yalk. ib. 923</span>; a. e.</div>","alt":["רוֹם"]},"28986":{"h":"רוּם ³","r":"T00377","html":"<div class=\"sense\"><b>1)</b> <i>height</i>. <span class=\"citation\">Targ. Y. Deut. XI, 18</span> <span dir=\"rtl\">על ר׳ ידכון</span> on the highest point of your arm (v. <a href=\"#\" data-headword=\"גּוֹבַהּ\">גּוֹבַהּ</a>). <span class=\"citation\">Targ. Is. XIV, 12</span>, sq. <span class=\"citation\">Targ. O. Num. XXIII, 22</span>; a. fr.—Y. Snh. X, 29ᵃ <span dir=\"rtl\">הוה ארונא … לר׳ וכ׳</span> the ark carried the priests high up and cast them down to the ground. <span class=\"citation\">B. Bath. IV, 2</span>; <span class=\"citation\">ib. 61ᵃ</span>, v. <a href=\"#\" data-headword=\"עוּמְקָא I\"><span dir=\"rtl\">עוּמְקָא</span> I</a>. <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">ברוּמְהוֹן</span> (some ed. <span dir=\"rtl\">ברוֹמֵיהֶן</span>, pl.) of their high stature, v. <a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a> I ch.; <span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">ברומחין</span> (corr. acc.); a. e.—Pl. <span dir=\"rtl\">רוֹמִין</span>, <a href=\"#\" data-headword=\"רומי\">רוֹמֵי</a>. <span class=\"citation\">Sot. 48ᵇ</span>, v. <a href=\"#\" data-headword=\"שׁוּט\">שׁוּט</a> I ch.—V. <a href=\"#\" data-headword=\"מְרוֹמָא I\"><span dir=\"rtl\">מְרוֹמָא</span> I</a>.</div><div class=\"sense\"><b>—2)</b> <i>haughtiness</i>. <span class=\"citation\">Targ. Ps. LXXIII, 8</span>.—V. <a href=\"#\" data-headword=\"רָמוּתָא\">רָמוּתָא</a>.</div>","alt":["רוּמָא I"]},"28987":{"h":"רוּמָא II","r":"T00378","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"רוּמָה\">רוּמָה</a></div>","alt":[]},"28988":{"h":"*רוֹמָא I","r":"T00379","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּמָא II\">preced. art.</a>) <i>haughty</i>.—Pl. <a href=\"#\" data-headword=\"רוּמְיָא\">רוֹמַיָּא</a>. <span class=\"citation\">Koh. R. to VIII, 11</span> (perh. to be read: <a href=\"#\" data-headword=\"רוּמְיָא\">רוֹמָיֵא</a> = <span dir=\"rtl\">רוֹמָאֵי</span>), v. <a href=\"#\" data-headword=\"*מְפוּקִים\">מְפוּקִים</a>.</div>","alt":[]},"28989":{"h":"רוֹמָא II","r":"T00380","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Roma) <i>Rome</i>, v. <a href=\"#\" data-headword=\"רוֹמִי I\">רוֹמִי</a>.</div>","alt":[]},"28990":{"h":"רוֹמָאָה","r":"T00381","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוֹמָא II\">preced.</a>) <i>Roman</i>. <span class=\"citation\">Ber. 62ᵇ</span> ר׳ Ms. M. (ed. <span dir=\"rtl\">פרסאה</span>, censor’s change); <span class=\"citation\">Yalk. Is. 316</span>; <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">רומאי</span> (corr. acc.); a. fr.—Pl. <span dir=\"rtl\">רוֹמָאֵי</span>. Y. Sabb. VI, 8ᶜ bot., v. <span dir=\"rtl\">אָבְטְיוֹ</span>‌<a href=\"#\" data-headword=\"נָא I\">נׇא</a>. <span class=\"citation\">Y. Erub. III, 21ᵇ</span>, v. <a href=\"#\" data-headword=\"טַקְסְיוֹטֵי\">טַקְסְיוֹטֵי</a>; a. fr.—<i>Fem.</i> <span dir=\"rtl\">רוֹמִיתָא</span>, <span dir=\"rtl\">רוֹמְיְיתָא</span>. <span class=\"citation\">B. Bath. 11ᵇ</span>, v. <a href=\"#\" data-headword=\"אַכְסַדְרָא\">אַכְסַדְרָא</a>. <span class=\"citation\">Sabb. 110ᵇ</span>, v. <a href=\"#\" data-headword=\"הֵיגְתָא\">הֵיגְתָא</a>.—Pl. <span dir=\"rtl\">רוֹמְיָיתָא</span>. <span class=\"citation\">B. Bath. 83ᵇ</span>, v. <a href=\"#\" data-headword=\"הֵיגְתָא\">הֵיגְתָא</a>; a. e.</div>","alt":[]},"28991":{"h":"רִוְמָאטִיקוֹן","r":"T00382","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רֶאוְמָטִיקוֹס\">רֶאוְמָטִיקוֹס</a>) <i>subject to a discharge of flux</i>. <span class=\"citation\">Lev. R. s. 15</span> נעשה ר׳ Ar. s. v. <span dir=\"rtl\">קטרקין</span> (<a href=\"#\" data-headword=\"קטריטון\">קטריטון</a>) he becomes subject to &amp;c. (different vers. in ed. Lev. R.; v. <a href=\"#\" data-headword=\"*קְטִיקְטוֹן\">קְטִיקְטוֹן</a>).</div>","alt":[]},"28992":{"h":"רוּמָה","r":"T00383","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ruma</i> in Galilee, near K’far Hananiah. <span class=\"citation\">Y. Erub. IV, end, 22ᵃ</span>; Bab. <span class=\"citation\">Erub. 51ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"אֲרוּמָא\">ארומא</a>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">III), 17</span> (ed. Zuck. <a href=\"#\" data-headword=\"דָּרוֹמָא\">דרומא</a>, corr. acc.).</div>","alt":["(רוּמָא)"]},"28993":{"h":"רוֹמוּלוֹס","r":"T00384","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Romulus</i>, the legendary founder of Rome in conjunction with his brother Remus. <span class=\"citation\">Midr. Till. to Ps. X</span> (ref. to <span class=\"citation\">Ps. LXVIII, 6</span>, a. <span class=\"citation\">X, 14</span>) <span dir=\"rtl\">רומוס ור׳ מתה אמם וכ׳</span> the mother of Remus and Romulus was dead, and a she-wolf was appointed (by Providence) to give them suck, and they built two large huts in Rome; Yalk. ib. 652. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <span dir=\"rtl\">רומס ורומילס</span>, v. <a href=\"#\" data-headword=\"צְרִיף\">צְרִיף</a>. <span class=\"citation\">Midr. Till. to Ps. XVII, 14</span>, <span dir=\"rtl\">אלו שני יתומין … רומוס ור׳ וכ׳</span> (not <span dir=\"rtl\">ורימילוס</span>) this refers to the two orphans …, R. and R. for whom thou didst appoint a wolf &amp;c.; <span class=\"citation\">Yalk. ib. 671</span>; <span class=\"citation\">Esth. R. to I, 9</span> <span dir=\"rtl\">רומוס ורמילוס</span>.</div>","alt":["(רוֹמִילוֹס)"]},"28994":{"h":"רוֹמוֹס","r":"T00385","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Remus</i>, v. <a href=\"#\" data-headword=\"רוֹמוּלוֹס\">preced.</a></div>","alt":[]},"28995":{"h":"רוֹמַח","r":"T00386","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>to swing</i>) <i>spear</i>. <span class=\"citation\">Sabb. VI, 4</span> (<span class=\"citation\">63ᵃ</span>). <span class=\"citation\">Num. R. s. 20</span>, end; Tanḥ. Balak 21; a. e.—Pl. <span dir=\"rtl\">רְמָחִים</span>, <span dir=\"rtl\">רְמָחִין</span>. <span class=\"citation\">Ab. d’R. N. ch. XXXIII</span> <span dir=\"rtl\">אף הקב&quot;ה … בחרבות ור׳</span> the Lord, too, came against them with swords and spears (lightnings). <span class=\"citation\">Tosef. Snh. XIV, 6</span>; a. e.</div>","alt":[]},"28996":{"h":"רוּמְחָא","r":"T00387","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Num. XXV, 7</span> (O. ed. Vien. <a href=\"#\" data-headword=\"רֹמַח\">רֳמְחָא</a>). <span class=\"citation\">Targ. Josh. VIII, 18</span>; <span class=\"citation\">26</span> (h. text <a href=\"#\" data-headword=\"כִּידוֹן I\">כידון</a>); a. fr.—Pl. <span dir=\"rtl\">רוּמְחִין</span>, <span dir=\"rtl\">רוּמְחַיָּא</span>. <span class=\"citation\">Targ. Jud. V, 8</span>. <span class=\"citation\">Targ. Job XLI, 21</span> Ms. (ed. <i>sing.</i>); a. e.—[<span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">ברומחין</span>, read: <span dir=\"rtl\">ברוּמְהוֹן</span>, v. <a href=\"#\" data-headword=\"רוּם ³\"><span dir=\"rtl\">רוּמָא</span> I</a>.]</div>","alt":["רוֹ׳"]},"28997":{"h":"רוֹמִי I","r":"T00388","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ῥώμη, Roma) <i>Rome</i>; also <i>the Roman empire</i>. <span class=\"citation\">Targ. Is. XXXIV, 9</span> ed. Lag. (omitted in oth. ed.). <span class=\"citation\">Ib. LIV, 1</span> ed. Lag. (oth. ed. <span dir=\"rtl\">כרכא</span>). <span class=\"citation\">Targ. Ps. CVIII, 11</span> <span dir=\"rtl\">כרכא דר׳ רשיעא</span> ed. Lag. (oth. ed. <span dir=\"rtl\">כרכא רשיעא</span>; ed. Wil. <span dir=\"rtl\">כרכא תקיפא</span>; h. text <span dir=\"rtl\">אדום</span>). <span class=\"citation\">Targ. Y. Num. XXIV, 19</span> Levita (ed. <span dir=\"rtl\">קוסטנטיני</span>, <span dir=\"rtl\">קושט׳</span>); a. fr. (mostly changed through the censor’s influence).—Y. Ab. Zar. I, 39ᶜ <span dir=\"rtl\">יום שנתחתן שלמה … וזהו כרך גדול שבר׳</span> on the day that Solomon was connected by marriage with Pharaoh Necho of Egypt, Michael stuck a reed into the sea …, and this is the origin of the great city of the Roman empire; <span class=\"citation\">Snh. 21ᵇ</span>; <span class=\"citation\">Sabb. 56ᵇ</span> Ms. M. (ed. <span dir=\"rtl\">שברומי</span> omitted). Y. Ab. Zar. l. c. <span dir=\"rtl\">יום שנסתלק … מלך בר׳</span> on the day that Elijah was removed, a king was installed in Rome. Y. Taan. I, 64ᵃ top <span dir=\"rtl\">בספרו … משא דומה משא ר׳</span> (not <a href=\"#\" data-headword=\"דּוּמִי\">דומי</a>) in R. Meir’s Bible was (a note) written, <i>massa dumah</i> (<span class=\"citation\">Is. XXI, 11</span>) ‘the burden of Rome.’ Ib. <span dir=\"rtl\">אם יאמר לך … בכרך הגדול שבר׳</span> if one should ask thee, where is thy God? tell him, in the great city of Rome; a. v. fr.—<span class=\"citation\">Ab. Zar. 8ᵃ</span> <span dir=\"rtl\">ר׳ שעשתה קלנדא</span> (Alf. <a href=\"#\" data-headword=\"*עַיִר\">עיר</a>) a Roman colony which celebrates the Calenda.</div>","alt":["רוֹמָא"]},"28998":{"h":"רוֹמִי II","r":"T00389","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוֹמִי I\">preced.</a>) <i>Roman</i>. Y. Ter. VIII, end, 46ᶜ; <span class=\"citation\">Gen. R. s. 63</span>, v. <a href=\"#\" data-headword=\"בְּסָא\">בְּסָא</a>. <span class=\"citation\">Y. Sot. VII, 21ᶜ</span> top, a. e. <a href=\"#\" data-headword=\"ר׳\">ר׳</a> the Roman language (Latin), v. <a href=\"#\" data-headword=\"קְרָב\">קְרָב</a>; a. e.—Pl. <span dir=\"rtl\">רוֹמִיִּים</span>. <span class=\"citation\">Yalk. Hos. 529</span> <span dir=\"rtl\">ידע הקב&quot;ה … גזירות ר׳ וכ׳</span> the Lord knew that Israel could not endure the decrees of the Romans, therefore he made them emigrate to Babylonia; <span class=\"citation\">Gitt. 17ᵃ</span> <span dir=\"rtl\">ארומיים</span>; <span class=\"citation\">Pes. 87ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲרָם\">אֲרָם</a>. <span class=\"citation\">Ib. 119ᵃ</span>. <span class=\"citation\">Pesik. R. s. 17</span>, end (play on <span dir=\"rtl\">ראמים</span>, <span class=\"citation\">Is. XXXIV, 7</span>) <span dir=\"rtl\">ר׳ עמם</span> the Romans will go down with them; a. e.</div>","alt":[]},"28999":{"h":"רומי","r":"T00390","html":"<div class=\"sense\">, Midr. Sam. XII <span dir=\"rtl\">מחושקת כר׳</span>, v. <a href=\"#\" data-headword=\"רֶקֶם I\"><span dir=\"rtl\">רֶקֶם</span> I</a></div>","alt":[]},"29000":{"h":"שְׁאֵילָא","r":"U00024","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵלְתָּא\">שְׁאֵלְתָּא</a></div>","alt":[]},"29001":{"h":"שְׁאֵילָה","r":"U00025","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵלָה</a></div>","alt":[]},"29002":{"h":"שְׁאִילָה","r":"U00026","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁאַל\">שָׁאַל</a>) </div><div class=\"sense\"><b>1)</b>  (with <a href=\"#\" data-headword=\"שָׁלוֹם I\">שלום</a>, or sub. <a href=\"#\" data-headword=\"שָׁלוֹם I\">שלום</a>) <i>salutation, greeting</i>. <span class=\"citation\">Y. Ber. V, 9ᵃ</span> <span dir=\"rtl\">במלכי או&quot;ה משיב שְׁאִילַת שלום</span> as regards gentile kings, you may answer the greeting (during prayer). <span class=\"citation\">Y. M. Kat. III, 82ᵃ</span> bot. <span dir=\"rtl\">איגרות של רשות זו ש׳ שלום</span> “letters of a secular character” (ib. III, 3), that means, social correspondence. <span class=\"citation\">Macc. 23ᵇ</span> <span dir=\"rtl\">(<span dir=\"rtl\">בשם</span>) <span dir=\"rtl\">וש׳ שלום</span></span> and using the name of the Lord in salutation. <span class=\"citation\">Shebu. 32ᵃ</span>, a. fr. <span dir=\"rtl\">כדי שאילת תלמיד לרב</span> as much time as is required for the disciple to salute the teacher <span dir=\"rtl\">(שלום עליך רבי</span>); <span dir=\"rtl\">כדי ש׳ הרב לתלמיד</span> as is required for the teacher to salute the pupil <span dir=\"rtl\">(שלום עליך</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>borrowing</i>. <span class=\"citation\">B. Mets. 95ᵇ</span> <span dir=\"rtl\">עד שיהו בעלים משעת ש׳ עד וכ׳</span> (the borrower is responsible,) unless the owner is present from the moment of lending the animal to that of the accident. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ש׳ בבעלים</span> borrowing an object together with employing its owner for service. <span class=\"citation\">Ib. 98ᵃ</span>, sq. <span dir=\"rtl\">שאילה</span> (interch. with <a href=\"#\" data-headword=\"שְׁאֵלָה\">שַׁאֲלָה</a> or <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵלָה</a>), v. <a href=\"#\" data-headword=\"שְׂכִירוּת\">שְׂכִירוּת</a>; a. fr.—V. <a href=\"#\" data-headword=\"שְׁאֵילָה\">שְׁאֵילָה</a>.</div>","alt":[]},"29003":{"h":"שְׁאִילְתָּא","r":"U00027","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Sh’ilta</i>. <span class=\"citation\">Gitt. 39ᵇ</span> (marg. correction <a href=\"#\" data-headword=\"שִׁילַת\">שִׁילֵת</a>).</div>","alt":[]},"29004":{"h":"שְׁאֵילְתָּא","r":"U00028","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵלְתָּא\">שְׁאֵלְתָּא</a></div>","alt":[]},"29005":{"h":"שְׁאֵיר","r":"U00029","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵר\">שְׁאֵר</a></div>","alt":[]},"29006":{"h":"שָׁאַל","r":"U00030","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to ask, beg; to inquire, question</i>. <span class=\"citation\">Yoma 75ᵃ</span> bot. <span dir=\"rtl\">בשר ששָׁאֲלוּ שלא וכ׳</span> flesh for which they asked unreasonably was given them at an unreasonable time (in the evening) &amp;c. <span class=\"citation\">Taan. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"הוֹגָן\">הוֹגָן</a>. <span class=\"citation\">Ber. V, 2</span> (<span class=\"citation\">33ᵃ</span>) <span dir=\"rtl\">הגשמים וכ׳</span> (<a href=\"#\" data-headword=\"זֶה\">את</a>) <span dir=\"rtl\">ושׁוֹאֲלִין</span> (Bab. ed. <span dir=\"rtl\">ושְׁאֵלָה</span>, v. Rabb. D. S. a. l.) and the prayer for rain is inserted in the Benediction of Years (the ninth section of the Prayer of Benedictions, v. <a href=\"#\" data-headword=\"שָׁנָה\">שָׁנָה</a>). <span class=\"citation\">Taan. I, 1</span> אף אני לא אמרתי לִשְׁאוֹל אלא להזכיר I also did not say, ‘to ask’ for rain, but to mention rain. <span class=\"citation\">Ib. 2</span>. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> bot. <span dir=\"rtl\">שׁוֹאֵל צרכיו</span>, v. <a href=\"#\" data-headword=\"צוֹרֶךְ\">צוֹרֶךְ</a>. <span class=\"citation\">B. Bath. IX, 1</span> <span dir=\"rtl\">יִשְׁאֲלוּ וכ׳</span>, v. <a href=\"#\" data-headword=\"פֶּתַח\">פֶּתַח</a>. <span class=\"citation\">Ab. IV, 18</span> <span dir=\"rtl\">ואל תִּשְׁאַל לו בשעת נדרו</span> ask not thy neighbor (as to circumstances which may change the aspects of his vow) at the moment of his vow, v. infra <i>Nif.</i> <span class=\"citation\">Ib. V, 7</span> <span dir=\"rtl\">שואל כענין ומשיב וכ׳</span> he (the wise student) asks pertinent questions, and (when asked) replies in agreement with the adopted law. <span class=\"citation\">Bekh. 36ᵃ</span> <span dir=\"rtl\">עמד השואל וש׳ יכ׳</span> the questioner (at college) arose and asked &amp;c. <span class=\"citation\">Ned. 20ᵃ</span> <span dir=\"rtl\">שָׁאֲלוּ את וכ׳</span> they asked Imma Shalom &amp;c. <span class=\"citation\">Nidd. 68ᵇ</span> <span dir=\"rtl\">בראשון לא שָׁאַלְתִּי … שלא שאלתי</span> as to the first day I did not ask, and I made a mistake in not asking. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">מטרונה שָׁאֲלָה וכ׳</span> a Roman matron asked R. José &amp;c.; a. v. fr.—<span class=\"citation\">Yoma 73ᵃ</span> <span dir=\"rtl\">כיצד שׁוֹאֲלִין השואל פניו כלפי נִשְׁאָל הנשאל וכ׳</span> how were the Urim and Tummim consulted? The inquirer had his face directed to him (the priest) who was consulted, and the latter directed himself to the Divine Presence (the Urim and Tummim). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין שואלין שני וכ׳</span> you must not ask two questions at a time; a. fr.—<span dir=\"rtl\">ש׳ בשלום</span> (or sub. <span dir=\"rtl\">בשלום</span>) <i>to salute</i>. <span class=\"citation\">M. Kat. 21ᵇ</span> <span dir=\"rtl\">הוא שואל בשלום אחרים … אחרים אין שואלין בשלומו וכ׳</span> he (the mourner during the first thirty days) may inquire after the peace of others, for they dwell in peace, but others must not inquire after his peace, for he does not dwell in peace. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משיב ואינו שואל</span>, v. <a href=\"#\" data-headword=\"שׁוּב I\">שׁוּב</a>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"דָּרַשׁ\">דָּרַשׁ</a>) <i>to discuss, lecture</i>. Tosef. Meg. IV (III), 5 <span dir=\"rtl\">שואלין הילכות וכ׳</span> the laws of Passover are expounded on Passover &amp;c., v. <a href=\"#\" data-headword=\"עִנְיָן\">עִנְיָן</a>; <span class=\"citation\">Meg. 29ᵇ</span> <span dir=\"rtl\">שואלין בהלכות וכ׳</span>; <span class=\"citation\">Y. Pes. I, 27ᵇ</span> bot.; Bab. <span class=\"citation\">Pes. 6ᵃ</span> שואלין בהלכות וכ׳ Ms. M. (ed. <span dir=\"rtl\">שואלין ודורשין</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Snh. 12ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"בְּעֵי I\"><span dir=\"rtl\">בְּעֵי</span> I</a>) <i>to beg to remark, to submit</i>. <span class=\"citation\">Y. Shek. I, beg. 45ᵈ</span> ר׳ חזקיה ש׳ מעתה וכ׳ R. Ḥ. remarked, according to this &amp;c. Ib. 46ᵇ. <span class=\"citation\">Y. Snh. IX, 27ᵃ</span> bot.; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to ask for a loan, to borrow</i>. <span class=\"citation\">Sabb. XXIII, 1</span> <span dir=\"rtl\">שואל אדם מחבירו וכ׳</span> a man may borrow of his neighbor vessels of wine or oil (on the Sabbath), but must not say <span dir=\"rtl\">הַלְוֵינִי</span> (v. infra <i>Hif.</i>); a. fr.—Esp. <i>to borrow an object for use</i> (with ref. to <span class=\"citation\">Ex. XXII, 13</span> sq.). <span class=\"citation\">B. Mets. 103ᵃ</span> <span dir=\"rtl\">שואל אדם בטובו לעולם</span> if a person borrows an object (saying, ‘lend it to me) for its usefulness’, it is a standing loan (he is permitted to take it whenever he desires to use it). <span class=\"citation\">Ib. VIII, 1</span> <span dir=\"rtl\">השואל את הפרה וש׳ בעליה עמה</span> if a person borrows a cow for work, borrowing her owner with her (the owner lending his personal service). <span class=\"citation\">Ib. 95ᵇ</span> <span dir=\"rtl\">שָׁאֲלָהּ ואחר כך ש׳ וכ׳</span> if he borrowed the cow only, and after a while borrowed her owner; a. fr.—שׁוֹאֵל <i>the borrower</i> of an object. <span class=\"citation\">Ib. 95ᵃ</span> <span dir=\"rtl\">חיובא דש׳</span> the responsibility of the borrower. <span class=\"citation\">Ib. 96ᵇ</span> top <span dir=\"rtl\">ש׳ הוי או שוכר הוי</span> is he legally considered a borrower or a hirer? <span class=\"citation\">Ib. III, 2</span> <span dir=\"rtl\">והש׳ ישלם וכ׳</span> and the borrower must indemnify the hirer; a. fr.—<span class=\"citation\">Sabb. 96ᵇ</span> <span dir=\"rtl\">אורגי … לשׁוֹאֲלֵיהֶן</span> (Ar. <span dir=\"rtl\">לשווליהן</span>, v. <a href=\"#\" data-headword=\"שְׁוַולְיָא\">שְׁוַולְיָא</a>) the curtain weavers were wont to throw the clue over to such as would borrow it from them.—Part. pass. <a href=\"#\" data-headword=\"שָׁאוּל\">שָׁאוּל</a>; f. <a href=\"#\" data-headword=\"שְׁאוּלָה\">שְׁאוּלָה</a> &amp;c. <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">טלית ש׳ היתה וכ׳</span> it was a cloak that had been lent to me, I had borrowed it for such a purpose (for ordinary wear), but not for that purpose (to wear it when carrying a load). <span class=\"citation\">Ib. IV, 8</span> <span dir=\"rtl\">שבחן … בכלי לבן שְׁאוּלִין וכ׳</span> on those days the maidens of Zion went out (to the vineyards) in white garments borrowed for the purpose, in order not to put to shame those who had none; a. fr.— [<span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">לא שאול … ולא שאולה</span>, v. next w.—<span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">שאולת חומץ</span>, read: <span dir=\"rtl\">שׁוֹאֶלֶת</span>, a woman asking for some vinegar.]</div><div class=\"sense\"><b>Hif. הִשְׁאִיל</b> <div class=\"sense\"><b>1)</b> <i>to cause inquiry, to inquire</i>. <span class=\"citation\">Ber. 6ᵇ</span> <span dir=\"rtl\">כל הרגיל … הקב&quot;ה מַשְׁאִיל בו</span> if one who comes regularly to synagogue fails to come one day, the Lord holds inquiry about him. <span class=\"citation\">Yeb. 76ᵇ</span> <span dir=\"rtl\">עד שאתה משאיל עליו … שְׁאַל וכ׳</span> instead of inquiring about him whether or not he is fit for government, ask whether &amp;c. <span class=\"citation\">Ib.</span> (in Chald. dict.) <span dir=\"rtl\">אאבוה קא משאיל</span> he (Saul) asked (Abner) to inquire who his (David’s) father was. <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">היתה יושבת … ומַשְׁאֶלֶת וכ׳</span> she sat at the cross-roads and made inquiries; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to lend</i>. <span class=\"citation\">Sabb. 148ᵃ</span> (ref. to Mish. <span class=\"citation\">ib. XIII, 1</span>, v. supra) <span dir=\"rtl\">מאי שנא הַשְׁאִילֵינִי ומאי שנא הלויני</span> what is the difference, whether you say <i>hashileni</i> (lend me) or <i>halveni</i> (loan me)? <span dir=\"rtl\">השאיליני לא אתי למיכתב וכ׳</span> when you say ‘lend me’, no document is expected to be written for it &amp;c. <span class=\"citation\">Ned. IV, 6</span> <span dir=\"rtl\">חמודר … לא יַשְׁאִילֶנּוּ ולא יִשְׁאַל ממנו</span> he who by his neighbor’s vow is forbidden any benefit at his hand, must neither lend him nor borrow from him &amp;c. <span class=\"citation\">B. Mets. 116ᵃ</span> <span dir=\"rtl\">דברים העשויין להַשְׁאִיל וכ׳</span> things which are frequently lent out or hired out; a. fr.—מַשְׁאִיל <i>the lender, owner of the lent object</i>. <span class=\"citation\">Ib. 96ᵃ</span>; a. fr.—[Pesik. Vayhi, p. 63ᵃ <span dir=\"rtl\">שאילו השאיל</span>, v. <a href=\"#\" data-headword=\"שָׁחַל II\"><span dir=\"rtl\">שָׁחַל</span> II</a>.]</div></div><div class=\"sense\"><b>Nif. נִשְׁאַל</b> <div class=\"sense\"><b>1)</b> <i>to be asked, consulted</i>. <span class=\"citation\">Yoma 73ᵃ</span> <span dir=\"rtl\">בגדים … נ׳ בהן</span> when the war chaplain is consulted, he wears the garments which the high priest wears when he officiates, v. supra. <span class=\"citation\">Ib. 85ᵃ</span> <span dir=\"rtl\">נִשְׁאֲלָח שאלה וכ׳</span> the following question was asked in their presence; <span class=\"citation\">Kidd. 40ᵇ</span>. <span class=\"citation\">Ned. 81ᵃ</span> <span dir=\"rtl\">דבר זה נ׳ לחכמים וכ׳</span> this problem was placed before the scholars and the prophets, and they could not solve it &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b>  נ׳ על <i>to allow one’s self to be asked about the circumstances of a case, to appear before a scholar for a decision on a ritual case</i>. Y. Ter. VIII, 46ᵃ bot. <span dir=\"rtl\">שדעתו להִישָּׁאֵל עליה</span> a case (of T’rumah) which he had intended to have a scholar decide. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הריני מניחה על מנת שאֶישָּׁאֵל עליה</span> I put it (the doubtful T’rumah) aside with the intention of having it decided &amp;c. <span class=\"citation\">Toh. III, 6</span> <span dir=\"rtl\">שאין בו דעת להִשָּׁאֵל</span> (a child) whose mind is not sufficiently developed to be questioned. <span class=\"citation\">Ib. V, 5</span> <span dir=\"rtl\">אם נִשְׁאֲלוּ זה וכ׳</span> if they come for a decision, each of them separately; a. fr.—Esp. (<span dir=\"rtl\">על נדרו</span>) <a href=\"#\" data-headword=\"נ׳\">נ׳</a> <i>to come before a scholar for absolution from a vow</i>. <span class=\"citation\">Ned. 90ᵃ</span> <span dir=\"rtl\">קונם … ולמי שאֶשָּׁאֵל עליו</span> if one vows, I will not be benefited by N. N., nor by any scholar to whom I may apply for absolution from this vow; <span dir=\"rtl\">נ׳ על הראשון וכ׳</span> he must first apply for absolution from the first part of the vow, and then from the second. Ib. <span dir=\"rtl\">נ׳ על נדרו … נזרו</span> he must first apply for absolution from his vow of abstinence, and then from his nazaritic vow. Ib. 69ᵃ <span dir=\"rtl\">נִשְׁאָלִין על ההקם וכ׳</span> you may apply for absolution in order to revoke your confirmation (of your daughter’s vow), but you cannot do so in order to revoke your invalidation; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be borrowed, to do gratuitous service</i>. <span class=\"citation\">B. Mets. 96ᵃ</span> <span dir=\"rtl\">שותפין ששאלו ונ׳ לאחד מהן</span> if partners borrow an animal for work, and its owner lends his services to one of them individually. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">האומר לשלוחו צא והִשָּׁאֵל לי וכ׳</span> (not <span dir=\"rtl\">והשאיל</span>) if a person says to his deputy, go out and do work in my behalf together with my cow (lent to my neighbor). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">האומר לעבדו צא והשאל עם וכ׳</span> if he says to his slave, go out and do work &amp;c.; a. e.</div></div>","alt":[]},"29007":{"h":"שְׁאַל","r":"U00031","html":"<div class=\"sense\"><b>1)</b> <i>to ask, inquire, beg.</i> <span class=\"citation\">Targ. II Kings III, 11</span>. <span class=\"citation\">Targ. I Kings XIX, 4</span>. <span class=\"citation\">Targ. Job XXXI, 30</span> למִשְׁאַל Ms. (ed. <span dir=\"rtl\">למִשְׁיַיל</span>, <span dir=\"rtl\">למִשְׁיַל</span>). <span class=\"citation\">Targ. Y. Deut. I, 1</span> <span dir=\"rtl\">שַׁיְילְתוּן</span> (ed. Vien. <span dir=\"rtl\">שַׁיְילַתַּוּן</span>, read: <span dir=\"rtl\">שַׁיַּילְתּוּן</span>, <i>Pa</i>). <span class=\"citation\">Targ. Ps. CXXXVII, 3</span>; a. fr.—<span dir=\"rtl\">ש׳ לשלם</span>, <span dir=\"rtl\">ש׳ בשלם</span>, v. <a href=\"#\" data-headword=\"שְׁלָם\">שְׁלָם</a>.—<span class=\"citation\">Sabb. 20ᵇ</span>; <span class=\"citation\">21ᵃ</span> <span dir=\"rtl\">שְׁאִילְתִּינְהוּ לכל וכ׳</span>, v. <a href=\"#\" data-headword=\"נָחוֹתָא\">נָחוֹתָא</a>. <span class=\"citation\">Ib. 30ᵃ</span> <span dir=\"rtl\">שׁאוּל שאילה זו וכ׳</span> they asked the following question &amp;c., v. <a href=\"#\" data-headword=\"עֵיל\">עֵיל</a>. <span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">אי איכא דשָׁאֵיל לי וכ׳</span> if any one were to ask me a question from the Mishnah of &amp;c. <span class=\"citation\">Y. Shebi. VII, 37ᶜ</span> top <span dir=\"rtl\">הא גברא מִישְׁאֲלִינֵיה אתא שַׁאֲלוּנֵיה וכ׳</span> (not <span dir=\"rtl\">מישאלינית</span>) here is a man whom you night ask; he came, and they asked; a. fr.—Part. pass. <a href=\"#\" data-headword=\"שְׁאֵיל\">שְׁאִיל</a>. <span class=\"citation\">Sabb. 30ᵇ</span> <span dir=\"rtl\">ולענין שאילה דשְׁאִילְנָא קדמיכון</span> and as to the question which I have been asked in your presence; [Rashi: <span dir=\"rtl\">דשָׁאֵילְנָא</span> which I asked, a courteous phrase for ‘which you asked of me’]; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to borrow</i>. <span class=\"citation\">Targ. Ex. XXII, 13</span>; a. fr.—[<span class=\"citation\">Targ. O. ib. XII, 36</span>, v. infra <i>Af</i>.]—<span class=\"citation\">B. Mets. 97ᵃ</span> <span dir=\"rtl\">ההוא גברא דש׳ וכ׳</span> a man borrowed a cat from his neighbor &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">האי … למִישְׁאַל מידי וכ׳</span> if one wishes to borrow an object from his neighbor and be free from responsibility for an accident &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נימא ליה שְׁאֵיל וכ׳</span> let him (the lender) say to him, first take what you want to borrow, and then &amp;c. <span class=\"citation\">Yeb. 120ᵇ</span> <span dir=\"rtl\">לא שָׁיְילֵי</span> (not <span dir=\"rtl\">שיולי</span>); <span class=\"citation\">B. Mets. 27ᵇ</span> <span dir=\"rtl\">לא שְׁאִילֵי</span>, v. <a href=\"#\" data-headword=\"סְקַב\">סְקַב</a>; a. fr.—Part. pass. as ab. <span class=\"citation\">Ib. 97ᵃ</span> <span dir=\"rtl\">שאיל לן מר</span> you (as teacher) are loaned to us, i.e. you are in our service, and if we borrow an object from you, we are not responsible, it being <span dir=\"rtl\">שאילה בבעלים</span>, v. <a href=\"#\" data-headword=\"שְׁאִילָה\">שְׁאִילָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתון שְׁאִילְתּוּן לי</span> you are in my service. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איהו ש׳ להו … אינהו שְׁאִילוּ ליה וכ׳</span> he (the teacher) is in their (the scholar’s) service on the Kallah day (v. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>); they are in his on any other day; a. e.—<span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">לא שאיל הוא לה ולא שְׁאִילָה היא ליה</span> (some ed. <span dir=\"rtl\">שאול … שאולה</span>) he is not loaned to her, nor she to him, i.e. the simile does not fit the application, nor the application the simile.</div><div class=\"sense\"><b>Pa. שַׁיֵּיל</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שָׁאַל\">same</a>, <a href=\"#\" data-headword=\"שָׁאַל\">same</a>, <i>to ask, borrow</i> &amp;c. <span class=\"citation\">Targ. Y. Ex. XII, 35</span>; a. e.—<span class=\"citation\">Bets. 19ᵃ</span> <span dir=\"rtl\">אתא … לשַׁיּוּלֵי וכ׳</span> he came before the Rabbis to ask &amp;c. <span class=\"citation\">Ḥull. 3ᵇ</span> <span dir=\"rtl\">דליתיה קמן דלִישַׁיְּילֵיה</span> when he is not before us so that we could ask him. <span class=\"citation\">Tam. 32ᵃ</span> מְשַׁיַּילְנָא לכו I am asking you; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to lend</i>. <span class=\"citation\">Targ. Y. Ex. XII, 36</span>.—<span class=\"citation\">Taan. 21ᵇ</span>, v. <a href=\"#\" data-headword=\"זְבִילָא\">זְבִילָא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דמחממת … ומְשַׁיְּילָא וכ׳</span> who heated her oven and let her neighbors use it; a. fr.</div></div><div class=\"sense\"><b>Af. אַשְׁאֵיל  אוֹשֵׁל</b> <div class=\"sense\"><i>to lend</i>. <span class=\"citation\">Targ. O. Ex. XII, 36</span> ed. Berl. (ed. Vien. <span dir=\"rtl\">שאילינון</span>, corr. acc.); a. e.—Yeb. l. c. <span dir=\"rtl\">ולא מוֹשְׁלֵי</span>, v. <a href=\"#\" data-headword=\"נְחַשׁ I\"><span dir=\"rtl\">נְחַשׁ</span> I</a>. <span class=\"citation\">B. Mets. 116ᵃ</span> <span dir=\"rtl\">דעביד לאוֹשׁוּלֵי וכ׳</span> which it is customary to lend and hire out; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתָּאַל</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּאֵיל  אִתְּשִׁיל</b> <div class=\"sense\"><b>1)</b>  (with (with <span dir=\"rtl\">מ־</span>) <i>to take leave of absence</i>. <span class=\"citation\">Targ. I Sam. XX, 6</span>.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"ב\">ב־</a>) <i>to allow one’s self to be inquired of; to answer, issue an oracle</i>. <span class=\"citation\">Targ. Ez. XIV, 3</span>. <span class=\"citation\">Targ. Y. II, Num. XXIV, 1</span>. <span class=\"citation\">Targ. Is. LXV, 1</span>.</div><div class=\"sense\"><b>—3)</b>  (with <span dir=\"rtl\">ל־</span>) <i>to bring a case up for decision, to ask</i>. Y. Maasr. II, beg. 49ᶜ אִשְׁתָּאֲלִית לאילין וכ׳ I asked those of the house of &amp;c. Y. Sabb. XII, 13ᶜ bot., <span dir=\"rtl\">אִשְׁתַּאֲלַת לר׳ שמעון וכ׳</span> R. S. b. L. was asked. Ib. VI, 8ᵃ <span dir=\"rtl\">ואִיתְשְׁלַת לר׳ ומר וכ׳</span> when the case was brought before Rabbi, he said &amp;c.; a. fr.—Esp. <i>to come before a scholar for absolution from a vow</i>. <span class=\"citation\">Ned. 90ᵃ</span> <span dir=\"rtl\">אי בעי על נדרו איתשיל ברישא וכ׳</span> if he so desires, he may ask first for absolution from his vow of abstinence, or if he chooses, he may ask first for absolution from his nazaritic vow; <span class=\"citation\">ib.</span> <span dir=\"rtl\">נִיתְּשִׁיל</span>; a. fr.</div></div>","alt":["שְׁאֵיל","שְׁיֵיל","שְׁיֵל"]},"29008":{"h":"שְׁאֵלָא","r":"U00032","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵלְתָּא\">שְׁאֵלְתָּא</a></div>","alt":["שְׁאָלָא"]},"29009":{"h":"שְׁאֵלָה","r":"U00033","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>request</i>, esp. <i>sh’elah, prayer for rain</i>, inserted in the ninth section of the Prayer of Benedictions. <span class=\"citation\">Ber. V, 2</span> (<span class=\"citation\">33ᵃ</span>), v. <a href=\"#\" data-headword=\"שָׁאַל\">שָׁאַל</a>. <span class=\"citation\">Ber. 26ᵇ</span>; <span class=\"citation\">29ᵃ</span> <span dir=\"rtl\">טעה … ש׳ בברכת השנים</span> (v. Ms. M. in Rabb. D. S. a. l.) if by mistake … he omitted the prayer for rain in the ninth section; (Tosef. ib. III, 9 <span dir=\"rtl\">ולא שאל את הגשמים</span>). <span class=\"citation\">Taan. 4ᵇ</span> <span dir=\"rtl\">ש׳ לחוד והזכרה לחוד</span> prayer for rain is one thing, and reference to rain (in the second section) is another thing, v. <a href=\"#\" data-headword=\"הַזְכָּרָה\">הַזְכָּרָה</a>. <span class=\"citation\">Ib. 2ᵇ</span> <span dir=\"rtl\">משעה שמפסיק לש׳ וכ׳</span> when you cease to insert the prayer for rain, you must also cease to insert the reference to rain; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>question, problem</i>. <span class=\"citation\">B. Kam. 116ᵃ</span> זו ש׳ היא Ms. H. (ed. <span dir=\"rtl\">וזו שאילה</span>) this is indeed a question (worth asking); <span class=\"citation\">Zeb. 30ᵇ</span>; <span class=\"citation\">92ᵇ</span>. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">ש׳ גדולה שאלת</span> thou hast asked a great question; a. fr.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"שָׁאַל\">שָׁאַל</a>, <i>Nif.</i>) <i>ritual question</i>, esp. <i>case of absolution from a vow brought before a scholar</i>. <span class=\"citation\">Num. R. s. 11</span><sup>3</sup> <span dir=\"rtl\">אם באת … על הדין ועל הש׳ וכ׳</span> when a woman comes to thee at college to ask concerning a law or a vow, consider her as if she were thy own daughter. <span class=\"citation\">Ned. 60ᵃ</span> <span dir=\"rtl\">צריך ש׳ לחכם</span> this requires absolution by a scholar. <span class=\"citation\">Ib. 69ᵃ</span> <span dir=\"rtl\">יש ש׳ בהקם</span> can absolution from confirmation be applied for? <span class=\"citation\">Ib. 78ᵃ</span>; <span class=\"citation\">B. Bath. 120ᵇ</span> <span dir=\"rtl\">יש ש׳ בהקדש</span> absolution from consecration of an object may eventually be had; <span dir=\"rtl\">אין ש׳ וכ׳</span> is not admissible; a. fr.—Pl. <span dir=\"rtl\">שְׁאֵלוֹת</span>, <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵי׳</a>. <span class=\"citation\">Gen. R. s. 82</span>; <span class=\"citation\">Yalk. ib. 136</span> שלש ש׳ אני וכ׳ I shall ask you three questions; if you answer them, it is right &amp;c. <span class=\"citation\">Gen. R. s. 49</span>, v. <a href=\"#\" data-headword=\"עִרְבּוּב\">עִרְבּוּב</a>; a. e.</div><div class=\"sense\"><b>—4)</b>  <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵלָה</a> or <a href=\"#\" data-headword=\"שְׁאֵלָה\">שַׁאֲלָה</a>, <i>loan</i>, v. <a href=\"#\" data-headword=\"שְׁאֵילָה\">שְׁאֵילָה</a>.</div>","alt":["שְׁאִי׳"]},"29010":{"h":"שְׁאֵלְתָּא","r":"U00034","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"שְׁאֵלָה\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>request, prayer, desire</i>. <span class=\"citation\">Targ. Jud. VIII, 24</span>. <span class=\"citation\">Targ. I Kings II, 16</span> (ed. Wil. <a href=\"#\" data-headword=\"שְׁאֵלָא\">שְׁאָלָא</a>; ed. Lag. <a href=\"#\" data-headword=\"שְׁאֵלָה\">שאלה</a>). <span class=\"citation\">Targ. Num. XI, 4</span> (h. text <a href=\"#\" data-headword=\"תַּאֲוָה\">תאוה</a>). <span class=\"citation\">Targ. Esth. V, 6</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>question, problem</i>. <span class=\"citation\">Targ. Jer. XII, 1</span> <span dir=\"rtl\">שְׁאֵילַת דינין</span> (h. text <span dir=\"rtl\">משפטים</span>).—<span class=\"citation\">Sabb. 30ᵃ</span> שאילתא Ms. M. (ed. <span dir=\"rtl\">שאילה</span>); <span class=\"citation\">ib.ᵇ</span> <span dir=\"rtl\">ולענין שאילה</span>, v. <a href=\"#\" data-headword=\"שְׁאֵיל\">שְׁאֵל</a>.</div><div class=\"sense\"><b>—3)</b> <i>proposition, remark</i>, esp. as heading of <i>decisions</i> in Sh’eltoth d’R. Aḥai, and in citations therefrom. Tanḥ. <span class=\"citation\">B’resh. 2</span>. Tanḥ. Noah 4; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁאֵלְתָּא\">שְׁאֵלָתָא</a>, <a href=\"#\" data-headword=\"שְׁאֵלָא\">שְׁאֵלָן</a>, <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵי׳</a>. <span class=\"citation\">Targ. Y. Deut. VIII, 9</span>.—Y. Naz. VIII, 56ᵇ; a. e.</div>","alt":["שְׁאֵילְתָּא","שְׁאֵילָא"]},"29011":{"h":"שַׁאֲמֵם","r":"U00035","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁעֲמֵם\">שַׁעֲמֵם</a></div>","alt":[]},"29012":{"h":"שאן","r":"U00036","html":"<div class=\"sense\">, <span class=\"citation\">Targ. I Sam. XIX, 24</span> Ar., v. <a href=\"#\" data-headword=\"*ברשאן\">בִּרְשָׁן</a></div>","alt":["בר ש׳"]},"29013":{"h":"שְׁאָן","r":"U00037","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Bethshean</i> (Scythopolis), in Galilee. <span class=\"citation\">Ḥull. 6ᵇ</span> והתיר רבי את ב׳ ש׳ כולה Rabbi permitted the entire territory of Bethshean (permitted its fruits to be eaten without tithes, it being considered foreign territory). <span class=\"citation\">Y. Kidd. II, 62ᶜ</span> bot. <span dir=\"rtl\">כלי פשתן … מב׳ ש׳</span> the finer linen garments that come from B.; <span class=\"citation\">Y. Keth. VII, 31ᶜ</span> <span dir=\"rtl\">בית שָׁן</span>; <span class=\"citation\">Koh. R. to I, 18</span>. <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">תהום ב׳ ש׳ וכ׳</span> the district of B. is named Kinnereth; a. fr.—V. <a href=\"#\" data-headword=\"בֵּישָׁן\">בֵּישַׁן</a>.</div>","alt":["בֵּית שְׁ׳"]},"29014":{"h":"שָׁאנִי","r":"U00038","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a></div>","alt":["שַׁאֲנִי"]},"29015":{"h":"שַׁאֲנָן","r":"U00039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> שאן <i>to rest</i>) </div><div class=\"sense\"><b>1)</b> <i>at ease, undisturbed</i>. <span class=\"citation\">Pirké d’R. El. ch. XXXVIII</span> <span dir=\"rtl\">אז … בטח וש׳ וכ׳</span> then Jacob dwelt in Canaan safe and undisturbed; <span class=\"citation\">Yalk. Gen. 138</span> <span dir=\"rtl\">בטח ש׳ ושליו</span>.</div><div class=\"sense\"><b>—2)</b> <i>rest, ease</i>. <span class=\"citation\">Gen. R. s. 10</span> end <span dir=\"rtl\">ומה … ש׳ ונחת שלוה והשקט</span> and what was created therein after he rested? Ease, rest, peace, and repose. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">זכורה אני בטחון וש׳ ושלוה שהייתי וכ׳</span> I remember the confidence and ease and contentment in which I used to dwell; a. e.</div>","alt":[]},"29016":{"h":"שָׂאסָא","r":"U00040","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָאסָא\">סָאסָא</a></div>","alt":[]},"29017":{"h":"שָׁאַף I","r":"U00041","html":"<div class=\"sense\"> (b. h.) = <a href=\"#\" data-headword=\"שׁוּף II\"><span dir=\"rtl\">שׁוּף</span> II</a>, <i>to tread, press</i>. <span class=\"citation\">Lev. R. s. 28</span>, a. e. (ref. to <a href=\"#\" data-headword=\"שָׁאַף I\">שאף</a>, <span class=\"citation\">Job V, 5</span>), v. <a href=\"#\" data-headword=\"דָּחַק\">דָּחַק</a>. Tanḥ. Mick. 2 (ref. to <span class=\"citation\">Dan. II, 2</span>) <span dir=\"rtl\">אשפים לשון דחק שנ׳ השואפים וכ׳</span> the root in <i>ashshafim</i> signifies pressure, as we read (<span class=\"citation\">Am. VIII, 4</span>), ‘hear ye this, <i>hashshoăfim</i> (who press) the needy. <span class=\"citation\">Midr. Till. to Ps. LI</span>. <span dir=\"rtl\">כל מי … ושׁוֹאֵף ברגלו וכ׳</span> he who knows that he has sinned, but stamps with his foot and removes the sin from his sight &amp;c.; a. e.</div>","alt":[]},"29018":{"h":"שְׁאָף","r":"U00042","html":"<div class=\"sense\">, to <i>rub</i>, v. <a href=\"#\" data-headword=\"שׁוּף II\"><span dir=\"rtl\">שׁוּף</span> II</a> ch.</div>","alt":[]},"29019":{"h":"שָׁאַף II","r":"U00043","html":"<div class=\"sense\"> (b. h.) = <a href=\"#\" data-headword=\"שׁוּף II\"><span dir=\"rtl\">שׁוּף</span> I</a>, <i>to blow, pant, long for</i>. <span class=\"citation\">Midr. Till. to Ps. CXIX, 131</span> <a href=\"#\" data-headword=\"כְּמוֹ\">כמו</a> (<a href=\"#\" data-headword=\"ש\">ש</a>)<span dir=\"rtl\">התנינים שׁוֹאֲפִים לרוח כן הייתי שׁוֹאֵף לתורתך</span> (not <span dir=\"rtl\">רוהך</span>) as the monsters pant for wind, so do I pant (longing) for thy Law.</div>","alt":[]},"29020":{"h":"שְׁאַף","r":"U00044","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שָׁאַף II\">same</a>. <span class=\"citation\">Targ. Job VII, 2</span>.—2) (cmp. <span dir=\"rtl\">שאב</span>) <i>to resorb</i>. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">ואתא זיקא ושָׁאֵיף ליה מיניה</span> and a hot wind may rise and suck it (the small quantity of blood left) out of him. <span class=\"citation\">Snh. 64ᵃ</span> דשאיף קליה Ms. M. Rashi (ed. <span dir=\"rtl\">דשייף</span>), v. <a href=\"#\" data-headword=\"שְׁאֵב\">שְׁאֵב</a>.—[<span class=\"citation\">Sabb. 139ᵇ</span> <span dir=\"rtl\">שאפו שיכרא</span>, v. <a href=\"#\" data-headword=\"שְׁחֵי II\"><span dir=\"rtl\">שְׁפֵי</span> II</a>.]</div>","alt":[]},"29021":{"h":"שָׁאפֵי","r":"U00045","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁפֵי ²\"><span dir=\"rtl\">שְׁפֵי</span> I</a></div>","alt":[]},"29022":{"h":"שָׁאקָא","r":"U00046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁקָא\">שָׁקָא</a></div>","alt":[]},"29023":{"h":"שָׁאַר","r":"U00047","html":"<div class=\"sense\"> (b. h.) <i>to swell, rise; to run over;</i> (cmp. <a href=\"#\" data-headword=\"יָתַר\">יָתַר</a>, <a href=\"#\" data-headword=\"עָדַף\">עָדַף</a>) <i>to remain over</i>. Denom. <a href=\"#\" data-headword=\"מִשְׁאֶרֶת\">מִשְׁאֶרֶת</a>, <a href=\"#\" data-headword=\"שְׁאָר\">שְׁאָר</a>, <a href=\"#\" data-headword=\"שְׁאֵר\">שְׁאֵר</a></div><div class=\"sense\"><b>Nif. נִשְׁאָר</b> <div class=\"sense\"><i>to be left over, reserved, preserved, spared</i>. <span class=\"citation\">Gen. R. s. 76</span> (ref. to <span class=\"citation\">Gen. XXXII, 9</span>) <span dir=\"rtl\">אלו אחינו … אע&quot;פ שנִשְׁאֲרוּ לפליטה וכ׳</span> this refers to our brethren in the diaspora …; although they have been spared for escape (from Roman persecution), yet they fasted for us (Palestinians) &amp;c. <span class=\"citation\">Cant. R. to II, 13</span> <span dir=\"rtl\">הנִשְׁאָרִים</span> the survivors of the Messianic days; a. e.</div></div><div class=\"sense\"><b>Pi. שֵׁיאֵר</b> <div class=\"sense\">,) <a href=\"#\" data-headword=\"שִׁיֵּיר\">שִׁיֵּיר</a> <i>to leave over, reserve</i>. <span class=\"citation\">B. Bath. IX, 6</span> <span dir=\"rtl\">שכיב … וש׳ וכ׳</span> if an ill person donated all his property to others and reserved some land for himself, his donation is valid (even if he recovers). <span class=\"citation\">Ib. 148ᵃ</span> <span dir=\"rtl\">דקל לאחד וש׳ פירותיו לפניו ש׳ מקום פירי</span> if he donated a palm-tree (for the wood of it) to a person, and reserved its fruit for himself, he meant to reserve for himself the place whereon the fruit grows (the branches). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל … בעין יפה מְשַׁיֵּיר</span> whatever one reserves for one’s self, one reserves liberally; a. v. fr.—Part. pass. <span dir=\"rtl\">מְשׁוֹאָר</span>, <span dir=\"rtl\">(מְשׁוּיָּיר</span>). Y. Pes. VII, 35ᵃ top <span dir=\"rtl\">לא עשה בה המש׳ כיוצא</span> the law does not treat that which is left over (of the sacrifice) like that which has been carried outside of its limits. <span class=\"citation\">Peah III, 3</span> <span dir=\"rtl\">נותּן מן המש׳ על מה ששייר</span> he must give to the poor out of the remainder in proportion to that which he left over; <span dir=\"rtl\">נותן מן המש׳ על הכל</span> he must give out of the remainder a quantity corresponding to the whole (including that which he has taken out before); a. fr.</div></div><div class=\"sense\"><b>Hif. הִשְׁאִיר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שָׁאקָא\">same</a>. <span class=\"citation\">Midr. Till. to Ps. IX</span> <span dir=\"rtl\">שלא להַשְׁאִיר זכר וכ׳</span> that he will not leave a remainder of the memory of Amalek; Yalk. ib. 642 <span dir=\"rtl\">להשאר</span> (corr. acc.); a. e.</div></div><div class=\"sense\"><b>Nithpa. נִשְׁתַּיֵּיר</b> <div class=\"sense\"><i>to be left over</i>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">ניטל … ולא נ׳ וכ׳</span> if the liver of a slaughtered animal is found consumed without any part of it left. <span class=\"citation\">Yoma 77ᵃ</span> <span dir=\"rtl\">לא נִשְׁתַּיְירוּ משונאיהן וכ׳</span> no remnant or survivor would have been left of the enemies of Israel (euphem. for ‘of Israel’); a. fr.</div></div>","alt":[]},"29024":{"h":"שְׁאַר I","r":"U00048","html":"<div class=\"sense\"><b>Af. אַשְׁאַר</b> <div class=\"sense\"><i>to leave over</i>. <span class=\"citation\">Targ. O. Ex. X, 12</span> (Y. <span dir=\"rtl\">שייר</span>). Ib. 26 <a href=\"#\" data-headword=\"שָׁאַר\">נַשְׁאַר</a> ed. Berl. (ed. Vien. <span dir=\"rtl\">תִּשְׁתָּאַר</span> <i>Ithpa.</i>); a. fr.</div></div><div class=\"sense\"><b>Pa. שָׁאֵר  שַׁיֵּיר</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"שִׁיר I\">שַׁיֵּר</a> same. <span class=\"citation\">Targ. Y. Ex. XII, 10</span> (O. <i>Af</i>.). <span class=\"citation\">Ib. X, 12</span>, v. supra; a. fr.—<span class=\"citation\">B. Kam. 15ᵃ</span> <span dir=\"rtl\">תנא וש׳ מאי ש׳ דהאי ש׳ ש׳ וכ׳</span> the Mishnah states some cases, but leaves over (does not state all cases coming under the same category). But what else did it omit, so as to be justified in omitting this? It omitted a case when half the assessed fine is to be paid; <span class=\"citation\">Succ. 54ᵃ</span>; a. fr.</div></div><div class=\"sense\"><b>Pali. שַׁאֲרֵי  שְׁאָרֵי</b> <div class=\"sense\"><i>to leave over, spare</i>. <span class=\"citation\">Targ. Ps. LXXIX, 11</span> Var. ed. Lag. (ed. Lag. a. oth. <a href=\"#\" data-headword=\"שרי\">שרי</a>; h. text <a href=\"#\" data-headword=\"נָתַר I\">הוֹתֵר</a>).</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתָּאַר  אִשְׁתַּיֵּיר</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּאַר</b> <div class=\"sense\"><i>to be left over, remain</i>. <span class=\"citation\">Targ. Gen. VII, 23</span>. <span class=\"citation\">Targ. Ex. VIII, 5</span>; a. fr.—<span class=\"citation\">B. Mets. 25ᵃ</span> <span dir=\"rtl\">א׳ בה מידי</span> some of it was left behind; a. e.</div></div>","alt":[]},"29025":{"h":"שְׁאַר II","r":"U00049","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"שְׁאַר I\">שָׁאֵר</a> (denom. of <a href=\"#\" data-headword=\"מִשְׁאַר\">מֵשָׁאר</a>, v. <a href=\"#\" data-headword=\"מֵישָׁרָא\">מֵישָׁרָא</a>) <i>to plant in beds</i>. <span class=\"citation\">B. Kam. 81ᵃ</span> <span dir=\"rtl\">שַׁאֲרֵיה מֵשָׁארֵי לאדם וכ׳</span> (Ms. M. <span dir=\"rtl\">שדיא משראי לשראי</span>, read: <span dir=\"rtl\">משארי משארי</span>; v. Rabb. D. S. a. l. note) if he planted in beds, it shows that he planted it for human food; if not, it is intended for cattle.</div>","alt":[]},"29026":{"h":"שְׁאֵר","r":"U00050","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"שָׁאַר\">שָׁאַר</a>) [<i>preservation, existence</i>,] </div><div class=\"sense\"><b>1)</b> <i>sustenance, alimentation</i>;</div><div class=\"sense\"><b>—2)</b>  (sub. <span dir=\"rtl\">בשר</span>) <i>body, flesh</i>; </div><div class=\"sense\"><b>3)</b> <i>bodily contact, intimacy</i>. Mekh. Mishp. s. 3 (ref. to <span dir=\"rtl\">שארה</span>, <span class=\"citation\">Ex. XXI, 10</span>) <span dir=\"rtl\">שְׁאֵרָהּ אלו מזונותיה וכ׳</span> <i>sh’erah</i> means her alimentation &amp;c. (ref. to <span class=\"citation\">Mic. III, 3</span>, a. <span class=\"citation\">Ps. LXXVIII, 27</span>); ib. (anoth. opin.) <span dir=\"rtl\">שארה כסותה כסות … לשְׁאֵרָהּ וכ׳</span> <i>sh’erah k’suthah</i> means, garments suited to her body (according to age and season) &amp;c.; ib. (anoth. opin.) <span dir=\"rtl\">שארה זו דרך ארץ</span> <i>sh’erah</i> means (intimacy) marital duty (ref. to <span class=\"citation\">Lev. XVIII, 6</span>; <span class=\"citation\">12</span>; <span class=\"citation\">13</span>, cmp. Targ.); <span class=\"citation\">Keth. 47ᵇ</span> <span dir=\"rtl\">לפום שארה תן כסותה וכ׳</span> according to her body (age) give her garments …, according to the season give her &amp;c.; Y. ib. V, 30ᵇ top. <span class=\"citation\">Sabb. 137ᵇ</span> <span dir=\"rtl\">חוק בשְׁאֵרוֹ</span>, v. <a href=\"#\" data-headword=\"חוֹק\">חוֹק</a>; <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> bot. <span dir=\"rtl\">בשְׁאֵירוֹ</span>.—Trnsf. [<i>flesh and blood</i>,] <i>relationship, relatives; race</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שְׁאֵירֵנוּ</span>; Sabb. l. c. <span dir=\"rtl\">שְׁאֵרֵינוּ</span>, v. <a href=\"#\" data-headword=\"יְדִידוּת\">יְדִידוּת</a>. Lev. R. v. 34 (expl. <span dir=\"rtl\">עכר שארו</span>, <span class=\"citation\">Prov. XI, 17</span>) <span dir=\"rtl\">זה שמגעת … את קרוביו וכ׳</span> that is he to whom joy (a festive occasion) happens, and who lets not his nearest relatives join him because they are poor; <span class=\"citation\">Yalk. Prov. 947</span>. <span class=\"citation\">Yeb. 90ᵇ</span> (ref. to <span class=\"citation\">Lev. XXI, 2</span>) <span dir=\"rtl\">שארו זו אשתו</span> his flesh (<i>sh’er</i>), this means his wife (cmp. <span class=\"citation\">Gen. II, 24</span>); Sifra Emor beg.; a. e.</div>","alt":["שְׁאֵיר"]},"29027":{"h":"שְׁאָר","r":"U00051","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>remainder, rest</i>. <span class=\"citation\">Sot. VII, 7</span> <span dir=\"rtl\">ועל ש׳ התפלה</span> (Y. ed. <span dir=\"rtl\">וש׳ תפילה</span>) and a special benediction for the remaining (general) prayer; Bab. ed. 40ᵇ <span dir=\"rtl\">והש׳ תפלה</span> and the remainder is a general prayer; ib. 41ᵃ; Y. ib. VII, end, 22ᵃ; <span class=\"citation\">Yoma 70ᵃ</span> <span dir=\"rtl\">וש׳ התפלה רינה וכ׳</span> and the remaining prayer is song, supplication &amp;c. <span class=\"citation\">B. Mets. III, 4</span> <span dir=\"rtl\">והש׳ יהא מונח וכ׳</span> and what is left must be deposited &amp;c., v. <a href=\"#\" data-headword=\"אֵלִיָּהוּ\">אֵלִיָּהוּ</a>. <span class=\"citation\">Peah IV, 3</span>; a. fr.—V. <a href=\"#\" data-headword=\"שְׁיָיר\">שְׁיָ֫יר</a>.</div>","alt":[]},"29028":{"h":"שְׁאָר ²","r":"U00052","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Gen. XLV, 7</span> (Y. <a href=\"#\" data-headword=\"שִׁיּוּרָא\">שיורא</a>; h. text <a href=\"#\" data-headword=\"שְׁאֵרִית\">שארית</a>). <span class=\"citation\">Targ. Is. X, 19</span>, sq. <span class=\"citation\">Targ. II Sam. III, 8</span> (h. text <span dir=\"rtl\">אשר</span>?); a. fr.—<span class=\"citation\">Targ. II Chr. XXXVI, 20</span> (fem.).—<span class=\"citation\">Ruth R. to III, 3</span> <span dir=\"rtl\">והיא עבדא ש׳</span> (some ed. <span dir=\"rtl\">שְׁאָרָהּ</span>); <span class=\"citation\">Yalk. ib. 604</span> <a href=\"#\" data-headword=\"שִׁירָא ²\">שְׁיָרָהּ</a>, v. <a href=\"#\" data-headword=\"נְפֵי\">נְפֵי</a>.—[<span dir=\"rtl\">שאריא</span>, <span class=\"citation\">Yalk. Jer. 321</span>, v. <a href=\"#\" data-headword=\"שְׁמָרָא\">שְׁמָרָא</a>.]</div>","alt":["שְׁאָרָא"]},"29029":{"h":"שְׁאָרוּתָא","r":"U00053","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁאָר ²\">preced.</a>) = h. <a href=\"#\" data-headword=\"מוֹתָר\">מוֹתָר</a>, <i>pre-eminence; superiority</i>. <span class=\"citation\">Targ. Koh. III, 19</span>.</div>","alt":[]},"29030":{"h":"שְׁאֵרִית","r":"U00054","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁאָרוּתָא\">preced.</a> wds.) <i>remnant</i>. Tanḥ. ed. Bub., Tol’doth 19 (ref. to <span class=\"citation\">Mic. V, 6</span>) <span dir=\"rtl\">אלו ש׳ שאמר וכ׳</span> this refers to the remnant (of the faithful) concerning whom the Lord said to Elijah &amp;c. (<span class=\"citation\">I Kings XIX, 18</span>); <span class=\"citation\">Yalk. Jud. 62</span>; <span class=\"citation\">Yalk. Mic. 553</span>.</div>","alt":[]},"29031":{"h":"שאשיתא","r":"U00055","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲשָׁשִׁיתָא\">אֲשָׁשִׁיתָא</a> a. <a href=\"#\" data-headword=\"עֲשָׁשִׁית ²\"><a href=\"#\" data-headword=\"עֲשָׁשִׁית ²\">עֲשָׁשִׁיתָא</a>.</a></div>","alt":["שאשתא"]},"29032":{"h":"שְׂאֵת","r":"U00056","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>swelling, sore</i>. Sifra Thazr., <span class=\"citation\">Neg., ch. I. Neg. I, 1</span><span class=\"citation\">Neg. I, 1</span>; a. e.</div>","alt":[]},"29033":{"h":"שָׁאתֵי","r":"U00057","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁתֵי\">שְׁתֵי</a></div>","alt":[]},"29034":{"h":"שֵׁב","r":"U00058","html":"<div class=\"sense\">, imper. of <a href=\"#\" data-headword=\"יָשַׁב\">יָשַׁב</a>.</div>","alt":[]},"29035":{"h":"שַׁב","r":"U00059","html":"<div class=\"sense\"> v. = h. <a href=\"#\" data-headword=\"שֶׁבַע\">שֶׁבַע</a>, <i>seven</i>. <span class=\"citation\">Targ. Y. Gen. XXIX, 18</span>; <span class=\"citation\">20</span>; <span class=\"citation\">27</span>; a. e.—<span class=\"citation\">Snh. 29ᵃ</span>. <span class=\"citation\">Pes. 116ᵃ</span> <span dir=\"rtl\">שב בנתיך</span> thy seven daughters. <span class=\"citation\">Ḥull. 42ᵇ</span>; a. fr.—<a href=\"#\" data-headword=\"שֵׁבְסַר\">שֵׁבְסְרֵי</a>, <a href=\"#\" data-headword=\"שֵׁבְסַר\">שֵׁבְסַר</a>, <a href=\"#\" data-headword=\"שֵׁזַרְתָּא\">שִׁ׳</a>, <span dir=\"rtl\">שֶׁ׳</span> (= <span dir=\"rtl\">שב עסר</span>) <i>seventeen</i>. <span class=\"citation\">Targ. Y. Gen. VII, 11</span>. <span class=\"citation\">Ib. XXXVII, 2</span>; a. e.—<span class=\"citation\">B. Bath. 10ᵃ</span> <span dir=\"rtl\">שֵׁיבְסַר דינרי</span> seventeen Denars. <span class=\"citation\">Taan. 28ᵇ</span> <span dir=\"rtl\">בש׳ בתמוז</span> on the seventeenth day of Tammuz; a. fr.—שְׁבִיסְרָאָה <i>the seventeenth</i>. <span class=\"citation\">Targ. I Chr. XXIV, 15</span>.</div>","alt":["שֵׁב","שֵׁיב"]},"29036":{"h":"שַׁב ²","r":"U00060","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שַׁב\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"שָׁבוּעַ\">שָׁבוּעַ</a>. <i>week</i>. Targ. II Esth. III, 7; a. fr.—<span class=\"citation\">Sabb. 156ᵃ</span> <span dir=\"rtl\">האי מאן דבחד בש׳</span> a person born on the first day of the week; <span dir=\"rtl\">בתרי בש׳</span> on Monday &amp;c. <span class=\"citation\">Bets. 16ᵃ</span> <span dir=\"rtl\">מחד שֵׁבָּיךְ לשבתך</span> from thy first day of the week begin to set aside good things for thy Sabbath; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>the seventh day, the Sabbath; day of rest</i>. <span class=\"citation\">Targ. Y. Deut. V, 14</span> <span dir=\"rtl\">שב ונייח</span> a day of rest and repose; <span class=\"citation\">Targ. Y. Ex. XX, 10</span> <span dir=\"rtl\">שבא ונ׳</span>. <span class=\"citation\">Targ. Y. Lev. XXIII, 32</span> <span dir=\"rtl\">שבא ונייחא</span>; Targ. O. <span dir=\"rtl\">ש׳ שבתא</span> (h. text <span dir=\"rtl\">שבת שבתון</span>); a. fr.—Y. Taan. I, 64ᵃ <span dir=\"rtl\">בשׁוּבָּה וכ׳</span>, v. <a href=\"#\" data-headword=\"נְיָיח\">נְיָיח</a>. <span class=\"citation\">Y. Sot. I, 16ᵈ</span> bot. <span dir=\"rtl\">כל לילי ש׳</span> every Sabbath night. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot. <span dir=\"rtl\">ערובת ש׳</span> Sabbath eve; <span dir=\"rtl\">בפוקי ש׳</span> at the exit of the Sabbath; a. fr.—<span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot. <span dir=\"rtl\">כל ארובת שובאי</span> (corr. acc.).—Pl. <span dir=\"rtl\">שַׁבִּין</span>, <a href=\"#\" data-headword=\"שַׁבְּתָא\">שַׁבַּיָּא</a>, <a href=\"#\" data-headword=\"שָׁבֵי\">שַׁבֵּי</a>. <span class=\"citation\">Targ. Is. I, 13</span> (ed. Wil. <span dir=\"rtl\">שַׁבְּאִין</span>). <span class=\"citation\">Targ. I Chr. XXIII, 31</span>; a. fr.—<span class=\"citation\">Sabb. 119ᵃ</span> יוסף מוקיר שבי Joseph, the honorer of the Sabbaths; a. e.</div>","alt":["שַׁבָּא","שׁוּבָּא"]},"29037":{"h":"שְׁבָא","r":"U00061","html":"<div class=\"sense\"><i>to capture</i>, v. <a href=\"#\" data-headword=\"שְׁבֵי\">שְׁבֵי</a>.</div>","alt":[]},"29038":{"h":"שְׁבָא ²","r":"U00062","html":"<div class=\"sense\"> (b. h.) pr. n. (<i>the kingdom of</i>) <i>Sheba</i>, in Arabia. Targ. II Esth. I, 2; a. e.—<span class=\"citation\">B. Bath. 15ᵇ</span>, v. <a href=\"#\" data-headword=\"מַלְכָּה\">מַלְכָּה</a>. Ib.; <span class=\"citation\">Y. Sot. V, end, 20ᵈ</span> <span dir=\"rtl\">בימי מלכת ש׳ היה</span> (Job) lived in the days of the queen of Sheba; <span class=\"citation\">Gen. R. s. 57</span>; a. e.</div>","alt":[]},"29039":{"h":"שַׁבָּאָה","r":"U00063","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = next w.—Pl. <a href=\"#\" data-headword=\"שַׁבַּאי\">שַׁבָּאֵי</a>, <a href=\"#\" data-headword=\"שַׁבּוֹיָא\">שַׁבּוֹיֵי</a>. Lam. R. introd. (R. Joḥ. 1) Moses said to them <span dir=\"rtl\">ש׳ אי בחייכון אתון קטולי וכ׳</span> you captors, oh, by your own lives, (I adjure you,) do not commit merciless slaughter. <span class=\"citation\">Keth. 23ᵃ</span> <span dir=\"rtl\">אוקמן לשַׁבּוֹיִינְהִי וכ׳</span> (Rashi <span dir=\"rtl\">לשבוייהי</span></div>","alt":["שַׁבּוֹיָא"]},"29040":{"h":"שַׁבַּאי","r":"U00064","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁבָה\">שָׁבָה</a>) <i>captor</i>, <i>guardsman of captives</i>. <span class=\"citation\">Snh. 104ᵃ</span>, sq. <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">נתעלל בה ש׳ וכ׳</span> the captor abused her the whole night; <span class=\"citation\">Yalk. Jer. 276</span>. Tanḥ. ed. Bub. <span class=\"citation\">B’shall. 4</span> <span dir=\"rtl\">נטל את השַׁבַּאיי וכ׳</span> he took (his son’s) captor and put him on the rack, <span class=\"citation\">Yalk. Ex. 225</span>; a. e.—Pl. <span dir=\"rtl\">שַׁבָּאִים</span>, <span dir=\"rtl\">שַׁבְּאִין</span>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 8</span> <span dir=\"rtl\">באו ש׳ ושבו וכ׳</span> captors came and led his son away; a. e.</div>","alt":[]},"29041":{"h":"שָׁבַב","r":"U00065","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">שִׁיבֵּב</span> (cmp. Arab. <i>sabba</i> a. deriv.) <i>to chip, chisel</i>. Koh. R. introd. <span dir=\"rtl\">ושִׁבְּבָהּ</span>, v. <a href=\"#\" data-headword=\"סָדַק\">סָדַק</a>.—Trnsf. <i>to chastise, discipline</i>. <span class=\"citation\">Sot. 12ᵃ</span> (play on <span dir=\"rtl\">שובב</span> <span class=\"citation\">I Chr. II, 18</span>, as an Agadic surname of Caleb) <span dir=\"rtl\">ששי׳ את יצרו</span> he trained his inclination; (Rashi: <span dir=\"rtl\">ששי׳ את עצמו</span>, denom. of <span dir=\"rtl\">שׁוֹבָב</span>, <i>he turned himself away</i> from the rest of the spies); Yalk. Chr. 1074 <span dir=\"rtl\">ששבב את יצרו</span>; <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ששי׳ את עצמו</span>. <span class=\"citation\">Sabb. 87ᵃ</span> (play on <span dir=\"rtl\">וישב</span>, <span class=\"citation\">Ex. XIX, 8</span>) <span dir=\"rtl\">דברים שמְשַׁבְּבִין דעתו של אדם</span> words which chasten the mind of man (threats of punishment), opp. <span dir=\"rtl\">מושכין</span>; (Rashi: things which <i>repel</i> the mind, v. supra).</div>","alt":[]},"29042":{"h":"שֵׁבָבָא","r":"U00066","html":"<div class=\"sense\">, v. sub. <a href=\"#\" data-headword=\"שִׁבְּבִין\">שֵׁיב׳</a>.</div>","alt":["שֵׁבְבוּתָא"]},"29043":{"h":"שִׁבְּבִין","r":"U00067","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שֵׁבָבָא\">preced. art.</a>; cmp. <a href=\"#\" data-headword=\"שִׁיבָּא\">שִׁיבָּא</a>, a. <a href=\"#\" data-headword=\"שְׁבִיבָא\">שְׁבִיבָא</a>) [<i>chips</i> or <i>sparks</i>,] name of a certain feminine <i>ornament</i>. <span class=\"citation\">Targ. O. Ex. XXXV, 22</span> <a href=\"#\" data-headword=\"שִׁבְּבִין\">שִׁבְּבִין</a> or <a href=\"#\" data-headword=\"שִׁבְּבִין\">שִׁבְבִין</a> Ms. (ed. <span dir=\"rtl\">שבכין</span>; Y. <a href=\"#\" data-headword=\"שִׁיוְוִין\">שֵׁיוְוִין</a>, <a href=\"#\" data-headword=\"שַׁוְיָא\">שִׁיוְ׳</a>; h. text <a href=\"#\" data-headword=\"נֶזֶם\">נזם</a>). <span class=\"citation\">Targ. O. Num. XXXI, 50</span> Ms. (ed. <span dir=\"rtl\">שבכין</span>; h. text <a href=\"#\" data-headword=\"צָמִיד\">צמיד</a>). [V. Berl. Targ. O. II, p. 31; p. 48.]</div>","alt":["שִׁבְ׳","שֵׁיבְ׳"]},"29044":{"h":"שָׁבָה","r":"U00068","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שבי\">שבי</a></div>","alt":[]},"29045":{"h":"שִׁבְהוֹר","r":"U00069","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"שִׁיבְהוֹר\">שִׁבְהוֹרְתָּא</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a> f. (<a href=\"#\" data-headword=\"שַׁבְהַר\">next w.</a>) <i>splendor, glory</i>. <span class=\"citation\">Targ. Y. Deut. XXVI, 19</span>. <span class=\"citation\">Targ. Ps. VIII, 6</span>. <span class=\"citation\">Targ. Prov. II, 7</span> (ed. Lag. <a href=\"#\" data-headword=\"סבהיי\">סבהיי</a>, read: <span dir=\"rtl\">סבהור</span>). <span class=\"citation\">Targ. Ps. XCVI, 9</span> <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁבְהוֹרַת</a> constr.; a. fr.—Pl. constr. <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁבְהוֹרֵי</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>. <span class=\"citation\">Ib. CX, 3</span>. <span class=\"citation\">Targ. I Chr. XVI, 29</span>.</div>","alt":["שִׁבְהוֹרָא","שִׁי׳"]},"29046":{"h":"שַׁבְהַר","r":"U00070","html":"<div class=\"sense\"> (<i>Shafel</i> of <span dir=\"rtl\">בהר</span>) <i>to brighten, glorify</i>. <span class=\"citation\">Targ. Ps. CXLIX, 4</span> Ms. (ed. <span dir=\"rtl\">ישבחו</span>, corr. acc.; h. text <span dir=\"rtl\">יפאר</span>).</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּבְהַר</b> <div class=\"sense\"><b>1)</b> <i>to be brightened</i>. <span class=\"citation\">Targ. Y. I Ex. XXXIV, 29</span> (Y. II <span dir=\"rtl\">שבחו</span>, ed. Ven. <span dir=\"rtl\">שברו</span>, corr. acc.). <span class=\"citation\">Targ. Job XXVI, 13</span>.</div><div class=\"sense\"><b>—2)</b> <i>to glory, boast</i>. <span class=\"citation\">Targ. Prov. XXV, 6</span>. <span class=\"citation\">Ib. 14</span>. <span class=\"citation\">Ib. XXVII, 1</span>.</div></div>","alt":[]},"29047":{"h":"שְׁבוּאֵל","r":"U00071","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shebuel</i>, proposed as a secondary substitute (<span dir=\"rtl\">כִּינּוּי כִּינּוּי</span>) for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a>. <span class=\"citation\">Ned. 10ᵇ</span> <span dir=\"rtl\">כינויי כינויין דשבועה היכי דמי ש׳ וכ׳</span> what are secondary substitutes for <i>sh’bu‘ah?</i> Like Sh’buel, Sh’buthiel, Sh’ḳuḳel; <span dir=\"rtl\">ש׳ ש׳ … משמע וכ׳</span> but could Sh’buel be used, as it may represent the proper noun Shebuel ben Gershom? Say Sh’bubel.</div>","alt":[]},"29048":{"h":"קְרֵיבָה","r":"S02034","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרֵב\">קָרַב</a>) <i>coming near, use of the root</i> <a href=\"#\" data-headword=\"קָרֵב\">קָרַב</a>. <span class=\"citation\">Gen. R. s. 96</span> (ref. to <span class=\"citation\">Gen. XLVII, 29</span>) <span dir=\"rtl\">כל מי שנ׳ בו ק׳ למות וכ׳</span> he of whom the expression ‘come near to die’ is used, has not reached the age of his fathers; <span dir=\"rtl\">דוד כתיב בו ק׳ וכ׳</span> of David the expression <span dir=\"rtl\">קרב</span> is used (<span class=\"citation\">I Kings II, 1</span>) &amp;c.; <span class=\"citation\">Yalk. Kings 168</span>. <span class=\"citation\">Snh. 3ᵇ</span> (ref. to <span class=\"citation\">Ex. XXII, 7</span> <span dir=\"rtl\">ונקרב</span>) <span dir=\"rtl\">משעת ק׳ שלשה</span> from the time of the approach (before court) there must be three judges. <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">בזה ק׳ ובזה ק׳</span> coming near is mentioned in connection with the tribe of Judah (<span class=\"citation\">Ps. LXV, 5</span>) and with the priestly tribe (<span class=\"citation\">Ex. XXVIII</span>, . <span class=\"citation\">Y. Snh. VII, 25ᵃ</span> <span dir=\"rtl\">מכיון דכתיב ק׳ ק׳ וכ׳</span> since with regard to illicit connections the word <span dir=\"rtl\">קרב</span> is used &amp;c. <span class=\"citation\">Sabb. 104ᵇ</span> <span dir=\"rtl\">מחוסר ק׳</span>, <span dir=\"rtl\">מחוסר מעשה דק׳</span> it lacks being brought together (joined into one word); a. fr.—<span class=\"citation\">Y. Hor. II, 46ᵈ</span> <span dir=\"rtl\">ק׳ פרישה</span> the root <span dir=\"rtl\">קרב</span> may also mean separation (coming near one’s self, ref. to <span class=\"citation\">Is. LXV, 5</span>).—Pl. <a href=\"#\" data-headword=\"קְרֵיבוּת\">קְרֵיבוֹת</a>. <span class=\"citation\">Pes. 118ᵇ</span> (ref. to <span class=\"citation\">Ps. LXVIII, 31</span>) <span dir=\"rtl\">מי גרם … ק׳ שהיו חפצין בהן</span> what caused the dispersion of Israel among the nations? The approaches (to the nations) which they desired; <span class=\"citation\">Yalk. Ps. 800</span> <a href=\"#\" data-headword=\"קְרֵבוּת\">קְרֵבוֹת</a> (or <span dir=\"rtl\">קְרָבוֹת</span>). <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> top, v. <a href=\"#\" data-headword=\"קָרוֹב I\"><span dir=\"rtl\">קָרוֹב</span> I</a>.</div>","alt":[]},"29049":{"h":"קָרִיבוֹי","r":"S02035","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָרוֹב II\"><span dir=\"rtl\">קָרוֹב</span> II</a></div>","alt":[]},"29050":{"h":"קְרֵיבוּת","r":"S02036","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרֵב\">קָרֵב</a>) <i>friendship, relationship</i>. <span class=\"citation\">Ex. R. s. 5</span>, a. e., v. <a href=\"#\" data-headword=\"נְשִׁיקָה\">נְשִׁיקָה</a>.</div>","alt":["קְרֵבוּת"]},"29051":{"h":"קְרֵיבוּתָא","r":"S02037","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"קְרֵיבָה\">קְרֵיבָה</a>. <span class=\"citation\">Targ. Y. Deut. XXXI, 14</span>.</div>","alt":[]},"29052":{"h":"קָרִיד","r":"S02038","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַד\">קרד</a>; cmp. <a href=\"#\" data-headword=\"גְּרִיד\">גְּרִיד</a>) (<i>a pot</i>) <i>covered with a crust</i> formed of hardened sediments. <span class=\"citation\">Ab. Zar. 76ᵃ</span> <span dir=\"rtl\">האי ק׳ והאי לא ק׳</span> (Ms. M. <a href=\"#\" data-headword=\"קְרַר ²\">קריר</a>, cmp. <a href=\"#\" data-headword=\"גָּרַד\">גָּרַד</a> a. <a href=\"#\" data-headword=\"גָּרַר I\">גָּרַר</a>) the one (a vessel taken from gentiles) has crusty accretions, the other (a sacred vessel) has none.</div>","alt":[]},"29053":{"h":"קִרְיָה I","r":"S02039","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> a. II) <i>town, settlement, fort.</i> Lam. R. introd. (R. Naḥman) (ref. to <span class=\"citation\">Is. XXIX, 1</span>) <span dir=\"rtl\">ק׳ שחנה וכ׳</span> the town in which David put up his camp; <span dir=\"rtl\">ק׳ דלא חניא וכ׳</span> the place where &amp;c., v. <a href=\"#\" data-headword=\"חַנְיָא\">חַנְיָא</a>. Ib. <span dir=\"rtl\">ק׳ שעשה וכ׳</span>, v. <a href=\"#\" data-headword=\"קְסִרְקִיטוֹן\">קְסִרְקִיטוֹן</a>; <span class=\"citation\">Yalk. Is. 302</span>. Tanḥ. K’dosh. 9 <span dir=\"rtl\">מעשה היה בקִרְיָתֵנוּ</span> it happened in our place; <span class=\"citation\">Lev. R. s. 24</span>, beg. <span dir=\"rtl\">בקרתני</span> (corr. acc.; <span class=\"citation\">Yalk. Ps. 680</span> <span dir=\"rtl\">בעירנו</span>).—Pl. <span dir=\"rtl\">קִרְיוֹת</span>. <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">מעשה … ק׳ וכ׳</span> it happened with (representatives of) 24 townships belonging to the house of Rabbi, that they were assembled to proclaim an intercalation at Lydda.—[<span class=\"citation\">Y. B. Bath. IX, 17ᵃ</span> <span dir=\"rtl\">קריות</span>, read <span dir=\"rtl\">קרנות</span>, v. <a href=\"#\" data-headword=\"קָרוֹן\">קָרוֹן</a>.]</div>","alt":[]},"29054":{"h":"קִרְיָה II","r":"S02040","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= <a href=\"#\" data-headword=\"קְרִיאָה\">קִרְיָאָה</a>, v. <a href=\"#\" data-headword=\"קוּרְיָיאָה\">קוּרְיָיאָה</a> a. <a href=\"#\" data-headword=\"קִרְיָיא\"><a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a>)</a><i>townsman, villager</i>. <span class=\"citation\">Gen. R. s. 18</span> (ref. to <span class=\"citation\">Gen. II, 22</span>) <span dir=\"rtl\">טבוי לק׳ דמלכא שושביניה</span> lucky is the townsman whose groomsman is the king (‘Rashi’ <span dir=\"rtl\">טבות לקרתא דמלכא שושבינה</span>); Yalk. ib. 24 <span dir=\"rtl\">טובוי לקי׳</span>.</div>","alt":["קִירְ׳"]},"29055":{"h":"קְרִיָּה","r":"S02041","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרִיאָה\">קְרִיאָה</a></div>","alt":[]},"29056":{"h":"*קֵרְיוֹן","r":"S02042","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κηρίων) <i>wax-candle.</i>—Pl. <span dir=\"rtl\">קֵרְיוֹנִין</span>. <span class=\"citation\">Ex. R. s. 36</span> (ed. <a href=\"#\" data-headword=\"קרוינין\">קרוינין</a>, <a href=\"#\" data-headword=\"קרינין\">קרינין</a>, corr. acc.), v. <a href=\"#\" data-headword=\"סִיבַק\">סִיבַק</a>.</div>","alt":[]},"29057":{"h":"קריוניוס","r":"S02043","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְיָינוֹס\">קִרְיָינוֹס</a></div>","alt":[]},"29058":{"h":"קִרְיוֹסִי","r":"S02044","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִירְיוֹסִים\">קִירְיוֹסִי</a></div>","alt":["קִרְיוֹסִין"]},"29059":{"h":"קִרְיוּתָא","r":"S02045","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קָרֶה\">קָרֶה</a> or <a href=\"#\" data-headword=\"קְרִי ²\">קֶרִי</a>, <i>accident;</i> קִרְיוּת הִרְהוּר <i>effusio seminis in consequence of heated fancy or dream</i>. <span class=\"citation\">Targ. Y. Deut. XXIII, 11</span>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 3</span>.</div>","alt":["קִי׳"]},"29060":{"h":"קְרֵיחַ","r":"S02046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a> ch.</div>","alt":[]},"29061":{"h":"קְרִיחָה","r":"S02047","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַח\">קָרַח</a>) <i>making bald, baldness.</i> Sifra Emor Par. 1, ch. I, v. <a href=\"#\" data-headword=\"קָרְחָה I\">קָרְחָה</a>. <span class=\"citation\">Y. Sabb. XX, end, 17ᵈ</span>, v. <a href=\"#\" data-headword=\"קְרַח I\"><span dir=\"rtl\">קְרַח</span> I</a>.—Pl. <span dir=\"rtl\">קְרִיחוֹת</span>. <span class=\"citation\">Macc. 20ᵃ</span>, v. <a href=\"#\" data-headword=\"קָרַח\">קָרַח</a>.</div>","alt":[]},"29062":{"h":"קַרַיי","r":"S02048","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרָיָיא\">קרָיָיא</a></div>","alt":[]},"29063":{"h":"קִרְיָיא","r":"S02049","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קִרְיָה I\">קִרְיָה</a>, <i>town, settlement, village</i>. Targ. II Esth. IV, 1. Ib. IX, 28. <span class=\"citation\">Targ. Prov. XVIII, 19</span>; a. fr.—<span class=\"citation\">Y. Ber. II, 5ᵃ</span> top <span dir=\"rtl\">הוה עייל ק׳ ונפיק ק׳</span> (not <span dir=\"rtl\">ונפקא</span>) he went from place to place; <span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">הוה עליל לק׳ ונפיק לק׳</span>. <span class=\"citation\">Ib. to V, 14</span> <span dir=\"rtl\">למזבן עיבור מן ק׳</span> to buy up the grain of the place; a. e.—Pl. <a href=\"#\" data-headword=\"קַרְיָין\">קִרְיָין</a>, <a href=\"#\" data-headword=\"קוֹרְטוֹר\">קוּ׳</a>, <span dir=\"rtl\">קִרְיָיתָא קוֹ׳</span>, <a href=\"#\" data-headword=\"קִרְיְתָא\">קִרְיָתָא</a>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Targ. Y. II, Num. XXXV, 2</span> (not <span dir=\"rtl\">קִרְיָת</span>). <span class=\"citation\">Targ. Y. ib. 7</span>; <span class=\"citation\">8</span>; a. fr.—Constr. <span dir=\"rtl\">קוּרְיֵי</span>, <a href=\"#\" data-headword=\"קוּלְיָא\">קוֹ׳</a>. <span class=\"citation\">Targ. Y. ib. XXXII, 26</span>; <span class=\"citation\">33</span>; <span class=\"citation\">36</span>; a. e., v. <a href=\"#\" data-headword=\"קִרְוָא\">קִרְוָא</a>.—Y. Ḥag. I, 76ᶜ ר׳ יודה … בק׳ דארעא וכ׳ R. Judah, the Nasi sent forth … to visit the small places of Palestine and arrange for them primary teachers &amp;c.; Lam. R. introd. (R. Abba 2). <span class=\"citation\">Succ. 44ᵇ</span> ק׳ אית לי I own villages (or <i>sing.</i>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בני ק׳</span> the villagers. <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> <span dir=\"rtl\">דנפקין וסחרין … קוריין וכ׳</span> who go out trading in four or five places (during the day) and sleep in their own homes; a. e.</div>","alt":["קִרְיָיה","קוֹ׳","קוּ׳","קִרְיְיתָא","קִרְיְתָא","קי׳"]},"29064":{"h":"קַרָיָיא","r":"S02050","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קַרָא\">קַרָא</a> <i>Biblical scholar, Bible teacher</i>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">ק׳ ותניי וכ׳</span> a Biblical scholar, a Mishnah student, poet, and preacher (v. <a href=\"#\" data-headword=\"קָרוֹב II\"><span dir=\"rtl\">קָרוֹב</span> II</a>); <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">קְרָאוֹי ותנויי</span>; Pesik. Ul’kaḥ. p. 179ᵃ <span dir=\"rtl\">קָרוֹי ותנוי</span>.</div>","alt":["קַרַיי"]},"29065":{"h":"קַרְיָיא","r":"S02051","html":"<div class=\"sense\"> c. = <a href=\"#\" data-headword=\"קְרֵי I\">קְרָא</a>, <i>Scriptures; Bible verse</i>. <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> bot. <span dir=\"rtl\">יכיל … ק׳ מן פומי</span> I can write the entire Scriptures from memory; <span dir=\"rtl\">יכיל … ק׳ בתרין מניי</span> I can write the whole Bible at a cost of two Manehs; <span dir=\"rtl\">וכתב כל ק׳ על וכ׳</span> and wrote the whole Bible on their hides. <span class=\"citation\">Y. Ber. II, 4ᵈ</span> bot. <span dir=\"rtl\">כמא דאישתעי ק׳ כך וכ׳</span> the phraseology of the Bible must be adopted in Talmudic diction; Y. Snh. VIII, 25ᶜ. <span class=\"citation\">Y. Peah I, 15ᵈ</span> bot. <span dir=\"rtl\">שמע … מן הדין ק׳</span> understood (derived) all this from the following verse. <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">אי מן הדא ק׳ לית וכ׳</span> if you mean to prove from this verse, you cannot derive from it anything; a. v. fr.—Pl. <span dir=\"rtl\">קָרַיָּיא</span> (v. <a href=\"#\" data-headword=\"קְרָא II\"><span dir=\"rtl\">קְרָא</span> II</a>), <a href=\"#\" data-headword=\"קַרְיָין\">קַרְיָין</a>. <span class=\"citation\">Y. Ber. I, 3ᵇ</span> <span dir=\"rtl\">הא רב&quot;ה מקיימין תרין ק׳</span> (not <span dir=\"rtl\">מקימון</span>) with this interpretation of Beth Hillel the two texts are harmonized. <span class=\"citation\">Koh. R. to III, 14</span> <span dir=\"rtl\">היאך מרי … אילין ק׳ וכ׳</span> how do you explain these verses?, and he delivered them to him; <span dir=\"rtl\">ואילין ק׳ מקרי ליה</span> (not <span dir=\"rtl\">מקרתן</span>) and these are the verses he interpreted to him. Lev. R. l. c. <span dir=\"rtl\">אית ליה ק׳ סגיין</span> he has many Biblical verses to prove his opinion; a. fr.</div>","alt":["קַרְיָא","קַרְיָיה"]},"29066":{"h":"קְרִיָּיה","r":"S02052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרִיאָה\">קְרִיאָה</a></div>","alt":[]},"29067":{"h":"קַרְיָיה","r":"S02053","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְיָיא\">קַרְיָיא</a></div>","alt":[]},"29068":{"h":"קִרְיָיה","r":"S02054","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְיָה I\">קִרְיָה</a></div>","alt":[]},"29069":{"h":"קרייון","r":"S02055","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרַמְיוֹן\">קְרַמְיוֹן</a></div>","alt":[]},"29070":{"h":"קַרְיָין","r":"S02056","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"קַרְיָיא\">קַרְיָיא</a>.—[Targ. II Esth. VI, 10, v. <a href=\"#\" data-headword=\"*קְרַק\">קְרַק</a>.]</div>","alt":[]},"29071":{"h":"קַרְיָינָא","r":"S02057","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרֵי I) </div><div class=\"sense\"><b>1)</b> <i>one able to read in the Bible</i>. <span class=\"citation\">Kidd. 49ᵃ</span> <span dir=\"rtl\">על מנת שאני ק׳ כיון וכ׳</span> if one betrothes a woman with the condition ‘that I am a <i>ḳaryana’</i>, she is betrothed as soon as he can read three verses in the synagogue. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והני מילי דאמר ק׳ וכ׳</span> this is the case only when he says <i>ḳaryana</i>, but if he says <i>ḳara</i> &amp;c., v. <a href=\"#\" data-headword=\"קַרָא\">קַרָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>one who dictates a letter</i>. <span class=\"citation\">Snh. 82ᵃ</span>, a. fr., v. <a href=\"#\" data-headword=\"פַּרְוַונְקָא\">פַּרְוַונְקָא</a>.</div>","alt":["קַרְיָנָא"]},"29072":{"h":"קִרְיָינוֹס","r":"S02058","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Ḳiryanos</i> (prob. = <a href=\"#\" data-headword=\"קַרְנַיִם\">קַרְנַיִם</a>, v. Grætz, Gesch. d. <span class=\"citation\">Jud. II, 2</span>, p. 456). Pesik. Vayhi, p. 66ᵃ; <span class=\"citation\">Lev. R. s. 17</span>; <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">כ׳ קרנים</span>; <span class=\"citation\">Ruth R. to I, 5</span> <a href=\"#\" data-headword=\"קִרְיָנוֹס\">קִרְיָנוֹס</a>. <span class=\"citation\">Esth. R. to VI, 10</span> <span dir=\"rtl\">כ׳ קריוניוס</span> (corr. acc.); <span class=\"citation\">Meg. 16ᵃ</span> קרינוס Ms. M. (ed. <a href=\"#\" data-headword=\"קרצום\">קרצום</a>, corr. acc.); Pesik. Haʿomer, p. 72ᵇ; <span class=\"citation\">Lev. R. s. 28</span>; <span class=\"citation\">Yalk. ib. 643</span> <span dir=\"rtl\">קריטם</span> (corr. acc.); <span class=\"citation\">Yalk. Esth. 1058</span> <a href=\"#\" data-headword=\"קורינוס\">קורינוס</a> (corr. acc.).</div>","alt":["כְּפַר קִ׳"]},"29073":{"h":"קריית","r":"S02059","html":"<div class=\"sense\">, <span class=\"citation\">Y. B. Bath. II, 13ᵇ</span> bot. <span dir=\"rtl\">מכוח ק׳</span>, prob. to be read: <span dir=\"rtl\">מכוח קְרָנוֹת</span> from the shock of passing vehicles.</div>","alt":[]},"29074":{"h":"קִרְיְיתָא","r":"S02060","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a></div>","alt":[]},"29075":{"h":"קְרִימָה","r":"S02061","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַם\">קָרַם</a>) <i>formation of a light crust</i> on dough in baking. <span class=\"citation\">Y. Ḥall. II, beg. 58ᵇ</span>; ib. III, 59ᵇ top.</div>","alt":[]},"29076":{"h":"קרימיון","r":"S02062","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרַמְיוֹן\">קְרַמְיוֹן</a></div>","alt":[]},"29077":{"h":"קַרְיָנָא","r":"S02063","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְיָינָא\">קַרְיָינָא</a></div>","alt":[]},"29078":{"h":"קְרִינָא","r":"S02064","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάρινον, κάρυνον, carenum; cmp., however, Assyr. karanûv, Schr. KAT<sup>2</sup>, p. 560, kurunnu, Del. Assyr. Handw., p. 355) name of <i>a sweet wine</i>. <span class=\"citation\">Ab. Zar. 30ᵃ</span> ק׳ חמרא חליא וכ׳ <i>ḳ’rina</i> is a sweet (weak) wine that comes from ʿAsia (v. <a href=\"#\" data-headword=\"עַסְיָא\">עַסְיָא</a>); Y. ib. II, 41ᵃ</div>","alt":[]},"29079":{"h":"קְרִינוֹן","r":"S02065","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κρίνον) (<i>white</i>) <i>lily</i>. Y. Kil. I, end, 30ᵃ (not <a href=\"#\" data-headword=\"קרינטון\">קרינטון</a>), expl. <span dir=\"rtl\">שושנת המלך</span>, v. <a href=\"#\" data-headword=\"שׁוֹשַׁנָּה\">שׁוֹשַׁנָּה</a> (v. Löw, Pfl. p. 380).</div>","alt":[]},"29080":{"h":"קִרְיָנוֹס","r":"S02066","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְיָינוֹס\">קִרְיָינוֹס</a></div>","alt":[]},"29081":{"h":"קרינטון","r":"S02067","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרִינוֹן\">קְרִינוֹן</a></div>","alt":[]},"29082":{"h":"קרינין","r":"S02068","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 36</span>, v. <a href=\"#\" data-headword=\"*קֵרְיוֹן\">קֵרְיוֹן</a></div>","alt":[]},"29083":{"h":"קריסטאלי","r":"S02069","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Esth. 1046</span>, a gloss to <a href=\"#\" data-headword=\"זְכוּכִית\">זכוכית</a>, <i>crystal</i>.</div>","alt":[]},"29084":{"h":"קריסטור","r":"S02070","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְוִיסְטוֹר\">קְוִיסְטוֹר</a></div>","alt":[]},"29085":{"h":"קְרִיסְטַמְלִין","r":"S02071","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרוּסְטְמִיל\">קְרוּסְטְמִיל</a></div>","alt":[]},"29086":{"h":"קְרִיסְפָּא","r":"S02072","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳ’rispa</i>, v. <a href=\"#\" data-headword=\"כְּרִיסְפָּא\">כְּרִיסְפָּא</a>. <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> (Var. <a href=\"#\" data-headword=\"קְרִיסְפְּדָא\">קְרִיסְפְּדַאי</a>). Y. R. Hash. I, 57ᵃ bot <span dir=\"rtl\">קרוס׳</span> ed. Krot. Ib. II, 58ᵇ top; Y. Snh. I, 18ᶜ bot. <a href=\"#\" data-headword=\"קְרִיסְפְּדָא\">קְרִיסְפְּדָא</a>. <span class=\"citation\">Y. Shek. VII, 50ᶜ</span>. <span class=\"citation\">Y. Yeb. I, 2ᶜ</span> top <a href=\"#\" data-headword=\"קְרִיסְפְּדָא\">קְרִיסְפִּי</a>. <span class=\"citation\">Y. Snh. III, 21ᵇ</span> bot. Y. M. Kat. III, end, 83ᵈ <a href=\"#\" data-headword=\"קְרוּסְפָּא\">קְרוּסְפִּי</a>.</div>","alt":[]},"29087":{"h":"קְרִיסְפְּדָא","r":"S02073","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרִיסְפָּא\">preced.</a></div>","alt":["קְרִיסְפְּדַאי","קְרִיסְפִּי"]},"29088":{"h":"קְרִיעָה","r":"S02074","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַע\">קָרַע</a>) <i>rending, tearing</i>. <span class=\"citation\">Yoma 80ᵃ</span> <span dir=\"rtl\">בן … טעון ק׳</span> an animal taken alive out of the slaughtered mother’s womb (v. <a href=\"#\" data-headword=\"פְּקוּעָה\">פְּקוּעָה</a>) requires ripping (to let the blood escape). <span class=\"citation\">Y. Ḥag. I, 76ᵃ</span> <span dir=\"rtl\">ק׳ היא שגרמה</span> the operation (on the <a href=\"#\" data-headword=\"טוּמְטוּם\">טוּמְטוֹם</a>) caused him to be legally recognized as a male. <span class=\"citation\">Y. Ber. I, 3ᵈ</span> bot., a. fr. <span dir=\"rtl\">קְרִיעַת ים סוף</span> the division of the Red Sea for the passage of the Israelites; a. fr.—Esp. <i>the rending of the garment in mourning</i>. M. K. 22ᵇ <span dir=\"rtl\">כל ק׳ שאינו מבדיל וכ׳</span> a rending whereby one fails to sever the border (v. <a href=\"#\" data-headword=\"קָמָה\">קָמָה</a>) is a meaningless act; a. fr.—Pl. <span dir=\"rtl\">קְרִיעוֹת</span>. Ib. 26ᵃ <span dir=\"rtl\">חייב לקרוע שתי ק׳</span> must make two rents; a. e.</div>","alt":[]},"29089":{"h":"קְרִיץ","r":"S02075","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַץ I\">קרץ</a>; cmp. <a href=\"#\" data-headword=\"קְרַע\">קְרַע</a>) [<i>breaking through</i>,] <i>dawn, early morning</i>. <span class=\"citation\">Targ. Job XXXVIII, 12</span> (some ed. <a href=\"#\" data-headword=\"קְרִיצְתָּא\">קריצתא</a>, <a href=\"#\" data-headword=\"קְרִצְתָּא\">קרצתא</a>, corr. acc.). <span class=\"citation\">Targ. Ps. LVII, 9</span>; a. fr.—V. <a href=\"#\" data-headword=\"קְרִיצְתָּא\">קְרִיצְתָּא</a>.</div>","alt":[]},"29090":{"h":"קְרִיצָה","r":"S02076","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַץ\">קָרַץ</a>) <i>compressing the lips, gesture</i> of anger, scorn &amp;c.—Pl. <span dir=\"rtl\">קְרִיצוֹת</span>. <span class=\"citation\">Yeb. 108ᵇ</span> <span dir=\"rtl\">מכרת ברמיזותיו וקְרִיצוֹתָיו</span> she is familiar with his hints and gestures (by which she may be influenced). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קְרִיצוֹתֵיהֶם ורמיזותיהם</span> their gestures and hints.</div>","alt":[]},"29091":{"h":"קְרִיצְתָּא","r":"S02077","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"קְרִיץ\">קְרִיץ</a>. <span class=\"citation\">Targ. Ps. XXII, 1</span>. <span class=\"citation\">Ib. L, 12</span>. <span class=\"citation\">Targ. Y. Num. XIV, 44</span>; a. e.—[<span class=\"citation\">Targ. Job XXXVIII, 12</span>, v. <a href=\"#\" data-headword=\"קְרִיץ\">קְרִיץ</a>.]—Y. Ber. I, 2ᶜ; <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; <span class=\"citation\">Cant. R. to VI, 10</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a> at day-break. <span class=\"citation\">Y. Bets. V, 63ᵃ</span> bot. <span dir=\"rtl\">בק׳ דשובתא</span> early on a Sabbath morning; a. e.</div>","alt":["קְרִיצְתָּה","קְרִצְ׳"]},"29092":{"h":"קריקם","r":"S02078","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹלְקָס\">קוֹלְקָס</a></div>","alt":["קריקס"]},"29093":{"h":"קָרִיר I","r":"S02079","html":"<div class=\"sense\"><i>crusty</i>, v. <a href=\"#\" data-headword=\"קָרִיד\">קָרִיד</a>.</div>","alt":[]},"29094":{"h":"קָרִיר II","r":"S02080","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קְרַר II) </div><div class=\"sense\"><b>1)</b> <i>cool, cold</i>. <span class=\"citation\">Targ. Nah. III, 17</span>.—<span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">בארבע … טולא ק׳ וכ׳</span> at four hours of the day the shade is cool, and the sun hot. <span class=\"citation\">Sabb. 53ᵃ</span> (prov.) <span dir=\"rtl\">חמרא … ק׳ ליה</span> the ass feels cold even at the solstice of Tammuz. <span class=\"citation\">B. Bath. 24ᵇ</span>, a. e. <span dir=\"rtl\">ולא ק׳</span>, v. <a href=\"#\" data-headword=\"חַמִּים\">חַמִּים</a>. <span class=\"citation\">Gen. R. s. 99</span>, v. <a href=\"#\" data-headword=\"עִילִיתָא II\"><span dir=\"rtl\">עִילִיתָא</span> II</a>; a. e.—[<span class=\"citation\">Zeb. 79ᵇ</span>; <span class=\"citation\">98ᵃ</span>, v. <a href=\"#\" data-headword=\"קָדַר I\"><span dir=\"rtl\">קְדַר</span> I</a>.]—Pl. <span dir=\"rtl\">קָרִירֵי</span>. <span class=\"citation\">Targ. Prov. XXV, 25</span>.—<span class=\"citation\">Nidd. 36ᵇ</span> <span dir=\"rtl\">עיילוה … אפקוה מק׳</span> they got him hot to relieve him from chills; <span dir=\"rtl\">עיילוה בק׳ וכ׳</span> they got him cold to relieve him from fever. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">מק׳ ק׳ דחיטי</span> from eating very cold wheat dishes; a. e.—Esp. <span dir=\"rtl\">קרירי</span> (<span dir=\"rtl\">מיא</span>) <i>cold water</i>. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">לא ק׳ וכ׳</span> neither cold nor hot, but tepid. <span class=\"citation\">Ḥull. 46ᵇ</span>, v. <a href=\"#\" data-headword=\"טְרַשׁ I\"><span dir=\"rtl\">טְרַשׁ</span> I</a>. <span class=\"citation\">Sabb. 55ᵃ</span>, v. <a href=\"#\" data-headword=\"חַמִּים\">חַמִּים</a>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"קוֹרָה IV\"><span dir=\"rtl\">קוֹרָה</span> I</a>) <i>satisfaction, pleasure</i>. <span class=\"citation\">Gen. R. s. 47</span> <span dir=\"rtl\">לא תמלי … קריר וכ׳</span> fill not my spirit with too much pleasure (awaken not in me too high aspirations), Oh that thou wouldst not withdraw from me the present grant!; <span class=\"citation\">Yalk. ib. 82</span>.</div>","alt":["קְרִירָא","קְרִירְתָּא"]},"29095":{"h":"קְרִירוּתָא","r":"S02081","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרִיר II\">preced.</a>) <i>cold</i>. <span class=\"citation\">Targ. Prov. XXV, 13</span>.</div>","alt":[]},"29096":{"h":"קרירטין","r":"S02082","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קרורטין\">קרורטין</a></div>","alt":[]},"29097":{"h":"קַרִישׁ","r":"S02083","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַשׁ\">קְרַשׁ</a>) <i>congealed, hard, frozen</i>. <span class=\"citation\">Targ. Y. Num. XI, 7</span> (not <span dir=\"rtl\">קדיש</span>).—<span class=\"citation\">Ḥull. 120ᵃ</span>, v. <a href=\"#\" data-headword=\"חָלָא III\"><span dir=\"rtl\">חָלָא</span> III</a>.—Pl. <span dir=\"rtl\">קַרִישִׁין</span>; <a href=\"#\" data-headword=\"קַרִישׁ\">קַרִישָׁן</a>. <span class=\"citation\">Targ. Job XXXVIII, 30</span> (Ms. <a href=\"#\" data-headword=\"קְרִי\">קְרִי׳</a>).</div>","alt":["קַרִישָׁא"]},"29098":{"h":"קְרִישָׁא","r":"S02084","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרוּשָׁא\">קְרוּשָׁא</a></div>","alt":[]},"29099":{"h":"קִרְיְתָא","r":"S02085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a></div>","alt":[]},"29100":{"h":"*קְרִיתָא","r":"S02086","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קרי\">קרי</a>, v. <a href=\"#\" data-headword=\"קרי ⁴\"><span dir=\"rtl\">קָרָה</span> II</a>) <i>a covered arched vehicle</i>. <span class=\"citation\">Keth. 17ᵇ</span>, v., however, <a href=\"#\" data-headword=\"הֵינוּמָא\">הֵינוּמָא</a>.</div>","alt":[]},"29101":{"h":"קָרַם","r":"S02087","html":"<div class=\"sense\"> (b. h.) [<i>to contract, join</i>,] <i>to form a skin, cover</i>. <span class=\"citation\">Tosef. T’bul Yom II, 10</span> <span dir=\"rtl\">חוט … שק׳ על וכ׳</span> if the film of an egg floated on the top of a pot; T’bul Yom III, 3. <span class=\"citation\">T’bul Yom III, 3</span>. Ib. <span dir=\"rtl\">קטניות שקָרְמוּ על וכ׳</span> cooked peas which formed a skin on the rim of a pot. <span class=\"citation\">Ber. 25ᵃ</span> <span dir=\"rtl\">כיון שקרמו פניה</span> when its surface formed a crust. <span class=\"citation\">Men. VII, 3</span> (<span class=\"citation\">78ᵇ</span>) <span dir=\"rtl\">עד שלא קרמו בתנור</span> (v. Rabb. D. S. a. l. note 90) before the loaves had formed a slight crust in the oven. <span class=\"citation\">Sabb. I, 10</span> <span dir=\"rtl\">כדי שיִקְרְמוּ פניה וכ׳</span> in time for the cake to form a crust on the surface &amp;c.; <span dir=\"rtl\">שיִקְרוֹם התחתון וכ׳</span> for the bottom to form a crust; a. fr.—Part. pass. <a href=\"#\" data-headword=\"קְרוּם\">קָרוּם</a>. <span class=\"citation\">Ḥull. 49ᵇ</span>; <span class=\"citation\">Tosef. ib. IX, 14</span>, v. <a href=\"#\" data-headword=\"תּוֹתָב\">תּוֹתָב</a>.</div><div class=\"sense\"><b>Hif. הִקְרִים</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"*קְרִיתָא\">same</a>. Y. Ter. X, 47ᵇ bot. <span dir=\"rtl\">בצים שהִקְרִימוּ</span> (abortive) eggs which have formed a membrane. <span class=\"citation\">Ber. 40ᵇ</span>; <span class=\"citation\">B. Bath. 95ᵇ</span> <span dir=\"rtl\">היין שה׳</span> wine which has formed a film; v. <a href=\"#\" data-headword=\"קָרַס\">קָרַס</a></div></div>","alt":[]},"29102":{"h":"קְרַם","r":"S02088","html":"<div class=\"sense\">, <i>to form a skin; to cover, overlay</i>. <span class=\"citation\">Targ. Prov. VII, 16</span> <span dir=\"rtl\">ובקרמא מצראה קְרִמְתָּהּ</span> ed. Lag. (ed. incorr.) and I covered it with Egyptian (fine) cloth.—Part. pass. <span dir=\"rtl\">קְרִים</span>. <span class=\"citation\">Ib. XXVI, 23</span> (some ed. <span dir=\"rtl\">קריס</span>, corr. acc.; h. text <a href=\"#\" data-headword=\"מִצְפֶּה\">מצפה</a>).—[<span class=\"citation\">Targ. Job VI, 12</span>, v. <a href=\"#\" data-headword=\"קְרַס\">קְרַס</a>.]</div><div class=\"sense\"><b>Af. אַקְרִים</b> <div class=\"sense\"> (of wine) <i>to form a film</i>. <span class=\"citation\">Ab. Zar. 30ᵃ</span> bot. (edd. Const. a. Ven. <span dir=\"rtl\">דאקריס</span>); <span class=\"citation\">B. Bath. 95ᵇ</span>; v. <a href=\"#\" data-headword=\"קְרַס\">קְרַס</a>.</div></div>","alt":[]},"29103":{"h":"קֶרֶם","r":"S02089","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַם\">preced.</a>) <i>fine cloth, gauze, hanging.</i>—Pl. <a href=\"#\" data-headword=\"קַרְמִית\">קְרָמִים</a>, <a href=\"#\" data-headword=\"קַרְמִית\">קְרָמִין</a>. <span class=\"citation\">Succ. 10ᵃ</span>; <span class=\"citation\">Sabb. 22ᵃ</span>; <span class=\"citation\">45ᵃ</span>; <span class=\"citation\">Bets. 30ᵇ</span></div>","alt":[]},"29104":{"h":"קְרָמָא","r":"S02090","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"קְרוּם\">קְרוּם</a>, <i>skin, membrane</i>. <span class=\"citation\">Ḥull. 45ᵃ</span> <span dir=\"rtl\">ק׳ עילאה</span> the upper (outer) membrane of the brain; <span dir=\"rtl\">ק׳ תיתאה</span> the lower (inner) membrane. Ib. 46ᵃ <span dir=\"rtl\">ק׳ עילאה וכ׳</span> the outer membrane of the lungs &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>fine cloth</i>, v. <a href=\"#\" data-headword=\"קִרְמָא\">next w.</a></div>","alt":[]},"29105":{"h":"קִרְמָא","r":"S02091","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קֶרֶם\">קֶרֶם</a>, <i>fine cloth, hanging</i>. <span class=\"citation\">Targ. Prov. VII, 16</span> (some ed. <a href=\"#\" data-headword=\"קְרָמָא\">קְרָמָא</a>), v. <a href=\"#\" data-headword=\"קְרַם\">קְרַם</a>.—Pl. <span dir=\"rtl\">קִרְמֵי</span>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">M. Kat. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּסְכֵּס\">כַּסְכֵּס</a>.—[<span class=\"citation\">Erub. 22ᵃ</span>, v. <a href=\"#\" data-headword=\"קוּרָמֵי\">קוּרָמֵי</a>.]</div>","alt":["קִי׳"]},"29106":{"h":"קרמודין","r":"S02092","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְמִיד\">קַרְמִיד</a></div>","alt":[]},"29107":{"h":"קַרְמוּלִין","r":"S02093","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (enlargement of <span dir=\"rtl\">קרם</span>; cmp. <a href=\"#\" data-headword=\"כְּרוּם\">כְּרוּם</a> a. <a href=\"#\" data-headword=\"כַּרְכּוֹם I\"><span dir=\"rtl\">כַּרְכּוֹם</span> I</a>) [<i>green</i> or <i>yellow</i> plants,] <i>ḳarmulin</i>, name of a sort of gourd, the leaves of which are eatable. <span class=\"citation\">Y. Shebi. II, end, 34ᵇ</span> ק׳ פטורין וכ׳ ḳ. are exempt from tithes, … as long as they have not formed gourds; <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"קִירְמוֹלִין\">קִירְמוֹלִין</a>. <span class=\"citation\">Tosef. Shebi. IV, 19</span> <a href=\"#\" data-headword=\"קְרוּמְלִים\">קְרוּמְנִין</a> ed. Zuck. (Var. <span dir=\"rtl\">קרמלוס</span>, <a href=\"#\" data-headword=\"קְרוּמְלִים\">קְרוּמְלִים</a>). <span class=\"citation\">Tosef. Neg. I, 5</span> (expl. <a href=\"#\" data-headword=\"יְרַקְרַק\">ירקרק</a>) <span dir=\"rtl\">כשעוה וכקוּרְמָל</span> ed. Zuck. (Var. <span dir=\"rtl\">וכקוּרְמָן</span>; R. S. to <span class=\"citation\">Neg. XI, 4</span> <span dir=\"rtl\">וכקורמין</span>) of the color of wax or of ḳ., v. <a href=\"#\" data-headword=\"כַּרְמֶל\">כַּרְמֶל</a>.</div>","alt":[]},"29108":{"h":"קַרְמִיד","r":"S02094","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κεραμίς, -ίδος) <i>roof-tile</i>. <span class=\"citation\">Y. Taan. I, 64ᵇ</span> top <span dir=\"rtl\">כדי שיודחו פני הק׳</span> (not <span dir=\"rtl\">שידוחו</span>) so that the surface of the roof-tiles appears washed (by the rain); <span class=\"citation\">Y. Ber. IX, 13ᵈ</span> bot. <span dir=\"rtl\">שיודחו פניה</span> (corr. acc.); <span class=\"citation\">Gen. R. s. 13</span> (not <span dir=\"rtl\">שידחו</span>).—Pl. <span dir=\"rtl\">קִרְמִידִים</span>, <span dir=\"rtl\">קִרְמִידִין</span>. Sifra M’tsorʿa, Par. 6, ch. IV יכול אפי׳ ק׳ וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"קרומדים\">קרומדים</a>, corr. acc.) lest you think that you may use also tiles or bricks. <span class=\"citation\">Tosef. Kel. B. Kam. II, 3</span> <span dir=\"rtl\">הסילונות והקרמודין וכ׳</span> ed. Zuck. (oth. ed. <a href=\"#\" data-headword=\"קְרַמְיוֹן\">קרמיון</a></div>","alt":[]},"29109":{"h":"קְרַמְיוֹן","r":"S02095","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> river, <i>Ḳ’ramyon</i>, prob. a tributary of the Jordan. <span class=\"citation\">Par. VIII, 10</span>; <span class=\"citation\">Snh. 5ᵇ</span> (Ms. M. <span dir=\"rtl\">קרימ׳</span>). <span class=\"citation\">B. Bath. 74ᵇ</span> (Ms. M. <span dir=\"rtl\">קור׳</span>; Ms. O. <span dir=\"rtl\">קירמון</span>; Ms. H. <a href=\"#\" data-headword=\"קדרון\">קדרון</a>); <span class=\"citation\">Midr. Till. to Ps. XXIV</span> <span dir=\"rtl\">קירמ׳</span> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"קרייון\">קרייון</a>, corr. acc.); <span class=\"citation\">Yalk. Ps. 697</span>.—[<span class=\"citation\">Tosef. Kel. B. Kam. II, 3</span>, v. preced.]</div>","alt":["קִירַ׳"]},"29110":{"h":"קַרְמִינָאֵי","r":"S02096","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְמְנָאֵי\">קַרְמְנָאֵי</a></div>","alt":[]},"29111":{"h":"קַרְמִית","r":"S02097","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (from its color; cmp. <a href=\"#\" data-headword=\"קַרְמוּלִין\">קַרְמוּלִין</a>) <i>cow-wheat</i> (Melampyron) of which a coarse bread is made. <span class=\"citation\">Tosef. Ḥall. I, 1</span> <span dir=\"rtl\">אף הק׳ חייבת וכ׳</span> (ed. Zuck. <a href=\"#\" data-headword=\"קרומית\">קרומית</a>) ḳ. is also subject to the priest’s gift; Y. ib. I, beg. 57ᵃ; <span class=\"citation\">Y. Pes. II, 29ᵇ</span> top; Bab. <span class=\"citation\">Pes. 35ᵃ</span>, expl. <span dir=\"rtl\">שיצניתא דמשתכחא וכ׳</span> a weed found among Papaver Spinosum. <span class=\"citation\">Tosef. ib. I</span> (<span class=\"citation\">II), 29</span> <span dir=\"rtl\">אף הק׳ יוצא וכ׳</span> one may comply with the duty of eating <i>matsah</i> (on the first night of Passover) by eating bread made of ḳ.—V. <a href=\"#\" data-headword=\"קוּרָמֵי\">קוּרָמֵי</a>.</div>","alt":["קְרָמִית"]},"29112":{"h":"רְמוּצָא","r":"T00799","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָמַץ\">רָמַץ</a></div>","alt":["רְמוּצָה"]},"29113":{"h":"רָמוּתָא","r":"T00800","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּם\">רוּם</a>) <i>haughtiness, pride</i>. <span class=\"citation\">Targ. Prov. VIII, 13</span>. <span class=\"citation\">Ib. XXI, 4</span>. <span class=\"citation\">Targ. Jer. XLVIII, 29</span>; a. fr.—<span class=\"citation\">Sabb. 94ᵃ</span> <span dir=\"rtl\">רָמוּת רוחא וכ׳</span> pride seizes them (which makes them walk micingly). <span class=\"citation\">Ab. Zar. 71ᵃ</span> <span dir=\"rtl\">דר׳ רוחא וכ׳</span> they are too proud (to take back what they have given). <span class=\"citation\">Sabb. 110ᵇ</span>; a. e.</div>","alt":[]},"29114":{"h":"רָמַז","r":"T00801","html":"<div class=\"sense\"> [<i>to move</i>, cmp. <span dir=\"rtl\">רָמַשׂ</span>,] <i>to nod, gesticulate, hint</i>. <span class=\"citation\">Gitt. V, 7</span> <span dir=\"rtl\">חרש רוֹמֵז ונִרְמַז</span> a deaf-mute person may transact business by gesticulating and being spoken to by gestures (with hands and head, contrad. to <a href=\"#\" data-headword=\"קָפַץ\">קָפַץ</a>). <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">ר׳ למנשה</span> he motioned to Manasseh; a. fr.—Trnsf. <i>to intimate, hint</i>. <span class=\"citation\">Sabb. 113ᵇ</span> <span dir=\"rtl\">רֶמֶז רָ׳ לה וכ׳</span> he intimated to her that &amp;c. <span class=\"citation\">Cant. R. to I, 15</span> <span dir=\"rtl\">רמז רָמְזָה לנח וכ׳</span> she (the dove, by bringing an olive leaf) hinted to Noah, as if saying &amp;c.; a. e.</div><div class=\"sense\"><b>Pi. רִמֵּז</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָמוּתָא\">same</a>. Ib. to I, 9 <span dir=\"rtl\">והיתה מְרַמֶּזֶת וכ׳</span></div></div><div class=\"sense\"><b>Nif. נִרְמַז</b> <div class=\"sense\"><i>to be spoken to by gestures</i>, v. supra.</div></div>","alt":[]},"29115":{"h":"רְמַז","r":"T00802","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Gen. XLIV, 19</span>. <span class=\"citation\">Targ. Is. LVIII, 9</span>. <span class=\"citation\">Targ. Prov. VI, 13</span>; a. fr.—<span class=\"citation\">Keth. 33ᵃ</span>, v. infra. Part. pass. <span dir=\"rtl\">רָמִיז</span>; f. <a href=\"#\" data-headword=\"רְמִיזָא\">רְמִיזָא</a>. <span class=\"citation\">Meg. 2ᵃ</span> <span dir=\"rtl\">היכא ר׳</span> where is it intimated (in the Biblical text)?; <span class=\"citation\">Snh. 81ᵇ</span>; a. e.</div><div class=\"sense\"><b>Pa. רַמֵּז</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָמַז\">same</a>. <span class=\"citation\">Targ. Job XV, 12</span> (Var. ed. Lag. <span dir=\"rtl\">מרזמין</span>; h. text <span dir=\"rtl\">ירזמון</span>, Var. in Cod. <span dir=\"rtl\">ירמזון</span>).—<span class=\"citation\">Keth. 33ᵃ</span> <span dir=\"rtl\">ונְרַמֵּז בהו רַמּוּזֵי</span> (Rashi <a href=\"#\" data-headword=\"רָמַז\">נִירְמַז</a>) and let us (the court) intimate to them (the warning, in such a manner as not to offend them). <span class=\"citation\">Sabb. 62ᵇ</span> (expl. <span dir=\"rtl\">ומסקרות וכ׳</span>, <span class=\"citation\">Is. III, 16</span> <span dir=\"rtl\">ומשׂק׳</span>) <span dir=\"rtl\">דהוו מלאן … ומְרַמְּזָן</span> they filled their eyes with paint and winked; <span class=\"citation\">Yalk. Is. 262</span> <span dir=\"rtl\">ורמזין</span> (read: <span dir=\"rtl\">ורָמְזָן</span> <i>Pe.</i>). <span class=\"citation\">B. Kam. 24ᵇ</span> <span dir=\"rtl\">דקמְרַמְּזֵי רמוזי</span> they give signs to one another; <span class=\"citation\">Snh. 86ᵇ</span>; a. e.</div></div>","alt":[]},"29116":{"h":"רֶמֶז","r":"T00803","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְמַז\">preced.</a>) <i>gesture, hint, intimation.</i> <span class=\"citation\">Sabb. 113ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"רָמַז\">רָמַז</a>. Y. Ber. IV, 8ᵃ top <span dir=\"rtl\">ר׳ לתלמיד חכם וכ׳</span> this is an intimation to a scholar that a man must say to his teacher &amp;c. <span class=\"citation\">Gen. R. s. 12</span>, beg. (ref. to <span class=\"citation\">Job XXVI, 14</span>) <span dir=\"rtl\">הפקחין יודעין רִמּוּזוֹ והגיונו</span> the wise understand his intimation (through the thunder) and his plans; <span class=\"citation\">Yalk. Job 914</span> <span dir=\"rtl\">רִמְזוֹ של דבר והגיונו</span>. <span class=\"citation\">Ex. R. s. 15</span><sup>26</sup> <span dir=\"rtl\">בר׳ הודיע להם וכ׳</span> he gave them to understand by allusion that &amp;c.; a. fr.</div>","alt":[]},"29117":{"h":"רמ\"ח","r":"T00804","html":"<div class=\"sense\"> (numerical value) <i>two hundred and forty-eight</i>. <span class=\"citation\">Gen. R. s. 69</span>, beg.; a. e.</div>","alt":[]},"29118":{"h":"רמח","r":"T00805","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. III, beg. 5ᶜ</span>, read: <a href=\"#\" data-headword=\"רֶמֶץ\">רֶמֶץ</a>, v. <a href=\"#\" data-headword=\"גִּיסְטְרָא\">גִּיסְטְרָא</a></div>","alt":[]},"29119":{"h":"רֹמַח","r":"T00806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹמַח\">רוֹמַח</a>, <a href=\"#\" data-headword=\"רוּמְחָא\"><a href=\"#\" data-headword=\"רוּמְחָא\">רוּמְחָא</a>.</a></div>","alt":["רֻמְחָא"]},"29120":{"h":"רַמִּי","r":"T00807","html":"<div class=\"sense\"> (tradit. pronunc. <span dir=\"rtl\">רָמִי</span>) pr. n. m. (= <span dir=\"rtl\">ר׳ אמי</span>) <i>Rammi</i> (<i>Rami</i>), name of several Amoraim. <span class=\"citation\">Keth. 87ᵇ</span>, a. fr. <span dir=\"rtl\">ר׳ בר חמא</span>. <span class=\"citation\">Ḥull. 20ᵇ</span>, a. fr. <span dir=\"rtl\">ר׳ בר יחזקאל</span> (Y. Erub. II, 22ᶜ top <span dir=\"rtl\">אמי בר יחזקאל</span>); a. others.</div>","alt":[]},"29121":{"h":"רמי","r":"T00808","html":"<div class=\"sense\"> (b. h.) [<i>to move</i>,] <i>to throw, swing</i>. Mekh. B’shall., Shir., s. 2 (ref. to <span class=\"citation\">Ex. XV, 1</span> a. <span class=\"citation\">4</span>) <span dir=\"rtl\">ר׳ שהיו עולין למרום וכ׳</span> <i>ramah</i> means that they were hurled upward, <i>yarah</i>, that they were thrown down the deep.</div><div class=\"sense\"><b>Pi. רִמָּה</b> <div class=\"sense\"><i>to impose upon, deceive; to be cunning</i>. Y. Hor. III, 48ᵃ bot. (he was no deceiver) <span dir=\"rtl\">אלא שהיה מְרַמֶּה במצות</span> but he was cunning in charitable deeds (waited until others had subscribed, and then gave as much as all of them combined); <span class=\"citation\">Deut. R. s. 4</span>; Tanḥ. R’eh 5. <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">אתה רִמִּיתָ באביך בגדי … שתמר מְרַמָּה בך וכ׳</span> thou (Judah) didst deceive thy father by means of a kid (<span class=\"citation\">Gen. XXXVII, 31</span>); by thy life! Tamar shall deceive thee through a kid (ib. XXXVIII, 20); Yalk. ib. 145 <span dir=\"rtl\">לאביך … לך</span>; a. e.—Part. pass. <a href=\"#\" data-headword=\"מְרוּמֶּה\">מְרוּמֶּה</a>. <span class=\"citation\">Snh. 32ᵇ</span>, a. e. <span dir=\"rtl\">דין מ׳</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a></div></div>","alt":["רָמָה"]},"29122":{"h":"רְמֵי","r":"T00809","html":"<div class=\"sense\"><b>1)</b> <i>to throw, swing; to put on; to impose</i>. <span class=\"citation\">Targ. Ex. XV, 1</span>. <span class=\"citation\">Targ. Ez. XVI, 5</span>. <span class=\"citation\">Targ. II Kings XVIII, 14</span>. <span class=\"citation\">Targ. Ps. LXXVIII, 57</span> (h. text <a href=\"#\" data-headword=\"רַמְיָה\">רְמִיָּה</a>!); a. fr.—<span class=\"citation\">Men. 42ᵃ</span> <span dir=\"rtl\">ר׳ חוטי</span> threw (attached) threads as show fringes; <span dir=\"rtl\">ר׳ ארבע</span> put four threads on. <span class=\"citation\">Sabb. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"פּוּזְמְקֵי\">פּוּזְמְקֵי</a>. <span class=\"citation\">Nidd. 33ᵇ</span> <span dir=\"rtl\">ר׳ ליה תורא</span> threw an ox down (slaughtered an ox) in his honor. <span class=\"citation\">Men. 42ᵇ</span> <span dir=\"rtl\">רְמִינָן להו ביורה</span> we cast them into the boiler.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"רְמֵי\">רְמֵי</a>, <a href=\"#\" data-headword=\"רַמְיָא\">רַמְיָא</a> <i>thrown down, lying</i>. <span class=\"citation\">Targ. Deut. XXI, 1</span> (O. ed. Vien. <a href=\"#\" data-headword=\"רְמֵי\">רָמֵי</a>). <span class=\"citation\">Targ. Jud. XIX, 27</span>; a. e.—<span class=\"citation\">Zeb. 5ᵃ</span> ר׳ ריש לקיש וכ׳ Resh Laḳish was lying on his belly in the college hall and asked &amp;c. <span class=\"citation\">Shebu. 34ᵇ</span> <span dir=\"rtl\">כל מילתא דלא ר׳ עליה וכ׳</span> a thing which does not rest upon a man (in which he is not interested), he will do unconsciously; <span class=\"citation\">ib. 41ᵇ</span>, sq.; <span class=\"citation\">B. Bath. 39ᵃ</span>; a. fr.—<span dir=\"rtl\">ר׳ לבני</span> [<i>to put up bricks</i>,] <i>to make bricks</i>. <span class=\"citation\">Targ. Gen. XI, 3</span>. <span class=\"citation\">Targ. Ex. V, 7</span>; a. e.—ר׳ תיגרא <i>to create discord; to dispute</i>. <span class=\"citation\">Targ. Prov. VI, 14</span>; <span class=\"citation\">19</span>; a. e.—<span class=\"citation\">Sabb. 130ᵃ</span> <span dir=\"rtl\">ליכא … דלא רָמוּ בה ת׳</span> there is no marriage contract at which the parties do not quarrel.</div><div class=\"sense\"><b>—2)</b> <i>to lift, remove</i>. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> bot. <span dir=\"rtl\">בעי מִירְמִיתֵיה</span> wanted to lift it; a. e.</div><div class=\"sense\"><b>—3)</b>  [<i>to pitch one thing against another</i>,] <i>to show an incongruity; to object.</i> Nidd. l. c. <span dir=\"rtl\">ר׳ … מתניתין אהדדי</span> pointed out an incongruity between two Mishnahs. <span class=\"citation\">Taan. 4ᵇ</span> <span dir=\"rtl\">גברא אגברא קא רָמִית</span> thou provest an incongruity between two authorities (why can they not differ in opinion)? <span class=\"citation\">B. Mets. 22ᵇ</span> רב פפא ר׳ כתיב וכ׳ Rab Papa raised an objection: it is written (<span class=\"citation\">Lev. XI, 38</span>) <i>ki yitten</i>, and we read <i>ki yuttan</i>, how is this to be explained? <span class=\"citation\">Yeb. 108ᵇ</span> <span dir=\"rtl\">ורְמִינְהִי וכ׳</span> and we shall show an incongruity in it, i.e. this disagrees with the Mishnah, &amp;c. <span class=\"citation\">Succ. 16ᵃ</span> <span dir=\"rtl\">איכא דר׳ ליה מִירְמָא</span> some put it in the shape of pointing out a contradiction (between a Mishnah and a Boraitha); a. v. fr.</div><div class=\"sense\"><b>Af. אַרְמֵי</b> <div class=\"sense\"><b>1)</b> <i>to cast</i>. <span class=\"citation\">Targ. Jud. XX, 16</span>. <span class=\"citation\">Targ. Prov. I, 14</span>; a. e.—<span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">הוה מַרְמִינָן וכ׳</span> we used to cast our bread together (into one basket) and eat. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אנא קאים וארמינא</span> I will stand up and put the bread into the basket; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to tear away, remove with force</i>. <span class=\"citation\">Pes. 10ᵇ</span> <span dir=\"rtl\">אַרְמוּיֵי אַרְמֵיה מיניה</span> (not <span dir=\"rtl\">ארמוייה</span>) it (the mouse) may have snatched it from the other mouse. <span class=\"citation\">Ḥag. 15ᵇ</span> <span dir=\"rtl\">אי … מאן מַרְמֵי ליה מאן</span> if I take him by the hand, who will tear him away from me? who?</div><div class=\"sense\"><b>—3)</b> <i>to lift up</i>. <span class=\"citation\">Ab. Zar. 34ᵇ</span> <span dir=\"rtl\">תַּרְמִינָךְ שעתך</span> (Ms. M. <span dir=\"rtl\">תור מינך</span>, v. Rabb. D. S. a. l. note) may thy hour lift thee up (i.e. may thy luck be high)!</div></div><div class=\"sense\"><b>Pa. רַמֵּי</b> <div class=\"sense\"><i>to impose, deceive</i>. <span class=\"citation\">Targ. Y. Num. XXV, 18</span>. <span class=\"citation\">Targ. Prov. XXVI, 19</span>.—<span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">הוה מְרַמֵּי במצוותה</span>, v. <a href=\"#\" data-headword=\"רמי\">preced.</a>; a. e.</div></div><div class=\"sense\"><b>Ithpe. אִתְרְמֵי  אִתְרְמָא</b> <div class=\"sense\"><b>1)</b> <i>to throw one’s self, be thrown</i>. <span class=\"citation\">Targ. I Chr. X, 4</span>, sq. <span class=\"citation\">Targ. Josh. X, 11</span>.—[<span class=\"citation\">Targ. Prov. VI, 6</span> <a href=\"#\" data-headword=\"רְמֵי\">אתרמי</a> some ed., read: <span dir=\"rtl\">אתד׳</span>, v. <a href=\"#\" data-headword=\"דְּמֵי I\"><span dir=\"rtl\">דְּמֵי</span> I</a>.]</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"קָלַע I\"><span dir=\"rtl\">קְלַע</span> I</a>) <i>to happen, chance</i>. <span class=\"citation\">Ḥull. 13ᵃ</span> <span dir=\"rtl\">מקום … איתרמי ליה</span> (not <span dir=\"rtl\">איתרמו</span>) because no suitable place (for slaughtering) offered itself there. <span class=\"citation\">Shebu. 41ᵇ</span> <span dir=\"rtl\">עד דמִתְרְמוּ בי תרי וכ׳</span> until two persons shall happen to come that have studied &amp;c.; a. e.</div></div>","alt":["רְמָא"]},"29123":{"h":"רַמְיָא","r":"T00810","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְמֵי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>lying</i>, v. <a href=\"#\" data-headword=\"רְמֵי\">preced.</a></div><div class=\"sense\"><b>—2)</b>  (<i>lying</i>) <i>idle, lax</i>. <span class=\"citation\">Targ. Prov. X, 4</span> (ed. Lag. <a href=\"#\" data-headword=\"רַמְיָיא\">רַמְיָיה</a>).—<i>Fem.</i> <span dir=\"rtl\"><a href=\"#\" data-headword=\"רְמִיתָא\">רְמִיתָא</a> (רמְיְיתָא</span>). <span class=\"citation\">Ib. XIX, 15</span>.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"רַמַּאי\">רַמַּאי</a>) <i>deceiver</i>. Ib. XIV, 25.—[<a href=\"#\" data-headword=\"רַמְיָא\">רָמַיָּא</a>, <span dir=\"rtl\">רָמַיָּיא</span>, pl. of <a href=\"#\" data-headword=\"רָם ⁴\">רָמָא</a>.]</div>","alt":["רַמְיָיא"]},"29124":{"h":"רַמְיָה","r":"T00811","html":"<div class=\"sense\">, <span class=\"citation\">Men. 42ᵃ</span>, v. <a href=\"#\" data-headword=\"רוּמְיָא\">רוּמְיָא</a></div>","alt":[]},"29125":{"h":"רַמְיוּ","r":"T00812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמְיוּתָא\">רַמְיוּתָא</a></div>","alt":[]},"29126":{"h":"רַמָּיוּת","r":"T00813","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַמַּאי\">רַמַּאי</a>) <i>deception, fraud</i>. <span class=\"citation\">Y. Taan. II, 65ᵇ</span> <span dir=\"rtl\">תשובה של ר׳</span> dishonest penitence; <span class=\"citation\">Gen. R. s. 9</span>. <span class=\"citation\">Y. Kidd. III, beg. 63ᶜ</span> <span dir=\"rtl\">נקנה המקח אלא שנהג מנהג ר׳</span> the transaction is legal, but he acted dishonestly; Bab. <span class=\"citation\">Kidd. 58ᵇ</span>; <span class=\"citation\">Tosef. Yeb. IV, 4</span>. <span class=\"citation\">Lev. R. s. 23</span>, beg. (ref. to <span class=\"citation\">Gen. XXVIII, 5</span>) <span dir=\"rtl\">כללן כולן בר׳</span> the text includes them all under the attribute of dishonesty (<span dir=\"rtl\">ארמי</span> = <a href=\"#\" data-headword=\"רַמַּאי\">רמאי</a>, v. <a href=\"#\" data-headword=\"רַמַּאי\">רַמַּאי</a>). <span class=\"citation\">B. Bath. 123ᵃ</span> אחיו אני בר׳ I am his brother in cunning; a. e.</div>","alt":["רַמָּאוּת"]},"29127":{"h":"רַמְיוּתָא","r":"T00814","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXIX, 19</span> (ed. Vien. <span dir=\"rtl\">רְמִיּוּ</span>). <span class=\"citation\">Ib. XXV, 28</span>; a. e.—<span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">מאי רַמָּאוּתֵיה</span> wherein does his trickery consist? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לסגויי בר׳</span>, v. <a href=\"#\" data-headword=\"סְגֵי III\"><span dir=\"rtl\">סְגֵי</span> II</a>; a. e.</div>","alt":["רַמְיוּ","רַמָּאוּתָא"]},"29128":{"h":"רְמִיזָא","r":"T00815","html":"<div class=\"sense\"> f. </div><div class=\"sense\"><b>1)</b>  part. pass. of <a href=\"#\" data-headword=\"רְמַז\">רְמַז</a>.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"רְמִיזָה\">next w.</a> <span class=\"citation\">Snh. 86ᵇ</span> מהו דתימא ר׳ מילתא היא קמ&quot;ל ר׳ וכ׳ I might have thought that an exchange of signs (between witnesses) is something (cause for disqualification), therefore we are told, it is nothing at all.</div>","alt":[]},"29129":{"h":"רְמִיזָה","r":"T00816","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָמַז\">רָמַז</a>) <i>hint, gesture</i>. <span class=\"citation\">Yeb. XIV, 1</span> <span dir=\"rtl\">כשם שהוא כונס בר׳ וכ׳</span> as well as he (a deaf mute) may marry by gestures, he may divorce by gesture; <span class=\"citation\">Gitt. 71ᵃ</span>. <span class=\"citation\">Ib. 59ᵃ</span> <span dir=\"rtl\">בגיטין דברי הכל בר׳</span> as to letters of divorce, all agree that a deaf mute may divorce by gesture. <span class=\"citation\">Gen. R. s. 5</span>, beg. <span dir=\"rtl\">שואלים … בר׳ וכ׳</span> they greeted the king with gestures, with fingering and with flags; ib. s. 28; <span class=\"citation\">Yalk. ib. 7</span>; <span class=\"citation\">Yalk. Ps. 848</span>; a. e.—Pl. <span dir=\"rtl\">רְמִיזוֹת</span>. <span class=\"citation\">Gitt. 71ᵃ</span> <span dir=\"rtl\">רְמִיזוֹתָיו</span>, v. <a href=\"#\" data-headword=\"קְפִיצָה\">קְפִיצָה</a>. <span class=\"citation\">Yeb. 108ᵇ</span>, v. <a href=\"#\" data-headword=\"קְרִיצָה\">קְרִיצָה</a>.—[<span class=\"citation\">Lam. R. to I, 13</span> <span dir=\"rtl\">כמה ר׳ עשיתי</span>, perh. to be read: <a href=\"#\" data-headword=\"רַמָּיוּת\">רְמִיּוֹת</a> <i>tricks</i>.]</div>","alt":[]},"29130":{"h":"רַמַּיי","r":"T00817","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמַּאי\">רַמַּאי</a> h. a. ch.</div>","alt":["רַמָּיָיא"]},"29131":{"h":"רַמְיָיא","r":"T00818","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמְיָא\">רַמְיָא</a></div>","alt":["רַמְיָיה","רְמַיְיתָא"]},"29132":{"h":"רַמַּיְיתָא","r":"T00819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמַּאי\">רַמַּאי</a> ch.</div>","alt":[]},"29133":{"h":"רמילוס","r":"T00820","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹמוּלוֹס\">רוֹמוֹלוֹס</a></div>","alt":[]},"29134":{"h":"רמין","r":"T00821","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">יודן ר׳</span> some ed., read <a href=\"#\" data-headword=\"רַמַּיי\">רמַּיי</a>.</div>","alt":[]},"29135":{"h":"רְמִיתָא","r":"T00822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמְיָא\">רַמְיָא</a></div>","alt":[]},"29136":{"h":"רַמָּךְ","r":"T00823","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>mule of a horse dam, rammakh</i>. <span class=\"citation\">Kil. VIII, 5</span> <span dir=\"rtl\">הר׳ מותר</span> you may let the <i>rammakh</i> gender with his kind.</div>","alt":[]},"29137":{"h":"רַמָּכָא","r":"T00824","html":"<div class=\"sense\"> <span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> bot. (ref. to <a href=\"#\" data-headword=\"רַמָּךְ\">רמך</a>, v. <a href=\"#\" data-headword=\"רַמָּךְ\">preced.</a>) <span dir=\"rtl\">ר׳ דלא כלינס</span> the <i>rammakh</i> is one that brooks no bridle (effrenis, v. Plin. Hist. Nat. VIII, 69).—Pl. <span dir=\"rtl\">רַמָּכִין</span>, <span dir=\"rtl\">רַמָּכַיָּא</span>, <span dir=\"rtl\">רַמָּכֵי</span>. <span class=\"citation\">Targ. Esth. VIII, 10</span>; Targ. II Esth. ib.—<span class=\"citation\">Taan. 23ᵃ</span> <span dir=\"rtl\">חזא חמריה … ר׳ ר׳</span> (Ḥoni after seventy years’ sleep) saw his ass to whom had been born several generations of mules.</div>","alt":["רַמָּכָה"]},"29138":{"h":"רמכוך","r":"T00825","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בָּרִין\">בָּרִין</a></div>","alt":[]},"29139":{"h":"רָמַם","r":"T00826","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">רִימֵּם</span>, v. <a href=\"#\" data-headword=\"רוּם\">רוּם</a> h.</div>","alt":[]},"29140":{"h":"רָמְמָא","r":"T00827","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"רָם ⁴\">רָמָא</a>, <i>high.</i>—Pl. <span dir=\"rtl\">רָמְמַיָּא</span>. <span class=\"citation\">Cant. R. to IV, 4</span>, v. <a href=\"#\" data-headword=\"רָם ⁴\"><span dir=\"rtl\">רָמָא</span> I</a>.</div>","alt":[]},"29141":{"h":"רֵמָנָא","r":"T00828","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵימָנָא\">רֵימָנָא</a></div>","alt":[]},"29142":{"h":"רָמַס","r":"T00829","html":"<div class=\"sense\"> (b. h.) <i>to tread, stamp</i>. <span class=\"citation\">Y. Peah V, beg. 18ᵈ</span> רוֹמֵס הייתי זתים וכ׳ I was stamping olives with R. Ḥiya &amp;c.; ib. VI, 19ᶜ bot.; ib. VII, end, 20ᶜ. <span class=\"citation\">Kidd. 66ᵃ</span> <span dir=\"rtl\">רוֹמְסֵם</span> crush them (the Pharisees); a. fr.—Part. pass. <span dir=\"rtl\">רָמוּס</span>; f. <span dir=\"rtl\">רְמוּסָה</span>. <span class=\"citation\">Y. Ber. IV, 8ᵃ</span> <span dir=\"rtl\">הר׳ ביד עריצים</span> (the city of Jerusalem) which is trodden down by tyrants.</div><div class=\"sense\"><b>Pi. רִמֵּס</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רֵמָנָא\">same</a>. <span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">והיה קרון … ומְרַמַּסְתָּן</span> (not <span dir=\"rtl\">ומרמסן</span>) the carriage passed over them and crushed them to death; (<span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">ומפסקתן</span>).</div></div>","alt":[]},"29143":{"h":"רְמַס","r":"T00830","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. LXXXIX, 42</span>.</div>","alt":[]},"29144":{"h":"רֶמֶס","r":"T00831","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">רְמָסִים</span>, v. <a href=\"#\" data-headword=\"רֶמֶשׂ\">רֶמֶשׂ</a>.</div>","alt":[]},"29145":{"h":"רָמַץ","r":"T00832","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָמַס\">רָמַס</a>) [<i>to crush</i>, denom. <a href=\"#\" data-headword=\"רֶמֶץ\">רֶמֶץ</a>,] <i>to roll</i> or <i>bake in hot ashes</i> <a href=\"#\" data-headword=\"רֶמֶץ\">(רֶמֶץ</a>). Part. pass. <span dir=\"rtl\">רָמוּץ</span>; f. <a href=\"#\" data-headword=\"רְמוּצָא\">רְמוּצָה</a>; <span dir=\"rtl\">דלעת הר׳</span> a certain kind of <i>cucumbers made edible by baking in hot ashes, Bitter Apple</i>. <span class=\"citation\">Ned. VI, 1</span> (<span class=\"citation\">49ᵃ</span>) <span dir=\"rtl\">דלעת הר׳</span> (Bab. ed. <a href=\"#\" data-headword=\"הַרְמוּצָא\">הרמוצא</a>), expl. ib. 51ᵃ <span dir=\"rtl\">דלעת הטמונה ברמץ</span> a cucumber steeped in hot ashes; (another definition, v. <a href=\"#\" data-headword=\"קַרְקוּזָאָה\">קַרְקוֹזָאָה</a>). <span class=\"citation\">Kil. I, 5</span>; <span class=\"citation\">Tosef. ib. I, 5</span>, expl. Y. ib. I, 27ᵃ <span dir=\"rtl\">כמין דלעת מרה … ברמץ</span> a kind of bitter cucumber which is sweetened by rolling it in ashes; <span class=\"citation\">Y. Ned. VI, 39ᶜ</span> bot. <span dir=\"rtl\">ברימצא</span>.</div>","alt":[]},"29146":{"h":"רְמַץ I","r":"T00833","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"רְמַץ I\">רִמֵּץ</a> (cmp. <a href=\"#\" data-headword=\"רָמַץ\">preced.</a>) [<i>to squeeze in</i>, corresp. to h. <a href=\"#\" data-headword=\"שָׁבַץ\">שבץ</a>,] </div><div class=\"sense\"><b>1)</b> <i>to weave in checkers, to variegate</i>. <span class=\"citation\">Targ. Ex. XXVIII, 39</span>.—Part. pass. <span dir=\"rtl\">מְרמּץ</span>; f. <a href=\"#\" data-headword=\"מְרַמְצָא\">מְרַמְּצָא</a>; pl. <span dir=\"rtl\">מְרַמְּצִין</span>; <a href=\"#\" data-headword=\"מְחַמְּצָן\">מְרַמְּצָן</a>. Ib. 4. <span class=\"citation\">Targ. Ps. XLV, 14</span>.</div><div class=\"sense\"><b>—2)</b>  (of jeweler’s work) <i>to set, enchase</i>. Part. pass. as ab. <span class=\"citation\">Targ. O. Ex. XXVIII, 20</span> (Y. <span dir=\"rtl\">משקע׳</span>); ib. O. a. Y. XXXIX, 13 <span dir=\"rtl\">משקעין מר׳</span>. <span class=\"citation\">Targ. II Chr. III, 6</span>.</div>","alt":[]},"29147":{"h":"רְמַץ II","r":"T00834","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רְמַץ I\">preced.</a>; cmp. meanings of <span dir=\"rtl\">רסס</span>), <i>Pa.</i> רַמֵּץ <i>to drip, to discharge viscous matter</i>. <span class=\"citation\">Bekh. 44ᵃ</span> (expl. <span dir=\"rtl\">טרוטות</span>) <span dir=\"rtl\">דמְרַמְּצן עיניה</span> Ar. (omitted in ed.) whose eyes are bleared.</div>","alt":[]},"29148":{"h":"רֶמֶץ","r":"T00835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָמַץ\">רָמַץ</a>) [<i>crushed matter</i>,] <i>hot ashes, embers</i>. <span class=\"citation\">Nidd. 49ᵇ</span> <span dir=\"rtl\">שופתה ע&quot;ג הר׳</span> he puts the pot upon embers: if the embers make it water-tight &amp;c. <span class=\"citation\">Neg. IX, 1</span> <span dir=\"rtl\">נכוה … בר׳</span> burnt by live coals or by embers. <span class=\"citation\">Ned. 51ᵃ</span>, v. <a href=\"#\" data-headword=\"רָמַץ\">רָמַץ</a>; a. e.</div>","alt":[]},"29149":{"h":"רִמְצָא","r":"T00836","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רֶמֶץ\">same</a>. Y. Ned. I, 39ᶜ bot., v. <a href=\"#\" data-headword=\"רָמַץ\">רָמַץ</a>.</div><div class=\"sense\"><b>—2)</b> <i>a pointed tool, pick</i>. <span class=\"citation\">Nidd. 62ᵃ</span>; <span class=\"citation\">Sabb. 90ᵃ</span>, v. <a href=\"#\" data-headword=\"אַשְׁלְגָא\">אַשְׁלְגָא</a>. <span class=\"citation\">Ib. 103ᵃ</span> <span dir=\"rtl\">דבזעיה בר׳ דפרזלא וכ׳</span> when he bored a hole in it with an iron pick, and left it in.</div>","alt":["רִי׳"]},"29150":{"h":"רֶמֶשׂ","r":"T00837","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> רמש <i>to move, creep</i>) <i>creeping thing, worm, snake</i> &amp;c.—Pl. <span dir=\"rtl\">רְמָשִׂים</span>. <span class=\"citation\">Nidd. III, 2</span>; <span class=\"citation\">Snh. VIII, 2</span>, v. <a href=\"#\" data-headword=\"שֶׁקֶץ\">שֶׁקֶץ</a>. <span class=\"citation\">Yalk. Ex. 182</span> <span dir=\"rtl\">רְמָסִים</span>; a. fr.</div>","alt":[]},"29151":{"h":"רְמַשׁ","r":"T00838","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>evening</i>. <span class=\"citation\">Targ. Gen. I, 5</span>. <span class=\"citation\">Targ. Ps. LXV, 9</span>. <span class=\"citation\">Targ. Is. XXI, 13</span> (h. text <a href=\"#\" data-headword=\"עֲרָב I\">עֲרָב</a>!); a. fr.—<span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span dir=\"rtl\">ברו׳ נחית וכ׳</span> in the evening he went down to the house of assembly. Ib. IV, 7ᶜ bot. <span dir=\"rtl\">יצלי דר׳ וכ׳</span> one may say the evening prayer (on the Sabbath), while it is still day-time; a. fr.</div>","alt":["רַמְשָׁא","רוּמְ׳"]},"29152":{"h":"רַמְשִׁית","r":"T00839","html":"<div class=\"sense\"> adv. (<a href=\"#\" data-headword=\"רְמַשׁ\">preced.</a>) <i>last night</i> (= h. <a href=\"#\" data-headword=\"אֶמֶשׁ\">אֶמֶשׁ</a>). Y. Ned. VIII, beg. 40ᵈ <span dir=\"rtl\">לית … ברומשא לא טעמית כלום ר׳ וכ׳</span> a man does not say to his neighbor in the evening, I did not taste anything <i>ramshith</i> (meaning the night before), but he would say, <i>ethmol</i> (yesternight, which would prove that in popular conception the day begins with the night); <span dir=\"rtl\">לית … בצפרא לא טעמית כלום ר׳ וכ׳</span> (on the other hand) does not a man say to his neighbor in the morring, I did not taste anything <i>rumshith</i> (last night)? does this mean to say, it is this day, i.e. does he not indicate that he does not count the day from the evening? <span class=\"citation\">Y. Snh. VIII, 26ᵇ</span> top <span dir=\"rtl\">עם מאן דקדש … ר׳</span> with him who inaugurated the new month here last night.</div>","alt":["רוּ׳"]},"29153":{"h":"רמ\"ת","r":"T00840","html":"<div class=\"sense\"> a mnemotechnical word, intimating <span dir=\"rtl\">ר̇אש</span> head, <span dir=\"rtl\">מ̇עים</span> bowels, <span dir=\"rtl\">ת̇חתוניות</span> piles. <span class=\"citation\">Ber. 51ᵃ</span></div>","alt":[]},"29154":{"h":"רָמָתָא","r":"T00841","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָמָא II\"><span dir=\"rtl\">רָמָא</span> II</a></div>","alt":[]},"29155":{"h":"רְנָא","r":"T00842","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְנֵי\">רְנֵי</a></div>","alt":[]},"29156":{"h":"רנגיא","r":"T00843","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to I, 13</span> <span dir=\"rtl\">מר׳</span>, v. <a href=\"#\" data-headword=\"סְרוּנְגַּיָּיא\">סְרוּנְגַּיָּיא</a></div>","alt":[]},"29157":{"h":"רִנָּה","r":"T00844","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>chant, song</i>. <span class=\"citation\">Yoma 70ᵃ</span>; <span class=\"citation\">Sot. 41ᵃ</span>. <span class=\"citation\">Ex. R. s. 47</span> <span dir=\"rtl\">ר׳ של תורה</span>, v. <a href=\"#\" data-headword=\"רִינּוּן\">רִינּוּן</a>. <span class=\"citation\">Y. Succ. IV, 54ᵃ</span> top <span dir=\"rtl\">בר׳</span> using the verb <a href=\"#\" data-headword=\"רָנַן\">רָנַן</a>; a. fr.</div>","alt":["רִי׳"]},"29158":{"h":"רִנּוּן","r":"T00845","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִינּוּן\">רִינּ׳</a>.</div>","alt":["רִנּוּנָא"]},"29159":{"h":"רְנֵי","r":"T00846","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָנַן\">next w.</a>) <i>to think, meditate.</i> Part. <span dir=\"rtl\">רָנֵא</span>, <a href=\"#\" data-headword=\"רְנֵי\">רָנֵי</a>, <a href=\"#\" data-headword=\"רָאנֵי\">רָאנֵי</a>. <span class=\"citation\">Targ. Prov. VIII, 7</span> (some ed. <span dir=\"rtl\">דנא</span>, corr. acc.), <span class=\"citation\">Ib. XV, 28</span> <a href=\"#\" data-headword=\"רָאנֵי\">ראני</a> ed. Lag. (Var. <span dir=\"rtl\">יאני</span>, corr. acc.; ed. Wil. <a href=\"#\" data-headword=\"רָנַן\">רָנֵן</a>).</div>","alt":["רְנָא"]},"29160":{"h":"רָנַן","r":"T00847","html":"<div class=\"sense\"> (b. h.) [<i>to whiz, hum</i>,] </div><div class=\"sense\"><b>1)</b> <i>to murmur</i>, v. <a href=\"#\" data-headword=\"רוֹנָן\">רוֹנָן</a>.</div><div class=\"sense\"><b>—2)</b> <i>to rejoice</i>. <span class=\"citation\">Ab. Zar. 24ᵇ</span> <span dir=\"rtl\">רוֹנִּי וכ׳</span> rejoice, O holy ark, v. <a href=\"#\" data-headword=\"רוּם\">רוּם</a> I h.</div><div class=\"sense\"><b>Pi. רִינֵּן</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רְנֵי\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>to murmur, complain</i>. Y. Ber. IV, 7ᵈ top <span dir=\"rtl\">עד שרִינְּנוּ כל העם</span> until all the people murmured (became rebellious); Bab. <span class=\"citation\">Ber. 27ᵇ</span> <span dir=\"rtl\">שרננו</span>; Y. Taan. IV, 67ᵈ <span dir=\"rtl\">שריננו בו</span>; <span class=\"citation\">Bekh. 36ᵃ</span>. Y. Ber. IX, 14ᵇ <span dir=\"rtl\">מְרַנְּנִים אחריו</span>, v. <a href=\"#\" data-headword=\"סְפִיקוּלָא I\"><span dir=\"rtl\">סְפִיקוּלָא</span> I</a>. <span class=\"citation\">Num. R. s. 12</span><sup>7</sup> <span dir=\"rtl\">כל … לא היתה מְרַנֶּנֶת</span> as long as she was engaged in making the purple cloak, she did not grumble; <span class=\"citation\">Pesik. R. s. 5</span> <span dir=\"rtl\">מרנונית</span> (corr. acc.; Tanḥ. Naso 12 <a href=\"#\" data-headword=\"מְרִיבָה\">מריבה</a>). Num. R. l. c.; Pesik. R. l. c. <span dir=\"rtl\">ווי … וִירַּנְּנוּ כשם שהיו מרננים</span> woe, (I am afraid,) lest they will again murmur as they were wont to do. <span class=\"citation\">Midr. Till. to Ps. XXXIII</span> (ref. to <span class=\"citation\">Cant. IV, 11</span>) <span dir=\"rtl\">בין משבחת בין מרננת אל תמנעי וכ׳</span> whether praising or complaining, refrain not thy voice, for ‘thy voice is sweet’; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to sing, praise</i>. Ib. <span dir=\"rtl\">הכל מרננים צדיקים מרננים וכ׳</span> all give praise (to God), the righteous give praise, and the wicked give praise; <span dir=\"rtl\">אבל אין הרשעים מרננין וכ׳</span> but the wicked praise not until he brings plagues upon them &amp;c. Ib. <span dir=\"rtl\">הכל מרננין לפניו וכ׳</span> all sing before Him, heaven and earth sing &amp;c.; a. fr.</div></div>","alt":[]},"29161":{"h":"רְנַן","r":"T00848","html":"<div class=\"sense\"><b>1)</b> <i>to think, meditate</i>. <span class=\"citation\">Targ. Prov. XV, 28</span>, v. <a href=\"#\" data-headword=\"רְנֵי\">רְנֵי</a>. <span class=\"citation\">Targ. Ps. XXXVII, 30</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to murmur</i>. <span class=\"citation\">Targ. I Sam. II, 24</span> <span dir=\"rtl\">דרַנְנִין</span> (ed. Lag. <span dir=\"rtl\">דדננין</span>, Var. <span dir=\"rtl\">דר׳</span>, <span dir=\"rtl\">דמְרַנְּנִין</span>).</div><div class=\"sense\"><b>Pa. רַנֵּין</b> <div class=\"sense\"><b>1)</b> <i>to think, meditate</i>. <span class=\"citation\">Targ. Ps. I, 2</span>. <span class=\"citation\">Ib. XXXIX, 4</span> ברַנְּנִי Ms. (ed. <span dir=\"rtl\">ברִנְנִי</span>, <span dir=\"rtl\">ברִי׳</span>, v. <a href=\"#\" data-headword=\"רְנָנָא\">next w.</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to murmur</i>. Targ. I Sam. l. c., v. supra.—Y. Ab. Zar. III, 42ᶜ top <span dir=\"rtl\">והוו … מְרַנְּנִין ביה</span> and the scholars murmured against him (considered his conduct unbecoming). <span class=\"citation\">Yeb. 34ᵇ</span> <span dir=\"rtl\">קא מְרַנְּנֵי … אבתרך</span> the scholars speak ill of thee; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to sing, rejoice</i>. <span class=\"citation\">Targ. Ps. XIII, 5</span>, sq. <span class=\"citation\">Ib. XIV, 7</span>; a. fr.</div></div>","alt":[]},"29162":{"h":"רְנָנָא","r":"T00849","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"רְנַן\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>meditation</i>. <span class=\"citation\">Targ. Ps. XXXIX, 4</span>. <span class=\"citation\">Ib. XIX, 15</span> <span dir=\"rtl\">רִנְנַת</span> constr. (not <span dir=\"rtl\">רגגת</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>murmuring, evil talk</i>. <span class=\"citation\">Targ. Ez. XXXVI, 3</span>.</div><div class=\"sense\"><b>—3)</b> <i>song, joy, music</i>. <span class=\"citation\">Targ. Job III, 6</span>. <span class=\"citation\">Targ. Ps. XCII, 4</span>.</div>","alt":["רִנְנָא","רִי׳"]},"29163":{"h":"רְנָנָה","r":"T00850","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"רְנָנָא\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>evil talk</i>. <span class=\"citation\">Yeb. 26ᵃ</span> top (in Chald. dict.) <span dir=\"rtl\">בר׳ לא מפקינן</span> on mere talk we do not require a husband to divorce his wife.</div><div class=\"sense\"><b>—2)</b> <i>meditation; prayer; song.</i>—Pl. <span dir=\"rtl\">רְנָנוֹת</span>. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">לשונך ירחיש ר׳</span> may thy tongue be abundant in reflections. <span class=\"citation\">Ib. 29ᵃ</span> <span dir=\"rtl\">כנגד כ&quot;ד ר׳ וכ׳</span> corresponding to the twenty-four expressions for prayer which Solomon used (<span class=\"citation\">I Kings VIII, 23-53</span>); <span class=\"citation\">Sabb. 30ᵃ</span> (v. Rashi); <span class=\"citation\">Num. R. s. 14</span><sup>3</sup> (expl. in a gloss by ref. to <span class=\"citation\">II Chr. VI, 18-41</span>); <span class=\"citation\">Midr. Till. to Ps. XXIV</span>.</div>","alt":[]},"29164":{"h":"רִסָּא","r":"T00851","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְסִיסָא\">רְסִיסָא</a></div>","alt":["רִסָּה"]},"29165":{"h":"רִסּוּס","r":"T00852","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיסּוּקָא\">רִיסּ׳</a>.</div>","alt":["רִסּוּק","רִסּוּקָא"]},"29166":{"h":"רסטקאות","r":"T00853","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרַקְסָאוֹת\">טְרַקְסָאוֹת</a></div>","alt":[]},"29167":{"h":"רְסֵי","r":"T00854","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְסַס\">רְסַס</a></div>","alt":[]},"29168":{"h":"רָסִיס","r":"T00855","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>broken piece</i>.—[<span class=\"citation\">Yalk. Josh. 27</span> <span dir=\"rtl\">ברסיסי</span>, v. <a href=\"#\" data-headword=\"נָסִיס\">נָסִיס</a>.]—Pl. <span dir=\"rtl\">רְסִיסִין</span> <i>groats</i> of lentils. <span class=\"citation\">Ḥull. 6ᵃ</span></div>","alt":[]},"29169":{"h":"רְסִיסָא","r":"T00856","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָסִיס\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>structure demolished by breaches</i>, opp. <a href=\"#\" data-headword=\"בְּקִיעָא\">בְּקִיעָא</a>. <span class=\"citation\">Lev. R. s. 19</span>, v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a>; <span class=\"citation\">Koh. R. to X, 18</span>; <span class=\"citation\">Cant. R. to IV, 14</span> <a href=\"#\" data-headword=\"רִיסָּא\">רִיסָּא</a>, <a href=\"#\" data-headword=\"רִיסָּא\">רִיסָּה</a> (Ar. <span dir=\"rtl\">ריסא לית מיניה אלא רסיס</span>).</div><div class=\"sense\"><b>—2)</b> <i>drop.</i>—Pl. <span dir=\"rtl\">רְסִיסַיָּא</span>, <span dir=\"rtl\">רְסִיסִין</span>. <span class=\"citation\">Targ. Jer. III, 3</span> (h. text <span dir=\"rtl\">רביבים</span>). <span class=\"citation\">Ib. XIV, 22</span>. <span class=\"citation\">Targ. Deut. XXXII, 2</span>; a. e.</div>","alt":["רְסִיסָה"]},"29170":{"h":"רֶסֶן","r":"T00857","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>bridle</i>. <span class=\"citation\">Ex. R. s. 20</span>, beg., v. <a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>; a. e.</div>","alt":[]},"29171":{"h":"רִסְנָא","r":"T00858","html":"<div class=\"sense\"> Targ. II Esth. VI, 11.</div>","alt":["רִי׳"]},"29172":{"h":"רָסַס","r":"T00859","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָצַץ\">רָצַץ</a>), <i>Pi.</i> רִיסֵּס <i>to crush, break into small pieces</i>. <span class=\"citation\">Y. Naz. VI, 54ᵈ</span> bot. <span dir=\"rtl\">רִסְּסָן ואכלן</span> (or <span dir=\"rtl\">רְסָסָן</span>) if he chopped them (the aṇts) and ate them (v. <a href=\"#\" data-headword=\"רָסַק\">רָסַק</a>). <span class=\"citation\">Ukts. II, 5</span>, sq. <span dir=\"rtl\">עד שׁיְרַסֵּס</span> until he has cracked or broken the shell (and taken out the contents); <span class=\"citation\">Tosef. ib. II, 15</span> <span dir=\"rtl\">אע&quot;פ שרי׳ … לפרק</span> although he has cracked the shell, the connection is not considered broken until he begins to pick; <span dir=\"rtl\">וביצה טרומיטא אע&quot;פ שרי׳ וכ׳</span> (not <span dir=\"rtl\">טרמיסא</span>) and in the case of a boiled-down egg (v. <a href=\"#\" data-headword=\"*טְרוֹמִיטָא\">טרומיטא</a>) the connection remains, although he has crushed it, until he begins to peel it; a. e.—Part. pass. <span dir=\"rtl\">מְרוּסָּס</span>. <span class=\"citation\">Sabb. VIII, 5</span> <span dir=\"rtl\">אם היה עב או מר׳</span> if the reed is thick or cracked.</div><div class=\"sense\"><b>Hithpa. הִתְרוֹסֵס</b> <div class=\"sense\"><i>to be crushed, cracked</i>. <span class=\"citation\">Ḥull. 77ᵃ</span> <span dir=\"rtl\">מִתְרוֹסֵס מהו</span> if the flesh covering the wound is lacerated, how is it? <span class=\"citation\">Sot. 11ᵃ</span> (play on <span dir=\"rtl\">ר̇עמ̇ס̇ס̇</span>, <span class=\"citation\">Ex. I, 11</span>) <span dir=\"rtl\">ראשון ראשון מ̇תר̇וס̇ס̇</span> (Ar. s. v. <a href=\"#\" data-headword=\"פִּיתוֹם II\">פיתום</a>: <span dir=\"rtl\">מתמסמס</span>) one building after the other was crushed (fell in); <span class=\"citation\">Ex. R. s. 1</span>.</div></div>","alt":[]},"29173":{"h":"רְסַס","r":"T00860","html":"<div class=\"sense\"><b>1)</b> <i>to crush, crack</i>.—Part. pass. <a href=\"#\" data-headword=\"רָסִיס\">רְסִיס</a>. <span class=\"citation\">Targ. O. Lev. XXII, 24</span> (h. text <a href=\"#\" data-headword=\"כָּתִית\">כתית</a>).—<span class=\"citation\">Targ. Y. Deut. XXVIII, 33</span> רְסִיסִין Bxt. (ed. <span dir=\"rtl\">דְּרִיסִין</span>; h. text <span dir=\"rtl\">רציץ</span>).</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"עָרַף\">עָרַף</a>) <i>to distil, drop, moisten</i>. <span class=\"citation\">Targ. Prov. VII, 17</span> <span dir=\"rtl\">רַסֵּית</span>. <span class=\"citation\">Ib. III, 20</span> <span dir=\"rtl\">וענני רַסּוּ טלא</span> (or <span dir=\"rtl\">רְסוּ</span> fr. <a href=\"#\" data-headword=\"רְסֵי\">רסי</a>) Ar. (Ms. <span dir=\"rtl\">ושחקי רַסָּן</span>; ed. corrupt <span dir=\"rtl\">שמיא צעי</span> (<a href=\"#\" data-headword=\"ד\">ד</a>)<a href=\"#\" data-headword=\"מטליא\">מטליא</a>; for <a href=\"#\" data-headword=\"צָעֵי\">צעי</a>, read <span dir=\"rtl\">ענני</span> as a Var. of <a href=\"#\" data-headword=\"שְׁמַיָּא\">שמיא</a>, and for <span dir=\"rtl\">דמטליא</span> read: <span dir=\"rtl\">רסו טליא</span>). <span class=\"citation\">Targ. Y. I Deut. XXXIII, 28</span> <span dir=\"rtl\">רַסְיַין</span> (fr. <a href=\"#\" data-headword=\"רְסֵי\">רסי</a>; ed. Vien. <span dir=\"rtl\">דסיין</span>, corr. acc.).</div><div class=\"sense\"><b>Pa. רַסֵּיס</b> <div class=\"sense\"><i>to cause to drip</i>, (of a sore) <i>to run</i>. Part. pass. <span dir=\"rtl\">מְרַסַּס</span>; f. <span dir=\"rtl\">מְרַסְּסָא</span>. <span class=\"citation\">Targ. Is. I, 6</span>.</div></div><div class=\"sense\"><b>Ithpe. אִרְסִיס</b> <div class=\"sense\"><i>to be crushed</i>. <span class=\"citation\">Targ. Y. Lev. XXII, 24</span> <span dir=\"rtl\">דְּמִרְסִיס</span> (ed. Vien. <span dir=\"rtl\">דִּמְרְסִיס</span>, corr. acc.), v. supra.</div></div>","alt":[]},"29174":{"h":"רָסַק","r":"T00861","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רְסַס\">preced.</a>) <i>Pi.</i> רִיסֵּק <i>to crush, chop</i>. <span class=\"citation\">Ter. X, 2</span> <span dir=\"rtl\">תפיח שרְסָקוֹ וכ׳</span> (Y. ed. <span dir=\"rtl\">שרִיסְּקוֹ</span>) an apple chopped and put into dough; Y. Ḥall. I, beg. 57ᵃ. <span class=\"citation\">Macc. 16ᵇ</span> <span dir=\"rtl\">רי׳ תשעה וכ׳</span> if he chopped nine ants &amp;c. (v. <a href=\"#\" data-headword=\"רָסַס\">רָסַס</a>). <span class=\"citation\">Sabb. XXII, 1</span> <span dir=\"rtl\">חלות דבש שרִיסְּקָן וכ׳</span> honeycomb broken into small pieces &amp;c. <span class=\"citation\">Ukts. III, 11</span> <span dir=\"rtl\">משיְרַסֵּק</span> from the time you break (the honeycomb, to take it out of the hive). <span class=\"citation\">Sabb. XXIV, 2</span> <span dir=\"rtl\">אין מְרַסְּקִין וכ׳</span> you must not chop grass &amp;c. <span class=\"citation\">Ib. 51ᵇ</span> אין מְרַסְּקִין וכ׳ Ms. M. (ed. <span dir=\"rtl\">מְרַזְּקִין</span>) you must not crush snow or hailstones &amp;c.; a. e.</div>","alt":[]},"29175":{"h":"רְסַק","r":"T00862","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">רַסֵּיק</span> <a href=\"#\" data-headword=\"רָסַק\">same</a>, <i>to break into pieces</i>. <span class=\"citation\">Targ. Y. Lev. II, 6</span> (h. text <span dir=\"rtl\">פתות</span>).—Part. pass. <span dir=\"rtl\">מְרַסַּק</span>; f. <span dir=\"rtl\">מְרַסְּקָא</span>. <span class=\"citation\">Ib. VI, 14</span>.</div>","alt":[]},"29176":{"h":"שְׁבוּבְאֵל","r":"U00072","html":"<div class=\"sense\"><i>Sh’bubel</i>, secondary substitute for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a>, v. <a href=\"#\" data-headword=\"שְׁבוּאֵל\">preced.</a></div>","alt":[]},"29177":{"h":"שִׁבּוּחָא","r":"U00073","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שֵּׁיבָבָא\">שִׁיבּ׳</a>.</div>","alt":["שִׁבּוּטָא"]},"29178":{"h":"שָׁבוּי","r":"U00074","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁבָה\">שָׁבָה</a></div>","alt":[]},"29179":{"h":"שַׁבּוֹיָא","r":"U00075","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁבָּאָה\">שַׁבָּאָה</a></div>","alt":["שַׁבּוֹיָיא"]},"29180":{"h":"שְׁבוֹיָיתָא","r":"U00076","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁבְיְיתָא\">שִׁבְיְיתָא</a></div>","alt":["שְׁבוֹיָיתָא"]},"29181":{"h":"שִׁבּוּלָא","r":"U00077","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שֵּׁיבָבָא\">שִׁיבּ׳</a>.</div>","alt":["שִׁבּוֹלֶת","שִׁבּוּלְתָּא"]},"29182":{"h":"שָׁבוּעַ","r":"U00078","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>a period of seven days, week</i>.—<span dir=\"rtl\">שְׁבוּעַ הַבֵּן</span>, v. <a href=\"#\" data-headword=\"בֵּן\">בֵּן</a>.—Pl. <span dir=\"rtl\">שָׁבוּעוֹת</span>. <span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">שבע ש׳ שבין וכ׳</span> the seven weeks between Passover and the Feast of Weeks; a. e.</div><div class=\"sense\"><b>—2)</b>  “<i>year-week</i>”,<i> a period of seven years, septennate</i> (the jubilee being divided into seven septennates); also <i>the seventh year, Sabbatical year</i>. <span class=\"citation\">Snh. V, 1</span>, v. <a href=\"#\" data-headword=\"חֲקִירָה\">חֲקִירָה</a>. <span class=\"citation\">Gitt. 77ᵃ</span> <span dir=\"rtl\">לאחר ש׳ שנה</span> if a person says, ‘give my wife a letter of divorce (or to his wife, ‘be thou divorced’), if I do not come back after the septennate’, we must wait one year (after the Sabbatical year). <span class=\"citation\">Ned. VIII, 1</span> <span dir=\"rtl\">ש׳ זה אסור בכל הש׳ וכ׳</span> (not <span dir=\"rtl\">השבועה</span>) if a person, during a Sabbatical year, vows abstinence, using the word ‘this <i>shabu‘a</i>ʾ, he is bound the entire coming septennial period and the seventh year of the expiring Sabbatical period. Ib. <span dir=\"rtl\">ש׳ אחד אסור וכ׳</span> but if he says, ‘one septennate’, he is bound from date to date, i.e. counting seven years from the day of the vow; a. fr.—<i>Pl.</i> as ab. Y. Sabb. X, 17ᵃ top <span dir=\"rtl\">אי אפשר לשני ש׳ שלא חל וכ׳</span> it is not possible that during fourteen years the fourteenth day of Nisan should not occur on a Sabbath; <span class=\"citation\">Y. Pes. VI, 33ᵃ</span> bot. <span dir=\"rtl\">לשני שביעית שיחול</span> (corr. acc.).</div>","alt":[]},"29183":{"h":"שָׁבוּעָא","r":"U00079","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, <i>week</i>. <span class=\"citation\">Targ. O. Gen. XXIX, 27</span>, sq. ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"שְׁבוּעָא\">שְׁבוּעֲתָא</a>; ed. Ven. <span dir=\"rtl\">עָתָא …</span>). <span class=\"citation\">Targ. Lev. XXIII, 16</span>. <span class=\"citation\">Targ. Job I, 4</span> דשבעתא Ms. (ed. <a href=\"#\" data-headword=\"שַׁבְעָא\">שַׁבְעָא</a>). <span class=\"citation\">Ib. 13</span> שבע׳ Ms. (ed. <span dir=\"rtl\">שבוע׳</span>); a. e.—Pl. <span dir=\"rtl\">שָׁבוּעִין</span>, <span dir=\"rtl\">שָׁבוּעַיָּא</span>, <span dir=\"rtl\">שָׁבוּעֵי</span>; <a href=\"#\" data-headword=\"שְׁבוּעָא\">שְׁבוּעָן</a>. <span class=\"citation\">Targ. Deut. XVI, 9</span>, sq. <span class=\"citation\">Targ. Lev. XXIII, 15</span>; a. e.—Meg. Taan. ch. I; <span class=\"citation\">Taan. 17ᵇ</span>; <span class=\"citation\">Men. 65ᵃ</span> <span dir=\"rtl\">חגא דש׳</span> the Feast of Weeks. <span class=\"citation\">Ib. 66ᵃ</span> <span dir=\"rtl\">מצוה למימני … ש׳</span> it is proper to count (the ‘Omer) by days and by weeks; <span class=\"citation\">Ḥag. 17ᵇ</span>; <span class=\"citation\">R. Hash. 5ᵃ</span>; a. e.</div>","alt":["שְׁבוּעַתָּא","שְׁבַעְתָּא"]},"29184":{"h":"שְׁבוּעָא","r":"U00080","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"שְׁבוּעָה\">next w.</a> <span class=\"citation\">Targ. Y. I Deut. XXXII, 40</span> (ed. Vien. <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a> h. form; Y. II <a href=\"#\" data-headword=\"שְׁבוּעֲיָיא\">שְׁבוּעֲיָיא</a>). <span class=\"citation\">Targ. Ps. X, 12</span>. <span class=\"citation\">Targ. Jud. XXI, 5</span>; a. e.—<span class=\"citation\">Shebu. 26ᵃ</span> ש׳ דהכי אמר רב I take an oath on it that Rab said thus. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שְׁבוּעֲתֵיה דכיר ליה</span> he remembers his oath. <span class=\"citation\">B. Mets. 5ᵇ</span>, a. fr. <span dir=\"rtl\">חשיד אש׳</span>, v. <a href=\"#\" data-headword=\"גֵּו\">גֵּו</a> ch. <span class=\"citation\">Lev. R. s. 29</span> (play on <span dir=\"rtl\">בחדש השביעי</span>, <span class=\"citation\">Lev. XXIII, 24</span>) <span dir=\"rtl\">ר׳ … ירחא דשְׁבוּעֲתָה וכ׳</span> R. B. called it the month of the oath, for in it the Lord swore unto Abraham &amp;c.; Pesik. Baḥod., p. 154ᵃ; a. fr.</div>","alt":["שְׁבוּעֲתָא"]},"29185":{"h":"שְׁבוּעָה","r":"U00081","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>oath</i>. <span class=\"citation\">Shebu. III, 1</span> <span dir=\"rtl\">ש׳ שאוכל וכ׳</span> if he says, I swear that I will eat, or, that I shall not eat &amp;c. <span class=\"citation\">Ib. 32ᵇ</span> <span dir=\"rtl\">חזרה ש׳ למחוייב וכ׳</span> the oath goes back to (is thrown again on) him who is bound to make it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל המחוייב ש׳ וכ׳</span> whoever would, according to law, be bound to make oath, and is disqualified from doing so, must pay; a. fr.—<span dir=\"rtl\">שְׁבוּעַת ביטוי</span>, <span dir=\"rtl\">ש׳ שוא</span>, <span dir=\"rtl\">ש׳ היסת</span>, <span dir=\"rtl\">ש׳ הפקדון</span> &amp;c., v. <a href=\"#\" data-headword=\"בִּיטּוּי\">בִּיטוּי</a>, <a href=\"#\" data-headword=\"שָׁוְא\">שָׁוְא</a>, <a href=\"#\" data-headword=\"הֶיסֵּת\">הֶיסֵּת</a>, <a href=\"#\" data-headword=\"פִּקָּדוֹן\">פִּקָּדוֹן</a>, &amp;c.—<span dir=\"rtl\">שבועת הדיינין</span> the oath imposed by the judges, legal oath. <span class=\"citation\">Ib. VI, 1</span> Y. a. Bab. (Mish. <i>pl.</i>); a. fr.—<i>Pl.</i> <span dir=\"rtl\">שְׁבוּעוֹת</span>. Ib. I, 1 <span dir=\"rtl\">ש׳ שתים שהן ארבע</span> the transgressions in cases of oaths are of two classes, subdivided into four. Ib. 25ᵃ <span dir=\"rtl\">חומר בנדריס מבש׳ וכ׳</span> there are restrictions in vows which do not apply to oaths &amp;c.; <span dir=\"rtl\">שהש׳ חלות וכ׳</span> inasmuch as oaths may refer to things unsubstantial as well as to things substantial; <span class=\"citation\">Tosef. Ned. I, 5</span>; a. fr.—<i>Sh’buoth</i>, name of a treatise, of the Order of N’ziḳin, of Misnah, Tosefta, Talmud Babli a. Y’rushalmi.</div>","alt":[]},"29186":{"h":"שְׁבוּעֲיָיא","r":"U00082","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁבוּעָא\">שְׁבוּעָא</a></div>","alt":[]},"29187":{"h":"שְׁבוּעַתָּא","r":"U00083","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁבוּעָא\">שָׁבוּעָא</a>, <a href=\"#\" data-headword=\"שְׁבוּעָא\"><a href=\"#\" data-headword=\"שְׁבוּעָא\">שְׁבוּעָא</a>.</a></div>","alt":["שְׁבוּעָתָא","שְׁבוּעֲתָא","שְׁבוּעֲתָה"]},"29188":{"h":"שְׁבוֹקָא","r":"U00084","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, constr. <span dir=\"rtl\">שְׁבוֹק</span> (<a href=\"#\" data-headword=\"שְׁבַק\">שְׁבַק</a>) <i>remission</i> (of taxes). <span class=\"citation\">Targ. Esth. II, 18</span>.</div>","alt":[]},"29189":{"h":"שִׁבּוּקָא","r":"U00085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיבּוּקָא\">שִׁיבּוּקָא</a></div>","alt":[]},"29190":{"h":"שְׁבוּקָה","r":"U00086","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>sh’buḳah</i>, a substitute for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a> (v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>). <span class=\"citation\">Y. Ned. I, 37ᵃ</span> top.</div>","alt":[]},"29191":{"h":"שָׁבוֹר","r":"U00087","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Shabor</i> (<i>Sapor</i> I), king of Persia, friend of Samuel. <span class=\"citation\">Ber. 56ᵃ</span>.—Trnsf. a surname of <i>Samuel</i>, and of <i>Raba</i> as influential men. <span class=\"citation\">B. Bath. 115ᵇ</span>; <span class=\"citation\">Pes. 54ᵃ</span> אמינא מילתא דש׳ מלכא … ומנו שמואל I will say something which king Shabor could not say; and who is meant by that? Samuel; ib. <span dir=\"rtl\">ומנו רבא</span>; B. Bath. l. c. <a href=\"#\" data-headword=\"רַבָּה I\">רבה</a> (Ms. M. <a href=\"#\" data-headword=\"רְבֵי\">רבא</a>); <span class=\"citation\">Yalk. Num. 774</span>.</div>","alt":[]},"29192":{"h":"שִׁבּוּר","r":"U00088","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיבּוּר\">שִׁיבּוּר</a></div>","alt":[]},"29193":{"h":"שבורה","r":"U00089","html":"<div class=\"sense\">, <span class=\"citation\">Y. Orl. I, 60ᵈ</span> bot., v. <a href=\"#\" data-headword=\"שְׁבִירָה\">שְׁבִירָה</a></div>","alt":[]},"29194":{"h":"שִׁבּוּשׁ","r":"U00090","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיבּוּשׁ\">שִׁיבּוּשׁ</a></div>","alt":[]},"29195":{"h":"שְׁבוּת","r":"U00091","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁבַת\">שָׁבַת</a>) <i>rest, abstention from secular occupation</i>. <span class=\"citation\">Sabb. 89ᵃ</span> <span dir=\"rtl\">כלום … שאתם צריכים ש׳</span> do you (angels) work, that you needed rest? [Sifra Emor ch. XIII, Par. 11, a. e. <span dir=\"rtl\"><a href=\"#\" data-headword=\"ש׳\">ש׳</a> (<a href=\"#\" data-headword=\"אֲלָא I\">אלא</a>) <span dir=\"rtl\">שבתון</span></span>, read: <a href=\"#\" data-headword=\"שְׁבוּת\">שְׁבוֹת</a>, v. <a href=\"#\" data-headword=\"שָׁבַת\">שָׁבַת</a>.]—Esp. <i>sh’buth, an occupation, on the Sabbath and Festivals, forbidden by the Rabbis as being out of harmony with the celebration of the day</i>. <span class=\"citation\">Bets. V, 2</span> <span dir=\"rtl\">כל שחייבין עלין משום ש׳ וכ׳</span> all occupations which are forbidden as <i>sh’buth</i> … on the Sabbath, are also forbidden on the Holy Days; <span dir=\"rtl\">ואלו הן משום ש׳ וכ׳</span> and these are forbidden as <i>sh’buth</i>: you must not climb up a tree &amp;c. Ib. 37ᵃ <span dir=\"rtl\">ש׳ גרידתא</span> a plain act forbidden as <i>sh’buth;</i> <span dir=\"rtl\">ש׳ דרשות</span> an act of exercise of authority; <span dir=\"rtl\">ש׳ דמצוה</span> an act of a religious nature. <span class=\"citation\">Pes. 65ᵃ</span> <span dir=\"rtl\">אין ש׳ במקדש</span> the prohibition of acts as <i>sh’buth</i> does not apply to Temple functions; a. v. fr.</div>","alt":[]},"29196":{"h":"שְׁבוּתְאֵל","r":"U00092","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sh’buthel, sh’buthiel</i>, a secondary substitute for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a>. <span class=\"citation\">Ned. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"שְׁבוּאֵל\">שְׁבוּאֵל</a>.</div>","alt":["שְׁבוּתִיאֵל"]},"29197":{"h":"שְׁבוּתָה","r":"U00093","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>sh’buthah</i>, a substitute for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שְׁבוּעָה</a> (v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>). <span class=\"citation\">Ned. I, 2</span>; a. e.—Y. ib. 37ᵃ top <span dir=\"rtl\">ש׳ שביתה שמה</span> (not <a href=\"#\" data-headword=\"שפותה\">שפותה</a>) <i>sh’buthah</i> may have the meaning of <i>rest</i> (besides a disguise for <a href=\"#\" data-headword=\"שְׁבוּעָה\">שבועה</a>).</div>","alt":[]},"29198":{"h":"*שְׁבַז","r":"U00094","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בְּזַז I\">בְּזַז</a>, <a href=\"#\" data-headword=\"*בִּיזְיָא\">בִּיזְיָא</a>) <i>something brittle, rotten</i>. <span class=\"citation\">Targ. Is. V, 24</span> (h. text <span dir=\"rtl\">מק</span>; LXX χνοῦς; Pesh. <a href=\"#\" data-headword=\"חָלָא I\">חלא</a>).</div>","alt":[]},"29199":{"h":"שַׁבְזֵז","r":"U00095","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of a <i>jewel, sapphire</i>. <span class=\"citation\">Targ. O. Ex. XXVIII, 18</span> (Ms. II <a href=\"#\" data-headword=\"שַׁבְסֵיס\">שבסיס</a>); <span class=\"citation\">XXXIX, 11</span> (h. text <a href=\"#\" data-headword=\"אספר\">ספיר</a>). <span class=\"citation\">Targ. Y. Num. II, 10</span>. <span class=\"citation\">Targ. Ez. XXVIII, 13</span>. <span class=\"citation\">Targ. Job XXVIII, 6</span>; <span class=\"citation\">16</span>. <span class=\"citation\">Targ. Lam. IV, 7</span>.—Pl. <span dir=\"rtl\">שַׁבְזִיזִין</span>. <span class=\"citation\">Targ. Cant. V, 14</span>.</div>","alt":["שַׁבְזֵיז","שַׁבְזִיזָא"]}};
